/* 平成24年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h24.committeeSessions.push(...[{"id":"h24-20121002-4","meetingId":"h24-c-settlement","date":"2012年10月2日","dateIso":"2012-10-02","committee":"決算特別委員会","time":"午前１０時００分～午後５時５７分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を167件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"渡部副委員長","kind":"質問・要望","question":"第１項、理事および理事会の設置についてです。閉会予定時間は、区役所の執務時間と同じく、午後５時１５分を目途といたします。一人当たりの質問時間は、答弁時間を含めて、１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。経過時間のお知らせにつきましては、残り時間がなくなった時点で、振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"}]},{"id":"topic-02","title":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、平成２３年度品川区一般会計歳入歳出決算","agenda":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、平成２３年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"おはようあります。お願いをいたします。順番を変えて、９６ページの子宮頸がん等予防接種補助金の質問をまず最初にさせていただきたいと思います。この上で、まず歳入の中で、ここの定期予防接種に関して、歳入の項目、これが入っていないのは、あえてちょっと確認がてらご答弁いただきたいと思います。","respondent":"伊津野保健予防課長","answer":"定期予防接種につきましては、予防接種法において区市町村の実施主体ということになっておりますので、国から等の負担金や補助金はありませんので、ここには載せておりません。","voiceIndex":15,"id":"exchange-002"},{"speaker":"大沢委員","kind":"確認","question":"ここには載せてないということは、一般財源ということで、これは、一般財源という部類の手当てでいいのかということを確認をさせてください。","respondent":"伊津野保健予防課長","answer":"はい、一般財源で賄われる事業であります。","voiceIndex":17,"id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"区市町村が行う事業ということでちょっとお伺いをしたんですけれども、この件について私は納得がいかないところがありまして、本来であれば国民の健康を保持する、守るという見地の上において、なぜこの事業、国の名のもとにおいて行われないのか。なぜ区の一般財源でこれが行われているのかということに非常に矛盾を感じるんですけれども、そこのところはどのようにお考えになっておりますでしょうか。","respondent":"伊津野保健予防課長","answer":"ただ、今までは予防接種の数も少なかったので、それで賄われてきたんですが、今後、予防接種の数も種類も増えてきておりますので、これにつきましては、いろんな意味で検討が必要な課題かと考えています。","voiceIndex":19,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問・要望","question":"ここの部分に関して、先ほどもちょっとお話をさせていただきましたけれども、補正予算でポリオ、生ワクチンから不活化ワクチンということで、２億１,０００万円余の補正予算が組まれたということで、これも区の一般財源ということで賄われたということですけれども、この件に関して、区では都とか国に対して財源確保という意味で何か働きかけというか、活動やっていないんでしょうか。","respondent":"本城企画財政課長","answer":"財源確保に関してですが、今委員のほうからお話ございましたように、予防接種については基本的には国の責任を持ってということで、特別区長会のほうからも国に対して全額国で負担をするということで要望を出させていただいているところです。","voiceIndex":21,"id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"今までの財源確保という流れの中で、ただ単に要望を出させていただいたという、今１点だけですけれども、これ、非常に今後定期予防接種が、区で行われる種類が増えてくるということになると、この取り組みを一層もっと強めなければいけないと思うんですけれども、ここの部分に対して、歳入確保、先ほど来何回もお話をしておりますように、歳入確保という意味で十分に、これ。","respondent":"本城企画財政課長","answer":"そういう意味で、特別区長会、そして全国市長会も含めて、すべて区市町村サイドからの要望として今後も強く国に対してきちんと要望していくという覚悟です。","voiceIndex":23,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"これについてどのようにお考えになりますでしょうか。","respondent":"本城企画財政課長、濱野区長","answer":"特別区としては最善の努力を尽くしていきますとともに、すべての全国区市町村とも連携を強めながら、今後とも強く要望していくところです。いわゆる医療費の低減ということで言えば、国全体の社会保障費の低減につながるわけでありますので、これを一般財源で区市町村がすべてを負担するというのは筋違いだと考えていますので。","voiceIndex":25,"id":"exchange-007"},{"speaker":"大沢委員","kind":"質問・要望","question":"区長会からということで、私は、返す返すですが、議会からも何か発信をすべきではないかと。議会から発信をどうすればいいか。そのための情報というか、行政側からのこの件についての情報が私どもにとって余りにも薄いように思われますが、その点について私たちに行政側からこの件に関して投げかける情報の多さ、少なさについてどのように考えていらっしゃるか、教えていただきたいと思います。","respondent":"日下部企画部長","answer":"ですから、そういった点では、情報をしっかりとこれからも議会のほうにもお伝えをする。それから、それを踏まえて、議会と私ども、区のほうが一緒に連携をして、きちんと国庫負担が実現できるまで、ともに頑張り、努力をしてまいりたいと、このように考えております。","voiceIndex":28,"id":"exchange-008"},{"speaker":"大沢委員","kind":"質問・要望","question":"これは要望させていただきたいと思います。次に、８３ページ、武蔵小山創業支援センターについてお伺いをいたします。これが３万１,０００円の家賃で、補助金が９万３,０００円。上に施設の貸し出し云々という話がありますけれども、今出した数字を兼ねても、約４５０万円とすると、どうも符合しない部分があるんですけれども、そこの細かいところがおわかりになるでしょうか。教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"武蔵小山創業支援センターですが、確かに１階部分のチャレンジショップにつきましては３店舗です。それ以外に６階に事務所の貸し出し部分としまして８室あります。さらに会議室の貸し出しも行っていますし、また、２階、３階部分には認証保育所が入ってあります。","voiceIndex":30,"id":"exchange-009"},{"speaker":"大沢委員","kind":"質問・要望","question":"そうなると、この記載の方法なんですけれども、この部分だと、今、認証保育所とおっしゃいましたけれども、これではわからないと思うんですね。それで、今、私、約４５０万円ということで出したんですけれども、そこら辺の処理の仕方というか、記述の仕方について何かご感想があったらお聞かせいただきたいと思います。","respondent":"本城企画財政課長","answer":"報告書への記載の方法ということで関連すると思いますが、これについては幾つかの施設、関連する場合、一番大きな重立ったところについて記載表示するというで、書かせていただいているということでご理解いただければと思います。","voiceIndex":32,"id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"書かせていただいているということで、決まりはないわけですね。ご理解できないから今聞いているわけでありまして、ここの部分、何でしょうか、もうちょっと僕は工夫の一興があるのではないかなと思うんですけれども、どういうふうにお考えになりますか。","respondent":"本城企画財政課長","answer":"そういう意味で、今の表示が他の施設も含めてということで少しわかりづらいところになっているところが確かにあると思いますので、このあたり、工夫をしまして、わかりやすい報告書づくりに努めてまいりたいと思います。","voiceIndex":34,"id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"時間も限られてきました。ちょっと簡単に聞かせていただきますけれども、ここの部分については創業支援ということで、基本１年間。それと、あるいは、まだ居すわっているというか、ずっと長く継続でいる、どういう傾向があるのか教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"１階のチャレンジショップ、３店舗ですけれども、こちらにつきましては、現在のところ、創設以来ずっと入っている状態です。ただ、今年いっぱいで１店舗が巣立つといいますか、拡大していくということになってあります。","voiceIndex":36,"id":"exchange-012"},{"speaker":"大沢委員","kind":"意見","question":"創設以来２店舗はそのままということで、これ、近隣の家賃の格差というか、あそこら辺、とても３万１,０００円で借りられるような場所ではないんですが、そこのところ、借りる側も非常に知識が豊富になっておりますので、公平公正な制度でお願いしたいんですけれども、どういうふうに思いますか。","respondent":"福島ものづくり・経営支援課長","answer":"公正となるように今後も努めていきたいと思います。","voiceIndex":38,"id":"exchange-013"},{"speaker":"鶴委員","kind":"質問・要望","question":"私のほうからは、８２ページ、シルバーセンター使用料、それから８４ページ、ロケーション・写真撮影等、ちょっと時間があれば、８５ページ、住民基本台帳証明手数料に行きたいと思います。最初に８２ページ、シルバーセンター使用料ですけれども、６８.８％の収入率ということで、平成２２年度は８３.９６％ということになりますけれども、収入率が低かった理由をまず最初に教えていただきたいと思います。","respondent":"早津健康福祉事業部長","answer":"シルバーセンターの収入率、低かったですが、震災等の影響があらわれているものと考えております。","voiceIndex":41,"id":"exchange-014"},{"speaker":"鶴委員","kind":"質問・要望","question":"大きい視野ではそうだと思います。後でわかればまた教えてください。過去の答弁見ますと、シルバーセンター全体としては、本来目的の部分については、魅力あふれるシルバーセンターづくりということでご答弁ありまして、今年度も含めていろいろ種々さまざま進んでおります。その上で、目的外使用、これ、幾つかあると思いますけれども、その主なものを教えていただきたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"目的外使用のご質問ですが、こちらにつきましては、町会ならびに企業の方々の使用が重立った内容です。","voiceIndex":43,"id":"exchange-015"},{"speaker":"鶴委員","kind":"質問・要望","question":"目的外使用、数字で見ても幾つかわかります。それで、その中で、目的外使用される団体で、例えば町会とかは５割減免、それから、高齢者関係の福祉団体が無料ということで聞いております。その上で、シルバーセンター、幾つかありますけれども、その中でカラオケ施設というのは、全部に配備をされているかどうか、これ、ちょっと教えていただきたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"カラオケ施設ですけれども、ほとんどのシルバーセンターのほうに配備をしています。なお、６０歳以上の方が利用ということで、団体貸し出しのみということでもって、日中だけ貸し出しです。","voiceIndex":45,"id":"exchange-016"},{"speaker":"鶴委員","kind":"質問・要望","question":"後で教えてください。もう１個要望が、この項目の件ですけれども、予算書では各館ごとで何回幾らとかって、こう出ています。決算書のほうも、個別で出ていると詳細に検討できる、審査できると思いますが、これも要望しますので、お願いしたいと思います。平成２０年度から約２０％ずつアップしてきていると聞いておりますけれども、やはり平成２３年度は、大震災の影響でしょうか、その辺を教えてください。","respondent":"小林土木管理課長","answer":"その金額も、３７８万円ほどから２８６万円ほどと、減少傾向が見られております。","voiceIndex":47,"id":"exchange-017"},{"speaker":"鶴委員","kind":"提案","question":"これ、ちょっと今後、この後は提案も含めてなんですけれども、平成２４年度の予算特別委員会のときも触れましたけれども、ＮＨＫの「梅ちゃん先生」の推進委員会、これ、議会も含めて行政側も一体となって推進をしていったということで、この間、最終回を観る会、私、行ってきました。それについて、引き続き収入増を図る上から何か新しい動き、今あるのかどうか、この辺を教えてください。","respondent":"米田商業・観光課長","answer":"ただいまご質問のありました品川、大田の連携協議会ですけれども、今年度も継続しております。","voiceIndex":49,"id":"exchange-018"},{"speaker":"鶴委員","kind":"提案","question":"で、そのタケノコを特産品として貧困から救ったのが、ご存じのとおり廻船問屋の山路次郎兵衛であって、アイデアなんだけれども、品川音頭にも、品川自慢は何がある、花と緑と海がある、こういう歌詞もあるとおり、ロケーション収入増を図るために、このタケノコとか、海つながりで廻船問屋というところで、山路次郎兵衛さんを題材とした脚本をお願いするなどやってみたらどうかなと思いますけれども。","respondent":"米田商業・観光課長","answer":"そういうような各地の売りというものを観光の面にうまくつなげていけるという中で、ご提案のありましたもの、なかなか難しい状況ではありますが、いろいろ検討の素材に含めてまいりたいと思います。","voiceIndex":51,"id":"exchange-019"},{"speaker":"鶴委員","kind":"質問・要望","question":"それから最後、時間のある限り、８５ページの住民基本台帳証明手数料に行きたいと思います。ちょっとこれ、この後質問することに関連しますので、住民票の写しですとか、そうした事務手数料、１件発行当たりの人件費とか、この辺もしわかれば教えていただきたいと思います。","respondent":"井浦戸籍住民課長","answer":"住民票の１件当たりの人件費等々ということのお尋ねです。人件費につきましてはさまざまな手法での積算、算定ということがあるんですが、大体大ざっぱに７００円ないしは８００円というふうに考えてあります。","voiceIndex":53,"id":"exchange-020"},{"speaker":"鶴委員","kind":"質問","question":"そういう意味でも、今の人件費に絡めてですけれども、渋谷区ではコンビニでは発行手数料２５０円、窓口は３００円と、こうなっている。人件費削減と区民の利便性向上という観点で、品川区もそろそろ導入したらどうかと思いますけれども、いかがでしょうか。","respondent":"井浦戸籍住民課長","answer":"ただ、普及状況としましては、全国で４４自治体にとどまっているということと、渋谷区、葛飾区にお聞きしましても、昨年ベースで、利用率といいますか、コンビニの率が１.５％から２％弱ということもありますので。","voiceIndex":55,"id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"その内容とまず効果についてお伺いします。","respondent":"伊崎待機児童対策担当課長","answer":"数的なものといたしましては、平成２２年度の実績から申し上げますと、今申し上げましたすべての事業での対応を入れまして、平成２２年度に４２０人の枠の拡大、平成２３年度には５９４人の枠の拡大を行いました。","voiceIndex":58,"id":"exchange-022"},{"speaker":"藤原委員","kind":"質問・要望","question":"さまざまな施策をしていただいて、待機児が減っているということは私も認識をしておるんですが、待機児数に関して、平成２１年４月が１２３人で、平成２４年４月にはたしか５０人という形で半分以下になっていると思うんですが、やはりこれだけの対策をしても待機児がゼロにはなりませんよね。このように待機児がゼロにならないというのを区側としてはどういうふうに分析しているでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"保育園の入園は措置ではございませんので、あくまでも保育園入園を希望する方のご希望を優先をしてやっている関係上、バランスをとっていくのが難しいと考えております。","voiceIndex":60,"id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう１点、この読み方というか、これ、シュッセイリツなんでしょうか、シュッショウリツなんですか。どっちが正しいのか教えていただきたいのと、それともう１点、出生数と出生率という、二つの言葉、保育の観点で出てくると思うんですけれども、その辺の結びつきといいますか、観点について説明していただけますか。","respondent":"伊崎待機児童対策担当課長","answer":"それからもう５年がたっておりますので、現在、乳幼児人口を含めた人口動向については、人口動向調査ということで行っております。ですので、その結果を見まして、今後の対策をいつ、どのように進めていけばいいかということを検討していきたいと考えております。","voiceIndex":62,"id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"お金についてお伺いします、ちょっと変えて。開設経費だけでもかなりの経費が投じられていると思うんですけれども、まずどのぐらいの金額になるのかということと、その中で、国や都の補助金と区の負担の割合はどうですかということ。９３ページの民生費補助金のどこに各当するのか、お尋ねします。","respondent":"伊崎待機児童対策担当課長","answer":"開設の経費ですけれども、主なところで、私立保育園の開設経費についてご説明をいたしますと、平成２３年４月に開設をしました６園、認可保育園６園開設をしたところですが、そちらにつきましては、総額で４億１,０３２万円余の補助金が出ております。","voiceIndex":66,"id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"そうすると、国や都からの補助金だけではなく、品川区民の税金が大分投じられているということなんですけれども、経費に占める利用者に負担をしていただいている保育料はどのぐらいなのかということと、それと一般的に国の示している基準というのはどのぐらいか、教えてください。","respondent":"伊崎待機児童対策担当課長","answer":"平成２３年度の決算数字ですけれども、全体の運営経費の中で利用者の方の負担が占める割合、経費ですが、１４.８％です。","voiceIndex":68,"id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"最後に、ここでこういうふうにつながってくると思うんですけれども、改めて今回の保育料改定の考え方を最後に教えてください。","respondent":"立川保育課長","answer":"今回の改定の基本的な考え方というのは、こうした経費の負担増、保育園運営経費の負担増の中で、実際に利用している方に少しでも区が肩がわりしている分について、正常なというか、適正な受益者負担というところで考えたです。","voiceIndex":72,"id":"exchange-027"},{"speaker":"木村委員","kind":"質問・要望","question":"歳入の８３ページの下のほうにあります土木使用料３０億４,８７３万円余の道路占用料１１億７８０万円余についてお伺いいたします。この道路占用料が土木使用料の中で３分の１以上に当たる１１億７８０万円余ということで、この道路占用料の占用とはどのようなことなのか、おさらいの意味を込めてご説明をいただきたいと思います。","respondent":"小林土木管理課長","answer":"その種類等は道路占用料等徴収条例別表に列記されておりますが、その主なものといたしまして、お手元、成果報告書８３ページ、電柱から鉄道および軌道等の９項目に整理してご覧いただいているところです。","voiceIndex":75,"id":"exchange-028"},{"speaker":"木村委員","kind":"質問","question":"基本的には占用料とは何を基準として、そして何を根拠に料金を決めているんでしょうか。そして、この道路や法定外公共物占用料の増減は何にこれから一番大きく左右されるとお考えでしょうか。","respondent":"小林土木管理課長","answer":"したがって、占用料の増減に影響が大きい要素といたしましては、地価の動向と占用物件の増減、申請件数の増減によるところです。","voiceIndex":77,"id":"exchange-029"},{"speaker":"木村委員","kind":"質問","question":"ここしばらくは安定した歳入増になっていますが、ここ数年の習性として、将来的にはこの歳入の見込みはどのように変化していくと読んでいるでしょうか。","respondent":"小林土木管理課長","answer":"平成２２年度に増加率が大きいのは、３年に１度の改定が実施された影響です。今後の見込みといたしましては、地価動向が下落傾向ですので、これを反映いたしまして、占用料も長期的には横ばいからやや減少傾向に転換するものと予想しております。","voiceIndex":79,"id":"exchange-030"},{"speaker":"木村委員","kind":"質問","question":"電柱類、それから埋設管路、ガス管とか、あと地下埋蔵物、何ていうんでしょうか、埋設物など、いろいろあることがよくわかりますけれども、電柱は実際わかっていたんですけれども、それに電線、まあ、電線までとは思いませんでしたけれども。徴収できないものも何かあるのかわかりませんけれども、道路占用で何か代表的なものがありましたら、まず教えてください。","respondent":"小林土木管理課長","answer":"特に電柱関係で徴収できないというものにはございませんが、あえて言えば、先ほどご説明しました地下占用の中での公共企業体の占用について減免の規定があるにとどまるかと思います。","voiceIndex":81,"id":"exchange-031"},{"speaker":"木村委員","kind":"質問","question":"例えば区道は区に入るわけですけれども、都道は第二建築事務所に入ると。そして国道は東京国道事務所に入るとお聞きしました。区、都、国への占用料は均一に入るのかどうか。それとも違いがあるのでしたら、どこが一番多く占用料が入るのか、国なのか、都なのか、区なのか、教えてください。","respondent":"小林土木管理課長","answer":"その占用料の算定はそれぞれが行っておりまして、品川区ですと、品川区の土地価格で算定いたしますけれども、例えば東京都は何区分かに分けて広域で設定しますので、それぞれ基礎とする単価が異なってまいります。","voiceIndex":83,"id":"exchange-032"},{"speaker":"木村委員","kind":"質問","question":"まあ、大体わかりました。それと、先ほど電話柱という言葉が出てきましたけれども、電柱と電話柱、もちろん電気を流す電柱、そして、電話回線のこの電話柱でありますけれども、１本につき第１種、第２種、第３種といろいろ分けてあるんでしょうけれども、値段が違うということも聞きました。もしくは入ってくるのであれば、今現在の地上にあるものと地中に入っているものとの違いがあったら教えてください。","respondent":"小林土木管理課長","answer":"電柱、電話柱の料金の違いですけれども、区分ごとの占用料は、電柱が１種、２種、３種の順にそれぞれ６,５７０円、１万２００円、１万３,９００円と。電話柱のほうが、それぞれ３,７４０円、６,０４０円、８,３２０円となっております。","voiceIndex":85,"id":"exchange-033"},{"speaker":"木村委員","kind":"質問","question":"次の８４ページになろうかと思いますけれども、法定外公共物占用料というのがありますけれども、この中にガス管とか電柱、鉄道などがあります。道路占用料にもあります足場、それから仮囲だとか、危険防止施設、あと、法定外公共物占用料にもありますけれども、囲込、何を基準にして、そして何平米で、月または年間単位で計算されているのでしょうか、わかりやすくちょっとご説明を願います。","respondent":"小林土木管理課長","answer":"それと、法定外公共物で、その一部を囲い込み、いわゆる敷地と一体的に利用しているような例もあります。極めて例外的なものですけれども、その場合は１平方メートル当たり月額４１７円の占用料が課されるものです。","voiceIndex":89,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、７６ページの特別区交付金、１０１ページの繰入金について伺いたいと思います。基金残高も約６９４億円と前年よりも増加です。疑問なのは、区民生活は一段と苦しくなり、経済はしぼみ、財調交付金もマイナス１１億円の中、なぜ品川区は健全財政を維持・成長できるのかということです。区は行革の徹底と説明いたしますけれども、そのやりくりやこつは何なのか、ご説明いただきたいと思います。","respondent":"本城企画財政課長","answer":"予算編成に当たっては、必要性を吟味し、そして、その前提として、今年度も事務事業評価等やっていますが、本当に必要な施策は何なのか、そういったものを吟味した上で予算編成をしています。","voiceIndex":92,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"やりくり、こつのところはまだよくわからないんですけれども、具体的に伺いたいと思うんですけれども、繰入金を見ますと、約７８億円取り崩す予定が約２４億円の取り崩しで済みました。予算に対してどういう要因で取り崩さずに済むことができたのか。不用額の合計が約７２億円ですが、これとの関係はどうあるのか、伺いたいと思います。","respondent":"本城企画財政課長","answer":"基金についてですが、今委員ご指摘がございましたように、当初取り崩す予定だったものをかなりの割合で取り崩さずに、結果として決算額にあるような数値になっております。","voiceIndex":94,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"初めに不用額のことについてなんですけれども、今回、不用額は７２億円余が生まれておりましたけれども、この不用額が生まれるというのはどういう要因なのか。それと東京都との、財調も含め、調整のことですけれども、需要額と収入額の差が普通交付金となるわけですが、この差をつくるために何か政策的な考えというか、区としての主体的な考えというものがあるのか、伺いたいと思います。","respondent":"本城企画財政課長","answer":"ちなみに、人件費という観点からのご質問もございましたが、人件費について限って言えば、職員給与費に関しては執行残として残っているものが３億円ほど、退職手当は約１億円ほどということで、先ほどご指摘がありました。","voiceIndex":96,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"こういう行財政改革が品川区の考えなのか、そこを改めて伺いたいと思います。いるとよく伺うんですけれども、そこを伺いたいと思うんですね。つまり、再開発に熱心な区とそうではない区で当然配分バランスが異なってしまうと思うんですけれども、再開発を進めると基準財政需要額も増えていくと、そういう関係にあるのか、どういう関係なのか伺いたいと思います。","respondent":"本城企画財政課長","answer":"平均的な算定、標準算定と言いますが、それと１件ごとの実績に基づく算定を合わせた需要が全体としての基準財政需要額という意味です。そういう意味では、再開発部分は基準財政需要額に入っているという、そういう考え方ということでご理解いただければと思います。","voiceIndex":98,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問","question":"不用額の中には人件費部分はちょっと違うんだというお話だったと思いますけれども、要するに伺いたいのは、区民の暮らしが苦しくなり、財調も少なくなり、経済がしぼんでいく中、どうして６９４億円もの基金を維持、また増やしていくことができるのか、その仕組みを改めて伺いたいと思います。","respondent":"本城企画財政課長","answer":"都市開発に関してですが、一件算定と先ほどお話ししましたが、財調の算定の中で対応補正と言われておりまして、実際どれだけ実績があったか、個別的に判断して、それを基準財政需要額に組み込むです。","voiceIndex":100,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"品川区が考える行革や健全財政をつくる考え方がいまいちご説明の中にないので、よくわからないので、改めて伺いたいと思います。ここを区はどう政策的に誘導していきたいとの考えがあるのか、改めて伺います。","respondent":"本城企画財政課長","answer":"先の見えない将来に備えるという意味でも、将来も含めたサービス水準を維持するために基金を確保しているということでご理解いただければと思います。再開発につきましては、必要な再開発について財源を財調も含めて確保しています。","voiceIndex":102,"id":"exchange-040"},{"speaker":"沢田委員","kind":"質問","question":"７９ページの使用料、区民保養所使用料と、それから８１ページの歴史館使用料についてお伺いします。予算書、決算書にこういった形で区民保養所載るのはこれが最後かと思いますけれども、改めてこの区民保養所というものが品川区において果たしてきた役割、そしてこのたびこういった形で廃止になったということについて、時代の要請ということもあったかと思いますけれども、簡単にお聞かせください。","respondent":"久保田地域活動課長","answer":"このたび廃止になりましたけれども、私ども、昨年度１年間検討をしてまいりまして、時代の変化で誰もが手軽に安く旅行できるようになったということ。","voiceIndex":106,"id":"exchange-041"},{"speaker":"沢田委員","kind":"意見","question":"今、課長からお話ありましたけれども、今年度も大体半分過ぎましたけれども、この民間への貸し付けということで、今年度半分過ぎて、現状、予算でいうとどれだけコストが削減できたのかということと、また、利用されている方の人数の増減というのはあるかと思うんですけれども、平成２３年度と比べると、平成２３年度は震災もあったり、そういったこともあったので。","respondent":"久保田地域活動課長","answer":"コストの関係ですけれども、私ども、平成２３年度やっていたものと平成２４年度全体で比較をいたしますと、率でいいますと大体６割程度のコストの削減が図れたと考えています。人数の増減ですけれども、こちらのほうは平成２３年度の比較でまいります。","voiceIndex":108,"id":"exchange-042"},{"speaker":"沢田委員","kind":"質問・要望","question":"今ちょっと話出ましたけれども、箱根荘の売却のほう、売却ということでしたけれども、現状はどういったことになったのかということだけお聞かせください。","respondent":"久保田地域活動課長","answer":"箱根荘ですけれども、平成２４年３月３１日末をもちまして保養所としての機能を廃止いたしまして、現在は解体工事に着手しています。予定としましては、平成２４年１２月、ことしの末までには施設等の解体をしていく予定で今工事を進めております。","voiceIndex":110,"id":"exchange-043"},{"speaker":"沢田委員","kind":"質問・要望","question":"８１ページの歴史館使用料のことでお伺いしますけれども、ちょうど昭和６０年に歴史館自体の建物が完成して２７年ということですけれども、今の歴史館の現状というか、いろんな課題等が出てきているかと思うんですけれども、そういった、ちょっと大ざっぱですけれども、認識と今後についてどういったお考えをお持ちなのかお聞かせください。","respondent":"安藤文化スポーツ振興課長","answer":"委員ご指摘のように、昭和６０年に建築されました。そんな中でも、庭にあります松滴庵、お茶室ですが、ご案内のとおり、松滴庵は昭和初期につくられた非常に価値のある伝統文化財です。","voiceIndex":114,"id":"exchange-044"},{"speaker":"沢田委員","kind":"質問","question":"茶室のほうは３５回で、１８回の利用ということですけれども、安田財閥以来の趣のある茶室や書院だということで文化的価値がすごく高いというお話が以前から出ていますけれども、その文化的価値という部分で高い、高いとおっしゃっておられるんですけれども、どういったところが高いのかということと、また。","respondent":"安藤文化スポーツ振興課長","answer":"それで、先ほど傷めないように使っていただくということを申しましたけれども、今後それをいかに保存をしていって、皆さんに使っていただくかということを、歴史館館長をはじめ、関係者の皆さんにお聞きしまして。","voiceIndex":116,"id":"exchange-045"},{"speaker":"阿久津委員","kind":"質問","question":"１点目ですけれども、先ほど鶴委員からも質問ありましたが、ロケーション・写真撮影等ということで、平成２２年度と比べると２８９件から２１９件に減少しているということで、鶴委員からも質問あったんですが、ご回答がなかったんですけれども、その理由について何か、鶴委員のほうから震災の影響等でしょうかという問いかけはあったんですが、その点についてのご見解を伺わせてください。","respondent":"小林土木管理課長","answer":"ロケーションの実績につきまして、平成２２年度決算では２８９件から平成２３年度２１９件に減少したその端的な理由というのははっきりいたしません。","voiceIndex":119,"id":"exchange-046"},{"speaker":"阿久津委員","kind":"提案","question":"以前私が第１回定例会のときにフィルム・コミッションの創設についてご提案をさせていただいたときに、区長のほうからのご答弁で東京ロケーションボックスとの連携をさらに進めていくということでご答弁をいただきました。この東京ロケーションボックスを通じてのロケーションハンティングとか、どういう場所がいいのかというお問い合わせ、これを受けるというのは品川区ではどちらが所管になるんでしょうか。","respondent":"米田商業・観光課長","answer":"こちらのロケーションに関しては、これまで広報広聴課のほうが窓口となっておりましたが、観光誘致の側面も強いということで、商業・観光課のほうでこちらのほうのお問い合わせを受けるということにしています。","voiceIndex":121,"id":"exchange-047"},{"speaker":"阿久津委員","kind":"質問","question":"今まで広報広聴課で、最近変わられたんでしょうか。商業・観光課のほうに変わられたということで、正確に変わったのがいつなのか、もし教えていただければと思います。","respondent":"米田商業・観光課長","answer":"今年度に入りまして、窓口のほうの確認を求められた際に、商業・観光課のほうで第一義的に受けするということを申し上げましたが、もちろん広報広聴課のほうでも問い合わせ等は従前と変わりなく続いて来ていますので、その辺は庁内連携を持ちながらという意味合いを込めまして。","voiceIndex":123,"id":"exchange-048"},{"speaker":"阿久津委員","kind":"確認","question":"今年度からということで、観光のほうの側面を非常に重視してということで、それは本当に歓迎をしたいと思うんです。荒川区も今検討していると聞いているんですが、品川区の窓口はいまだに広報広聴課になっているんですね。これについては一義的には東京都のほうなんですけれども、これは東京都のほうのロケーションボックスのほうとよく連携をされているのかどうか、そこの確認をしたいと思います。","respondent":"米田商業・観光課長","answer":"この辺につきましては、変更について、私どものほう、東京都のほうに申し上げたというようなことではありますが、ちょっと事務処理上の手違いがあったんだろうと思われます。改めて商業・観光課が窓口ということで訂正のほうお願いしたいと思います。","voiceIndex":125,"id":"exchange-049"},{"speaker":"阿久津委員","kind":"質問・要望","question":"実際、品川区とどういう連携をとられているんですかということで、来た話を通すということですから、なかなか連携と言われてもということでした。２点目に移らします。今年度から補助金がありまして、今年度から始まった事業かと思うんですけれども、簡単で結構ですので、現状、始まって半年ですか、この現状について、どういう事業なのか、簡単にご説明いただければと思います。","respondent":"永尾障害者福祉課長","answer":"それで今年度につきましては、医療デイケアを今年の９月から開始しております。精神科の専門医の方がデイケアをしていただいているというところですけれども、その医療デイケアと病院また地域をつなぐ役割として、地域医療コーディネーターというのを区のほうで派遣をしています。","voiceIndex":127,"id":"exchange-050"},{"speaker":"阿久津委員","kind":"提案","question":"現在稼働中というところで、どこまでの分析がされているのか、うまく回っているのかどうかというところもちょっとまた後で教えていただきたいんですけれども、これも申しわけないんですが、第１回定例会の中で、この事業に関して、ＭＴＢＩ、軽度外傷性脳損傷というものについて、病気についてご提案をさせていただいて、例えば港区なんかはこの事業に絡めて。","respondent":"福島荏原保健センター所長","answer":"今後も要望に応じて学習会を開き、その中で軽度外傷性脳損傷についても勉強して学んでいきたいと考えております。","voiceIndex":129,"id":"exchange-051"},{"speaker":"阿久津委員","kind":"質問","question":"その件について、今はまだやられていないということでよろしかったでしょうか。ＭＴＢＩに関してですけれども。","respondent":"福島荏原保健センター所長","answer":"委員のご質問を受けて以後の勉強会というのは、今のところはちょっとまだ開いていないという状況です。","voiceIndex":131,"id":"exchange-052"},{"speaker":"阿久津委員","kind":"質問・要望","question":"確かに厚生労働省、先ほどご答弁の中でもあったとおり、いわゆる画像に出ないということで、これに関しては専門家の中でも非常に見解が分かれております。どうか、そこら辺の難病ですとか、こうした難しい疾病に対する区の姿勢を最後にお伺いをさせていただきたいと思います。","respondent":"福島荏原保健センター所長","answer":"難病とか難しい病気についての支援等については、我々は区としても協力をしていきたいと考えております。","voiceIndex":133,"id":"exchange-053"},{"speaker":"阿久津委員","kind":"質問","question":"ぜひ期待をしていきたいと思います。土木使用料、区民住宅使用料についてなんですが、ちょっと時間がないようなので、また場を改めましてお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-054"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"私はまず８２ページの衛生使用料、それから９６ページの子宮頸がん等予防接種助成補助金、時間がありましたら、１０５ページの放置自転車等保管料に関して質問させていただきたいと思います。最初に、８２ページの衛生使用料の保健所使用料の試験検査という項目、１万１,９７９件というのがありますが、これは具体的にはどのような検査なんでしょうか。","respondent":"坂上品川保健センター所長","answer":"この試験検査というのは、受託健診、一般健康相談で行った検査で、糞便検査、これはすいません、普通に検便検査として行っているものですが、糞便検査、それと受託健診などで行っている尿の検査、それから、血液検査、心電図検査、聴力検査などです。","voiceIndex":137,"id":"exchange-055"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これはいわゆる一般健診の中で受託している項目をここにカウントされているということなんでしょうか。","respondent":"坂上品川保健センター所長","answer":"はい、ご指摘のとおりです。","voiceIndex":139,"id":"exchange-056"},{"speaker":"鈴木（博）委員","kind":"質問","question":"わかりました。それに対して今保健所のほうでは、遺伝子検査でＰＣＲをやって確定診断をしていると思うんですが、むしろはしかとか風疹なんかは、保健所ないし保健予防課のほうで積極的に遺伝子検査をやって確定診断をしたものに十分対策とったほうがよろしいのではないかと思うんですが、今現状はいかがでしょうか。","respondent":"伊津野保健予防課長","answer":"委員ご指摘のように、麻疹、風疹につきましては、臨床診断でなかなかつきがたく、遺伝子検査をしないと確定診断できない場合が多くあります。ですから、特に麻疹につきましては、全例、出た場合はＰＣＲ検査のほうに回して、確定診断をつけております。","voiceIndex":141,"id":"exchange-057"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次の質問にまいりたいと思います。次は９６ページの衛生費補助金、子宮頸がん等予防接種助成補助金、あと、款をまたぐんですが、１４６ページの予防費の任意予防接種のところに「Ｈｉｂワクチンほか」というような記載がありますが、これ、同じような任意接種で公的な助成が行われているものですが、子宮頸がん等と、それからＨｉｂワクチンほか、これは何か違いがあるんでしょうか。","respondent":"伊津野保健予防課長","answer":"９６ページの子宮頸がん等予防接種助成補助金と予防費の中の１４６ページ、同じであります。子宮頸がん、Ｈｉｂ、小児用肺炎球菌のワクチンであります。","voiceIndex":145,"id":"exchange-058"},{"speaker":"鈴木（博）委員","kind":"確認","question":"ことしの９月１日からイモバックスポリオという不活化ポリオのワクチンに変更になったんですが、それぞれの単価はどのぐらいなんでしょうか。このように、要するにワクチンそのものの原価だけではなくて、実際それが価格に関して非常に不合理というか、非常に高額で、要するに予算が膨らまされているという現状に関して、品川区のご見解をお伺いしたいと思います。","respondent":"伊津野保健予防課長","answer":"ポリオワクチンですが、従来の生ポリオワクチンの場合は、三者協で決めております接種委託費用としましては１,３７９円であります。それに対しまして、新しいイモバックスの接種費用につきましては、１万１,０４１円となっております。","voiceIndex":147,"id":"exchange-059"},{"speaker":"井上委員","kind":"質問・要望","question":"昨年の決算書には返金が求められる超過額という表記がされていないんですけれども、こういった不足額や超過額が成果報告書に表記されないというのはどういう理由によって、そういうことが発生するのか、教えてください。","respondent":"本城企画財政課長","answer":"今ご質問の超過額、あるいは不足額ですが、こちらについては、補助金等を受給した後に、その時点で返還しなければいけない超過額、あるいは不足額が確定しているものとそうでないものがあるということで、この調書をつくる時点で把握。","voiceIndex":150,"id":"exchange-060"},{"speaker":"井上委員","kind":"確認","question":"確定していない場合のことについてなんですけれども、私たちは予算書、決算書を見比べながら、その事業がどういう成果を得たのかということを確認するわけですので、そこに前年度の不足精算金や返還金が、運営費というか、決算のほうに含まれているということになると、その決算自体が事業の評価の前提が崩れてしまうと思うんですね。","respondent":"本城企画財政課長","answer":"翌年度の返還についてですが、それについては基本的な考え方といたしましては、返還額ということで独立して表記するのが基本です。原則はそのような形で対処しています。","voiceIndex":152,"id":"exchange-061"},{"speaker":"井上委員","kind":"提案","question":"原則そういうふうでも、そういうふうにされていないということになるので、やはりすごく少ないのかもしれませんけれども、この決算書でそういう内訳を各事業部に伺うと、返還金ということで、その事業部ではそのことがわかっているので、ぜひこれも、先ほどもわかりやすい決算書とか予算書というような表記の追加などの提案がありましたけれども、そこら辺は。","respondent":"坂上品川保健センター所長","answer":"今年度は９月末までで９回、対象５２０人の方に行っております。企画運営委員としても卒業生約１７名にご協力いただいておりまして、そういう意味で、受益者負担というふうには考えておりません。","voiceIndex":154,"id":"exchange-062"},{"speaker":"井上委員","kind":"質問","question":"私も以前に、随分前になりますが、中央公園で押し花教室に参加したときに、相当本格的な押し花キットが無料で配布をされて、「これはお返ししなくていいんですか」というふうにお尋ねしたことがあるんですけれども、これはどういう予算措置がされた事業として運営されているんでしょうか。","respondent":"多並公園課長","answer":"一つ一つの園芸等の講座のときの費用の負担の考え方ですけれども、実費負担が発生するものにつきましては、そこで実費をいただくとか、さまざまな講座の中の団体の考え方のところで、その中で行いながらやっているような仕組みとなっています。","voiceIndex":156,"id":"exchange-063"},{"speaker":"井上委員","kind":"質問・要望","question":"この事務事業評価、今回のものについては、費用負担についてのそういう表記がないので、それをどういうふうに庁内でこれから検討していくかということがわかりませんけれども、やはり私たちがこういう区民サービスを受けることについて、そのことによっての長期的な相乗効果も検討しなければいけないので、これがかかるからここで負担というわけにはいかないけれども。","respondent":"柏原行財政改革担当課長","answer":"ただ、委員おっしゃるように、今後それをいろんな面で多角的に検討して、どういった形でサービスを下げないで効果を上げていくかというところは大きな課題ですので、我々もその辺の視点を大きな課題というふうにとらえてございまして。","voiceIndex":158,"id":"exchange-064"},{"speaker":"井上委員","kind":"質問","question":"次に人権啓発活動費補助金なんですが、都の補助金が昨年より３００万円ほど増額になっていますので、この分がどんなふうな施策の充実につながったのかということと、あともう一つ、あわせてお伺いしてしまいますけれども、歳入歳出事項別明細書の財産に関する調書の中に、２３８ページの株式会社品川都市整備公社株券で、増で１９０万円と、ずっとここら辺はあまり変更がないんですが。","respondent":"中山人権啓発課長、柏原行財政改革担当課長","answer":"財源としましては、国のほうの財源になっております。今回かなりの増額ということだったんですが、実は平成２３年度の年度当初の補助金の交付予定額は２４０万円ほどでした。こういったところで、区としましても、ほかの株主との均衡を保つ観点からもしまして、区が引き受けるといいますか、買うというところで、年度途中での１９０万円購入ということで、株の購入の部分です。","voiceIndex":160,"id":"exchange-065"},{"speaker":"井上委員","kind":"質問・要望","question":"そのことについて見直しを求めますが、見解を伺いたい。株券のほうなんですが、この財源は予算書になくて、突然出ていたということで、流用だと聞きましたが、こういったものの報告は議会にはされなかったのは何か理由があるのでしょうか。","respondent":"中山人権啓発課長、柏原行財政改革担当課長","answer":"今現在、行動計画のほうが作業部隊ということで、まだ案がまとまっていないところですので、非公開としています。時期を見て公開のほうに変えていくようにしたいと考えています。こちらにつきましては、対応したのが年度途中というところがございましたので、決算書のほうに記載させていただいたというところでございまして、議会の報告というところにつきましては、そういった部分につきまして。","voiceIndex":163,"id":"exchange-066"},{"speaker":"渡辺委員","kind":"確認","question":"私は成果報告書１０５ページ、水族館運営費収入、８０ページの区民活動交流施設使用料で伺っていきたいと思います。そういう中で、費用のところ、約７,６００万円の決算額で、予算ベースですと約８,９００万円となっていました。当然来場者数のことが中心になるかと思いますが、確認で伺います。ちょうどこの年が２０周年の予算もついており、どう分析されているのか、教えてください。","respondent":"多並公園課長","answer":"予算立てのまず考え方でございましたが、平成２２年度の５１万人という実績者数を分析いたしまして、今後の増加を見込んで５２万７,０００人ということで見込んでおったところでしたけれども、今お話ししたような結果でございました。","voiceIndex":167,"id":"exchange-067"},{"speaker":"渡辺委員","kind":"質問・要望","question":"２０周年を迎えるに当たって、先輩方にも聞いていくと、当時のオープニングのときの地域の強い要望であったり、そして、ブームも一部あったかと思いますが、安定した高い人気を誇っているという性格の中で、まず５０万人というのを平成２３年度割ったにしても、４９万人、やはりわざわざお金を払って来ていただける来場者という点で、よく何万人というイベントの来場者等はありますが。","respondent":"多並公園課長","answer":"区民の利用者数に関してですけれども、区民割引というサービスを行っておりまして、その利用者の方は全体の５％というところで、そのような認識です。","voiceIndex":169,"id":"exchange-068"},{"speaker":"渡辺委員","kind":"確認","question":"５％といいながらも、総来場者が５０万人前後の中の５％ですから、本当に大きな数かと思います。あり方の検討が一つ、一定程度の方向性がどのように出されたのか、見解なり方向性なり結果、この辺を伺いたいのと、スケジュールは今後どのようになっていくのか、そしてまた、そのあり方の検討もどのような方がかかわっての意見集約だったのか、お知らせください。","respondent":"多並公園課長","answer":"あり方の検討委託の成果です。平成２３年度にしながわ水族館あり方検討業務支援委託ということで実施いたしました。","voiceIndex":171,"id":"exchange-069"},{"speaker":"渡辺委員","kind":"確認","question":"その点の確認をさせてください。ちょっと具体的な話として、年間パスポートを使った来場者の集客の取り組みだとか、ショー自体の演出も、イルカだとか、そういうことだけではない、もうちょっと人も使った演出だとか、ちょうどたまたまやっていたものですから、この辺なんかも柔軟に取り入れてもいいのかなという、利用者というか、見た方が言っていらしたので、これもちょっとあわせて伺いたいと思います。","respondent":"多並公園課長","answer":"今、やはり運営事業者とも話をしておりますが、その際、先ほど申しましたが、現在、４月から８月までですね、夏休みが終わったまでの期間の落ち込みが、同じ期間の前年より約１７％減という現在の状況を踏まえまして、今までの想定したものよりもかなり落ち込みがあるので。","voiceIndex":173,"id":"exchange-070"},{"speaker":"渡辺委員","kind":"質問・要望","question":"最後ですね、やはり水族館の存在はとても大きいと思います。そこには、ぜひとも経費的なものや、あるいはアイデア、人の投資というものがあってしかるべきだと思っていますので、そういう創出力のある品川区のまちづくりという点で、議会も含めて考えていければと思っています。要望も含めて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-071"},{"speaker":"塚本委員","kind":"質問","question":"私は１０４ページの広告料収入、それから、８５ページの総務手数料のところについてお伺いをしたいと思います。","respondent":"荒井広報広聴課長","answer":"今後は、こういったものを充実させるとともに、さらに、品川インフォビジョン、区政情報モニターの充実、あるいはバナー広告の充実等々、広告主に対してＰＲを努めていきたいと考えているところです。","voiceIndex":177,"id":"exchange-072"},{"speaker":"塚本委員","kind":"質問","question":"確かに広告料収入そのものをアップしていくことというのは歓迎していきたいと私も思いますけれども、あまり、何といいますかね、競争入札みたいな形で高い金額を出してくれた人を入札していくとかいうような、収入の金額面ばかりを拡充していくというような、そういう方向よりは、むしろ、今現在もそういう形ではあるかと思いますけれども。","respondent":"荒井広報広聴課長","answer":"広告主の要件につきましては、現在のところ、一般的に公共性およびその品位を損なうものではないことであるとか、政治活動、宗教活動、意見広告、個人的宣伝にかかわるものではないことなどの一般的な要件がありますが。","voiceIndex":179,"id":"exchange-073"},{"speaker":"塚本委員","kind":"質問","question":"了解いたしました。そういったことも含めて、今後の広告料の拡大というか、広告事業の拡張というか、そういったことについて最後お伺いしたいと思います。","respondent":"今井協働・国際担当課長","answer":"現在、区民情報サイト、しながわすまいるネットにおきまして、寄附金をいただいた企業、団体等の方から、一定金額以上の寄附金をいただいた場合には、一定期間の広告をすまいるネット上でバナー広告という形で載せしています。","voiceIndex":181,"id":"exchange-074"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。今の事業は事業として、また新たな展開というようなことでもご検討いただければと思います。この件につきまして、品川区としてそういった事実があったかどうか、ちょっと確認をさせていただきたいと思います。","respondent":"井浦戸籍住民課長","answer":"全国紙の新聞に昨年報道されましたように、１件、司法書士兼行政書士による不正請求というものが全国的にございまして、品川区もその不正に偽造された番号をもとに調べましたら、件数は事件として１件なんですが。","voiceIndex":183,"id":"exchange-075"},{"speaker":"塚本委員","kind":"質問","question":"この辺、例えば窓口のところで、水際で防ぐというか、何かそういうことというのは、現場を預かる課長として何かでき得ることなのかどうか、ちょっとお伺いしたいと思います。","respondent":"井浦戸籍住民課長","answer":"この水際という点の一番の大もとが、先ほど委員ご指摘のいわゆる八つの業士、弁護士、行政書士、司法書士、税理士等々、八つの資格のある業務の方は法律上、職務上請求できるとなっておりまして、それは所定の用紙。","voiceIndex":185,"id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問","question":"成果報告書のページ、７３ページ、特別区民税についてお伺いします。特別区民税なんですが、前年度比でマイナス０.２％となっています。数字をお伺いしますが、平成２２年度との比較で伺います。所得階層別の人数の増減もお伺いしますけれども、基本のところの２００万円以下、２００万円から７００万円、あと、７００万円以上で、どこでどのように増えたり減ったりしているのかを教えてください。","respondent":"高森税務課長","answer":"平成２３年度、納税義務者数につきましては、２０万６,０７７人です。ただ、今申し上げました、ここで言う２００万円という数字につきましては、課税標準額でございまして、給与収入の場合につきましては、単身者の方で、おおよそ３４０万円ぐらいの方が対象となるものです。","voiceIndex":188,"id":"exchange-077"},{"speaker":"飯沼委員","kind":"質問・要望","question":"貧困と格差のところが広がっていて、税の負担が低所得者のところに重くのしかかっているのではないかと思うんですが、その辺のちょっと評価を１点お聞かせいただきたいのと、あと、２００８年のリーマンショック以来、世界的な経済危機が長く続いていますが、とりわけ日本は成長がとまった国と言われ、原因は、国の富が大企業とか富裕層に偏って、サラリーマンの賃金が年々減っているということと、商店街。","respondent":"高森税務課長","answer":"ただ、この減免というのも、課税した後減免ということはありませんので、課税を６月、普通徴収であれば６月のこの間したわけですけれども、その後、申請に基づいて支払いができないということであれば、調査の上、執行停止という手続をとりまして、３年間。","voiceIndex":190,"id":"exchange-078"},{"speaker":"飯沼委員","kind":"質問","question":"一つは、最初のところの税から見える区民のところの、どういうふうに見ていらっしゃるのかという評価のところ、もう１回お伺いしたいのと、あと、相談件数５,１００件で、あとプラスアルファというか、はっきりしてない部分があるというふうに受けとめればいいんでしょうか。","respondent":"高森税務課長","answer":"この数値は２３区の中でも大変高い状況でございまして、生活が苦しい区民の方もいらっしゃるかとは思いますが、地域の会費としての区民の納税意識が高いという形で認識をしています。","voiceIndex":192,"id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どう評価しているのかというところにおいては、税金を納める、なるべくたくさん徴収するのは大事なんですけれども、そういったところから区民の生活の困難さをしっかり見てほしいなという意味で伺ったんですが、執行停止のところも、一昨年６,１４２件が１万件を超えているということでは、払いたくても払えないという区民の実態があるということをしっかりとらえていただきたいと思います。","respondent":"高森税務課長","answer":"先ほど申し上げましたように、ご相談いただいた方につきましては、生活事情を勘案しまして、執行停止などの手続を的確に個々の状況に応じてとらせていただいているというのが現状です。","voiceIndex":194,"id":"exchange-080"},{"speaker":"高橋委員","kind":"質問・要望","question":"土木費補助金をちょっと見ていて、ある事業から財源というんでしょうか、それを調べていこうと思って、それで土木費補助金の性質や土木費補助金全体のことを伺おうと思ったんですけれども、平成２３年度に行われた土木のほうの事業の財源が補助金の中にどうも見当たらないんですけれども、五反田ふれあい水辺広場のクレーンの検討経費でしょうか、それが補助金のどれに当たって。","respondent":"武藤河川下水道課長","answer":"五反田ふれあい水辺広場におけますクレーン等の検討の財源に関するご質問です。本件につきましては、水辺の利活用を推進するという観点から、区の単独事業費として予算を計上させていただいているものです。","voiceIndex":198,"id":"exchange-081"},{"speaker":"高橋委員","kind":"確認","question":"ということは、ここの補助金ではないということで、一般財源からこちらが出ている。ということは、予算書に出ていないということですと、こちらには出ていなかったんですね。そうすると、これはどこから、一般財源の本来別のところからの流用という表現になるんでしょうか。それとも、確認なんですが、平成２３年度補正予算の中で組んできたものなんでしょうか。","respondent":"武藤河川下水道課長","answer":"繰り返しになりますけれども、本事業は一般財源という形で計上させていただいているから、本項目に記載されていないものです。","voiceIndex":200,"id":"exchange-082"},{"speaker":"高橋委員","kind":"質問","question":"すいません。ちょっと別なところに話が飛んで申しわけございません。そうすると、流用した場合に、補正予算のほうに組むことがあるんですが、そちらに出てこなかった理由は、補正予算と流用との関係でどういった形になるんでしょうか。私は、補正予算に出ていなかったからいけないとか、そういうのではなくて、流用と補正予算との関係をご説明いただけると。","respondent":"武藤河川下水道課長","answer":"申しわけございません。本事業の五反田ふれあい水辺広場のクレーンの設置検討費の予算ですけれども、本事業は予算を流用させていただいて検討させていただいたものです。","voiceIndex":202,"id":"exchange-083"},{"speaker":"高橋委員","kind":"確認","question":"補正予算について、話がまたいってしまって申しわけないんですけれども、流用というのは、事業を円滑に進めていくために年度の途中で事態が起きたときには柔軟に行っていくべきだと思っているんです。ですから、きちんと報告していただく形で事業の迅速化というのを進めていただけると、やっていただいているわけですので、そこの確認をちょっとしたかったんです。","respondent":"本城企画財政課長","answer":"ただ、時期的に間に合わなかった場合等については流用で対応して、ただ、その場合については、適宜、議会等に報告だとかはするというのが基本的な流れです。","voiceIndex":204,"id":"exchange-084"},{"speaker":"高橋委員","kind":"質問・要望","question":"議決機関である議会と執行機関である区長をはじめとするそちらのほうが、もちろんきちっと信頼をしているという前提で、そういう流用をすることで迅速に進めていっていただきたい。流用で対応した場合も、補助金等は、後に精算ですか、そういう形になるのでしょうか。","respondent":"本城企画財政課長","answer":"補助金がもらえるかどうかにつきましては、区の内部で補正対応したかどうかということについて必ずしも連動しているわけではございませんので、補正しなければいけないとか、そういうことが補助金の関係であるわけでは必ずしもないということでご理解いただければと思います。","voiceIndex":206,"id":"exchange-085"},{"speaker":"高橋委員","kind":"質問","question":"逆に言うと、流用した場合でも補助金は交付される。もしそれがきちっといろんな国や都のルールにのっとっていれば適用されるということでしょうか。","respondent":"本城企画財政課長","answer":"そういうことです。繰り返しになりますが、事業執行上、補正するのが原則ということが基本ですが、迅速性だとか、そういう場合について、流用で対応した場合であっても、補助金がもらえないとか、そういうことになるわけではないです。","voiceIndex":208,"id":"exchange-086"},{"speaker":"高橋委員","kind":"質問・要望","question":"ですから、補正が前提だということですが、迅速性を持って流用でするときにはきちっと流用していただくのは構わないんですが、議会のほうに報告していただいて、トータルとして区の執行機関として円滑に行っていっていただければいいということで、議会として執行機関のほうを全面的に信頼しているわけですから、その辺は確認です。これは質問ではなくて、そういう要望です。すみません。","respondent":"溝口都市開発課長","answer":"都市基盤整備費収入について、どういう収入かということについてご説明します。","voiceIndex":210,"id":"exchange-087"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、７７ページに分担金及び負担金というのもあると思うんですが、そちらではなくて、この諸収入のところに入っているというのは、この辺の事情は何か理由があるのでしょうか。雑入ということで、いろんなものが雑入に入っているので、分類することがなかなか難しいので、こちらということなんでしょうか。","respondent":"溝口都市開発課長","answer":"本収入につきましては、地方財政法で禁じられています割当的寄附金等との混同を避けるために雑入という形で当該科目を設けているというのが本来の性質です。そうしたところで設けているものです。","voiceIndex":214,"id":"exchange-088"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、今お話あったように、再開発関係の形で負担していただいて、そちらがこのような形で、年度で多いときでは十数億円、少ないときは数千万円という形で、そういった再開発との関係で波が出てきているというのはわかりました。それで、いろんな補助金が再開発に入ってきています。区も一般財源でかなり補助をしていると思います。その点についてはどうでしょうか。","respondent":"溝口都市開発課長","answer":"基本的には区はそういったものに対しての補助金を出すという形になっておりますので、区民の方たちが利用しやすい、また、安全な市街地の形成ができるというふうに判断しております。","voiceIndex":216,"id":"exchange-089"},{"speaker":"高橋委員","kind":"意見","question":"今いろいろなものに還元という形で使われているというお話でしたが、そうすると、どのような事業に使われているのかということ、そのために一度、基金などで積み立てたりして、そういった原資になっているのか。なっているとすると、どういった積立金のほうにそちらが一度入って、そして地元の方々に還元されるような事業に使われていっているのか、その辺、お願いします。","respondent":"本城企画財政課長","answer":"基金との関係のご質問ですが、今の都市基盤整備費収入につきましては、一定額について公共施設の整備基金のほうに入れまして、そこで長期的に活用するという形で対応しているものです。","voiceIndex":218,"id":"exchange-090"},{"speaker":"高橋委員","kind":"質問・要望","question":"もう１点として、今お話あったように、補助金を補助している、それが区民の方々への還元になると、有効に活用されているということの確認でありますけれども、そういった形で、年度でちょっと波があるんですけれども、再開発と、この都市基盤整備費収入、区民の方々への還元という観点からも有効に活用していっていただきたいと思います。そこで終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":222,"id":"exchange-091"},{"speaker":"金野委員","kind":"質問・要望","question":"ですけれども、私個人の意見としては、今後の日本の医療というのは、医療費の財政負担ということも考えると、予防学というのが大変に遅れている国でもありますので、そこら辺が非常に早く予防医学というところに転換をしていっていただきたいという要望も含めて、今後こうしたことから、私のほうからも、このポリオワクチン含めた財政負担というところも、ぜひ国のほうへも要望し続けていただきたいですし。","respondent":"本城企画財政課長","answer":"今のポリオワクチンの関係ですが、財源としては、一般財源で対応するということで、財調の関係では財調に、現在のワクチンは参入されておりまして、今回新しくできたものについても、これから東京都の間で財調の需要額に含める協議をするところですが、今の見通しとしては。","voiceIndex":224,"id":"exchange-092"},{"speaker":"金野委員","kind":"確認","question":"都の財政調整というところで盛り込まれてくるということで、そういったところもぜひ活用してというところですが、その中で、今後の動きとしては、定期接種化される予防接種もあるという、こうした動きの中で、ことしの１１月ですか、報道で見たので、ちょっと確認をしたいんですけれども、これまでの３種混合ワクチンに合わせて、この不活化ポリオ。","respondent":"伊津野保健予防課長","answer":"委員ご指摘の４種混合ワクチンにつきましては、９月２８日に通知が来まして、１１月１日から４種混合として開始することになっております。","voiceIndex":226,"id":"exchange-093"},{"speaker":"金野委員","kind":"質問","question":"スケジュール的にはほかのものもあるので、なかなかというところだというのはわかりました。イメージ的に４種混合というと、いわゆる今までの３種混合と一緒に合わせる、その新しい薬が開発をされるというイメージをしているのですが、そこら辺のところで、財政的にはどうなるんでしょうか。","respondent":"伊津野保健予防課長","answer":"今回、不活化ポリオワクチン、先ほどお答えしましたように、かなり高価なワクチンだったんですが、４種混合になった場合は、今までのＤＰＴプラス生ポリオワクチンに少し高くなる程度になりますので、今回の不活化ワクチン単体の高額に比べれば。","voiceIndex":228,"id":"exchange-094"},{"speaker":"金野委員","kind":"質問","question":"単体で打つよりも４種混合にしたほうが財政的にはというお話をいただきました。やるならば４種混合ワクチン、１１月１日から行われるということで、ぜひ、これの周知などは考えていらっしゃるかと思いますけれども、お子さん方、お子さんを持っていらっしゃる接種対象の方への周知はどのようにされますでしょうか。","respondent":"伊津野保健予防課長","answer":"４種混合ワクチンは１１月１日からスタートですので、８月以降お生まれになったお子さんについて接種券を発送するという形で通知していきたいと思います。あわせまして、区のホームページ等で周知していきたいと考えています。","voiceIndex":230,"id":"exchange-095"},{"speaker":"金野委員","kind":"質問","question":"この点は以上で終わります。次に、障害児（者）基礎調査費、この件についてお伺いいたします。そこで、平成２３年度は、これまでの調査と同時に生活のしづらさなどに関する調査も実施をされていると認識しておりますけれども、昨年実施されたその調査はどのような目的で実施をされて、その調査の結果、いつごろ、どのように公表されていくのか、調査の概要、それから実施方法などもお知らせください。","respondent":"永尾障害者福祉課長","answer":"委員ご指摘のとおり、５年に１回の実施となっておりますけれども、今回の障害児（者）基礎調査というのは、内閣府のほうで設置している障がい者制度改革推進本部のほうで、新しい障害者総合支援法の整備に伴い実施をしたものです。","voiceIndex":232,"id":"exchange-096"},{"speaker":"金野委員","kind":"質問","question":"わかりました。予算書から見て、委託を受けてしていますので、１５０万円という予算額でした。それに対して決算額は７４万円余という、半分しか使っていないという、これはどういうことなのか、状況を教えてください。","respondent":"永尾障害者福祉課長","answer":"最初の予算を算定したときには、外部の調査員を使って委託をして行うというような予定でおりましたけれども、実際の調査は職員が行っておりまして、勤務時間外に調査をして、それに対する方針を出すという形をとりましたので、結果的には経費が少なくて済むような形になりました。","voiceIndex":234,"id":"exchange-097"},{"speaker":"金野委員","kind":"質問","question":"職員の方だけでやってくださったということで、経費削減をしてということで、調査をしてくださった。わかりました。この結果は、先ほども個別ではないということで、法にのっとってやるということですけれども、品川区としての調査、これは活用を、このような調査をされているのであれば、今後の障害者施策として大変に有効なものだと思いますけれども、どのように活用されるんですか。","respondent":"永尾障害者福祉課長","answer":"この具体的な内容については手元にありますけれども、分析等はまだ不十分なところがあります。ただ、これは、世帯も限られておりまして、もっと大きい範囲でニーズを確認する必要があると思いますので、今後その方法については検討してまいります。","voiceIndex":236,"id":"exchange-098"},{"speaker":"山内委員","kind":"質問・要望","question":"私からまず財調に関することを伺いたいと思います。これを何としても、少しでも事務移管に伴って財調を増やしていきたいということで、この２２区の区長は何とか東京都に要望しておりますけれども、東京都の相変わらずの答えは、区域の編成ありきというような形で、なかなかこの数字といったものが特別区に優位な数字になってこない。","respondent":"濱野区長","answer":"財源がきちっと伴う形なのか、あるいは伴わないのか、あるいは財源としても、財調なのか、いわゆる事務処理特例なのかというような形で、いろいろ評価分かれると思いますが、私は、もちろん大きな財政負担を伴うようなものは。","voiceIndex":239,"id":"exchange-099"},{"speaker":"山内委員","kind":"質問","question":"仕事の大きさによって、そこはやはり臨機応変にその辺は考えていく。これは濱野区長の考えということなんですが、他区の区長との整合性をとって、それで一つの意見として集約をし、それを東京都にあてていくということになるかと思うんですけれども、その辺の調整はどのようにされるのでしょうか。","respondent":"濱野区長","answer":"ただ、一つのことについて言えば、やはり少しでも区民の利便性のためには仕事を獲得していくのも一つの方法だと考えています。","voiceIndex":241,"id":"exchange-100"},{"speaker":"山内委員","kind":"質問","question":"わかりました。そういう中で、５５の中のいわゆる水平調整といった部分が今度は新たな課題なのかなという思いがいたしております。もちろんこれは財調で行っている。そういう中で、品川区は２３区の中でいち早くこの各戸収集に取り組んでいるということ。このあたりの今後の品川区の考え、それから、そういった付加価値についての部分というものをどのように考えていくのかを伺います。","respondent":"本城企画財政課長","answer":"今の付加価値という関係のことでお答えしますが、基本的には財政調整制度で財政需要額として見込まれて、共同の財源で担保する事務としては、標準的なサービス水準ということになってきますので、今例えばごみの各戸収集ということで、それでプラスになっている部分については。","voiceIndex":243,"id":"exchange-101"},{"speaker":"山内委員","kind":"質問","question":"それはわかるんですよ。その部分の財調といったものを今後どうやって、今はわかりますよ、今現状わかるんですが、そういった部分を今後どのように水平調整の中でお金をとりに行くのかというような考えがあるのかどうかということを伺いたいです。","respondent":"本城企画財政課長","answer":"今の点のご質問に関してですが、基本的には標準水準となるということが基本ではありますが、ただ、この基準となる需要額というのが見込まれないものについても、対応補正というような中で、財調の範囲に含めるということで、ケースによっては可能であるということがありますが。","voiceIndex":245,"id":"exchange-102"},{"speaker":"山内委員","kind":"質問","question":"わかりました。次に、１０２ページの延滞金についてを伺います。しっかりと区の職員の方々のご努力といった、これは成果ではないかなと考えていますが、改めてこの増の要因を伺いますことと、それから、区民税、さっきほかの委員からも質問ありましたけれども、区民税、９８％の徴収率だということでありましたが、今、区民税は、これ、口座振替を行っておりますよね。","respondent":"高森税務課長","answer":"現在も、平成２１年度から納税通知書発送時に口座振替の申込書を同封するなり、または平成２２年度以降は、口座振替加入キャンペーンと題しまして、区内の共通商品券１,０００円分を１,０００名様にプレゼントという形で、平成２２年度。","voiceIndex":247,"id":"exchange-103"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"８７ページと９２ページの国民健康保険の国庫負担金と都負担金についてお伺いをしたいと思います。国庫負担の総医療費に占める割合がどうなっているのか、国庫負担と都負担の割合が、平成元年とこの決算であります平成２３年、それぞれどれぐらいの割合になっているかを教えていただきたいのが１点です。それともう一つは、加入世帯の平均所得も平成元年と平成２３年でどうなっているかをお聞かせください。","respondent":"間部国保医療年金課長","answer":"加入世帯の平均所得については、これ、新聞報道等でサラリーマンの平均給与の関係での報道がありますけれども、以前バブルのころにつきましては、サラリーマンの平均年収が大体４５０万円のところが、現在では４００万円程度に落ちているというのが現状だと認識しています。","voiceIndex":250,"id":"exchange-104"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つ、この国保の国庫負担の割合に対しては、全国市長会でもずっと要望し続けていると思うんですけど、どういう中身で国庫負担増を求めるような要望書を出し続けているのか。それともう一つは、前回も低所得者層に配慮した充実を求めているということなんですが、この中身が具体的にどうなのかということもお聞かせいただきたいと思います。","respondent":"間部国保医療年金課長","answer":"これを何とか強くしてもらえませんかという申し入れをしているところでございまして、この点については、今般、税と社会保障の一体改革の中でも取り入れられていまして、今後は消費税が上がったときには、新たに２,２００億円ほど、全国的にですけれども。","voiceIndex":252,"id":"exchange-105"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国のほうで２,２００億円ということと同時に、自治体が出している４,０００億円近くのその財源をなくしていくという方向も国のほうとしては示されているので、そうなると逆に国保料というのが上がってきてしまうということにもなりかねないので、ぜひそういうことにはならないように、低所得者の配慮も含めて、品川区の自治体の財源の確保という点についても、これからも引き続いて。","respondent":"間部国保医療年金課長","answer":"最初に、今後は値下げの検討をということのお話がございましたが、先ほども申し上げましたとおり、医療給付費の上昇に伴って保険料が上がっていくと。これにつきましては、社会保険制度としては当然の成り行きですので、値下げについては難しいのかなという考えを持ってあります。","voiceIndex":254,"id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"病気、負傷、借金過多、低所得、それから勤労所得減、失業、事業不振、倒産、破産、こういうところで、これだけでも２,５７６人いるんですね。私はこの一人一人の生活がどうなっているのかというところに本当に心を寄せていただきたいと思うんですけど、そういうところでぜひこの方たちが相談に来られる窓口を国保の中にも一つつくっていただきたいということで思うんですが、それが１点です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":256,"id":"exchange-107"},{"speaker":"浅野委員","kind":"質問","question":"７９ページの使用料及び手数料から、集会所使用料について、９０ページと９７ページ、それぞれ、国庫補助金、都補助金の中から、密集住宅市街地整備促進事業と都市防災不燃化促進事業についてお伺いします。集会所の利用ですけれども、利用回数とこの使用料について、特に利用率が低い集会所ですけれども、その現状とその理由についてお伺いします。","respondent":"久保田地域活動課長","answer":"なぜ利用率が低いのかですけれども、固定の利用者の方はいらっしゃるんですけれども、やはり立地の条件、また施設の古さ、また数の問題等もございまして、そういった利用率が低い施設があるというふうには私どもは考えているところです。","voiceIndex":259,"id":"exchange-108"},{"speaker":"浅野委員","kind":"質問・要望","question":"階段昇降機ですか、これも屋外だけど、つけられないかという質問もあったかと思いますけれども、その後どうなったかというのは、現在ついてないので、きっとだめだったんだろうなと思いつつも、この検討の結果について、なぜだめだったのか、教えていただければと思います。","respondent":"久保田地域活動課長","answer":"これはやはり施設の形状等から、なかなかあそこにエレベーターをつけたりするのは難しいというところで、現在でも今のまま下から階段で上っていくという形になってあります。","voiceIndex":261,"id":"exchange-109"},{"speaker":"浅野委員","kind":"質問","question":"そしてあと、追加で質問ですけれども、インターネット接続可能な集会所、たしか６カ所あって、今回、荏原第五地域センターが追加で７カ所目になったと考えていますけれども、無料で提供している無線ＬＡＮ、または有線ＬＡＮですけれども、それぞれの年間での利用回数、そしてまた利用率について教えてください。","respondent":"久保田地域活動課長","answer":"施設予約システムですけれども、現在施設予約システムに入ってない集会所については、今ご説明しました荏原西区民集会所とか平塚橋会館というものが施設予約システムに入ってございません。こうしたものは、地域の方にできるだけ優先的にご利用いただきたいということ。","voiceIndex":263,"id":"exchange-110"},{"speaker":"浅野委員","kind":"質問","question":"一遍にどんというのはなかなかいかない。そう考えますと、今、この９カ所ですか、こちら、９カ所一遍でもないんでしょうけれども、何カ所か選んで、今あまり使われていない、この集会所利用のためのＷｉ－Ｆｉとかを屋外、まあ、屋外が難しいのであれば、集会所、地域センターの中で使えるような、Ｗｉ－Ｆｉとして提供してみてはどうかなと、そういうふうに考えます。","respondent":"久保田地域活動課長","answer":"委員ご提案のフリースポット等の提供につきましても、コストの面、またセキュリティーの問題等もいろいろあるところではありますけれども、今後の研究課題であるかと認識しています。","voiceIndex":265,"id":"exchange-111"},{"speaker":"浅野委員","kind":"意見","question":"ぜひともこの点については研究をしていっていただければと思います。いろんな地域で行政主導で、フリースポットといいましょうか、Ｗｉ－Ｆｉを提供しているというところがあります。このＷｉ－Ｆｉにつきましては、今、区の、この有線のほうしかやってないと言いますけれども、無線の機器を１台追加すればできるわけですので、これはぜひとも行ってまいりたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":267,"id":"exchange-112"},{"speaker":"本多委員","kind":"質問・要望","question":"１０２ページの諸収入はじめ、歳入全般で入るべきものが入らなかったという債権放棄分について質問いたします。債権放棄分につきましては、平成２３年度の第３回定例会の議案とあわせていただいた資料で、債権放棄が３７件でした。","respondent":"福田会計管理者、武内総務課長","answer":"事業数で申しますと３件含まれておりまして、そういう意味で、トータルを申し上げますと、平成２３年度中に放棄をした債権は２,３９８万６,７９０円。これは５１件に相当するものです。分配金につきましては、平成２３年度は、そのときが黒字ということではなくて、余剰金の積立てがあるということと、委員言われましたとおり、東日本大震災があったということで、２,０００万円が配分金として配分されました。","voiceIndex":269,"id":"exchange-113"},{"speaker":"本多委員","kind":"質問","question":"競馬場のほうなんですけれども、平成２３年度は黒字で２,０００万円ということで、久しぶりの黒字だと思いますので、よかったなと思うんですけれども、以前、競馬場の芝とかダートとは違って、調教などで全天候型のニューポリトラックコースを大井競馬場でも研究するという話があったと思うんですけれども、その辺の研究というのが現在進んでいるのか、それとも頓挫してしまったのか。","respondent":"福田会計管理者、武内総務課長","answer":"保証人、連帯保証人も当然債務者ですので、この方たちに対する督促もこれまでやってまいりました。債権管理条例ができましてからはさらに一層力を入れていると、そういう状況です。平成２２年に、大井競馬場の中ではないんですけれども、その調教コースというのが千葉にあるんですけれども、そこは委員言われたとおり、ニューポリトラックというのが完成したという情報を得ているんですけれども。","voiceIndex":272,"id":"exchange-114"},{"speaker":"本多委員","kind":"意見","question":"自治体における債権管理の原則として、債権については必ず回収しなさいというのが自治体の大原則であり、自治体が持っているお金は原則税金であり、国からのお金でも都からのお金でも、原則税金ということで、１円の債権であっても、放棄については取り扱い上高額な契約を結ぶ場合と同じであるべきと考えるんですけれども、この辺の取り扱いについてご所見をお聞かせください。","respondent":"福田会計管理者","answer":"職員の手間を省かせて、ほかのところに余力を振り向けると。ほかのところというのは、債権の徴収もその一つであろうと考えていますので、結局は徴収力を強化させると、こういう目的を持つ制度です。","voiceIndex":275,"id":"exchange-115"},{"speaker":"本多委員","kind":"質問・要望","question":"徴収することにつきましては最善の努力をしていただきたいと思います。数字を見ると、やはり額が大きい額になっておりますので、その辺につきまして確認をさせていただきました。ぼんと放棄する額が大きくて、穴があくといいますか、その部分を補うということは、これで失ったからほかで補うよということが、これは全然分けて考えるべきものだと思いますが、その点だけ、もし何かあれば、お聞かせください。","respondent":"福田会計管理者","answer":"これは目に見えない、数字には見えないかもしれませんけれども、徐々にそういう効果が上がってくる、そういうことを期待しながら事務を進めているものです。","voiceIndex":277,"id":"exchange-116"},{"speaker":"稲川委員","kind":"質問","question":"私から７３ページ、特別区たばこ税、９０ページ、土木費補助金の社会資本整備総合交付金、時間があれば１０５ページの宝くじ等助成金収入についてお伺いいたします。今回、増えているので、増収なのでいいんですが、減る場合とかもあるので、実際これが誤差の範囲なのかどうなのか、教えてください。年度内であれば、別に繰り越しというわけではないから、いつの時点でこれが生じたのか。２点教えてください。","respondent":"高森税務課長","answer":"当時の積算の根拠といたしましては、平成２２年１０月のたばこ税の改定を迎える中、当時新聞紙上では２０％ほどの喫煙者が減るというふうな方向性が主流であったために、販売本数について前年度の２０％減と見込み、予算計上させていただきました。","voiceIndex":280,"id":"exchange-117"},{"speaker":"稲川委員","kind":"質問・要望","question":"先ほどお話に、２０％ほど減だろうということ、で、実際７％だと。たばこ税は以上で終わります。次に、社会資本整備総合交付金についてですが、この交付金、区が出した計画に基づいて交付が実行されるような形だと思います。この計画を策定する段階で、ある意味継続的にやられている事業もあるんですが、実際その優先順位とか、そういうのがあるのかどうなのかを教えてください。","respondent":"本城企画財政課長","answer":"社会資本整備総合交付金の関係ですが、平成２３年度決算で全体額で３７億円強ということで、土木費から各いろんな費目にわたって、かなり大きな総額、全体の交付金になっております。一応基本的には申請した分を受給するような方向で、その交付金を確保しています。","voiceIndex":282,"id":"exchange-118"},{"speaker":"稲川委員","kind":"質問","question":"要するに、優先順位というよりは、計画を策定して申請したものに関しては、同時進行で物事を行っていくという感覚でよろしいのでしょうか。やはり近年そういった木密地域の整備に対して、しっかりと予算というか、財源を確保していかなければならない中で、ある程度優先順位があるのかなと私は思ったもので、質問させていただきましたが、いかがでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"そういう中で、優先的に整備する路線というものを決めて、その中の決まったものを申請をする。その申請したものが国の要件、区の要件に合致して、それが採択されて、補助金として入ってくる。このような形になってあります。","voiceIndex":284,"id":"exchange-119"},{"speaker":"稲川委員","kind":"確認","question":"これは私もいろいろなところでいろいろ所管には確認をさせていただいているんですが、非常に財源の確保が必要であり、なおかつやる商店街の底力というか、そこの商店街の財源も必要になってくる、非常に長くかかる事業でありますが、しかしながら、戸越銀座、そして北品川地区においては、今着々と進め、北品川は終わっていますが。","respondent":"稲田道路課長","answer":"電線類地中化事業は、委員ご存じのように、莫大な費用と年月を要します。国や都の補助金、最大限どの程度有効活用できるか、そういうところを重ねて検討していく必要があります。","voiceIndex":286,"id":"exchange-120"},{"speaker":"西本委員","kind":"質問","question":"成果報告書の７３ページの特別区民税と、それから７７ページの保育園保育料、それから、８４ページの教育使用料の中で、伊藤学園の温水プールについて質問いたします。それにあわせて、不納欠損もありますし、それから、滞納繰越などもありますけれども、これらをどのように受けとめて見通しを立てているのか、お聞きします。","respondent":"高森税務課長","answer":"平成２４年度、今後の収入見込みというご質問でよろしいですか。今後の収入見込みにつきましては、平成２４年６月に当初賦課をしています。","voiceIndex":289,"id":"exchange-121"},{"speaker":"西本委員","kind":"質問","question":"今のお話ですと、平成２４年度の動向を見ていくと、特別区民税が上がっていくよというようなめどをつけていると。歳出を見ると、歳出も下がっています。この結果を見て、例えば、やはり一般財源が下がってくれば、当然ながら事業も縮小していかなければいけない、どういう考えのもとでこれから事業の中でのコストを見ていくのかということについての区の全体的な考え方をお聞きしたいと思います。","respondent":"本城企画財政課長、高森税務課長","answer":"そういう中で、必ず本当に必要なものを、事務事業評価含めて、きちんと精査するとともに、財源見合いでなかなか確保できない、当年度の財源では確保できないものについては。滞納繰越分につきましても、平成２３年度３６％という誇れる徴収率を確保した状態になっていますので、その分現年度の徴収、区民の方に地域の会費として納税いただく努力をさらに進めていきたいと考えているところです。","voiceIndex":291,"id":"exchange-122"},{"speaker":"西本委員","kind":"質問","question":"なので、今年もかなり基金を投入したということを考えていくと、やはり何かしらの、基金だけではなくて、税外収入という形もあるでしょうし、いろいろな方法で財源を確保していかなければならないだろうと思いますが、その点についてのお考えをお聞きします。","respondent":"本城企画財政課長","answer":"基盤となるのは税収等ということになると思いますので、それを着実に確保しながら、税外収入も可能なものについてはいろいろ工夫しつつ、あと、特定財源も、先ほど来ありましたが、確実に確保する等、総合的に財源を確保しながら、その中の一つの要素として、基金の積立て。","voiceIndex":294,"id":"exchange-123"},{"speaker":"西本委員","kind":"質問","question":"考え方を含めてです。この保育園保育料です。今回の条例案の中でも出ていましたけれども、保育料の値上げというところがありました。そもそも保育料という考え方についてお聞きしたいと思います。","respondent":"立川保育課長","answer":"保育料の徴収につきましては、児童福祉法第５６条の３項に直接規定されているものです。法の規定では、保育の実施主体として、国、区、それから保護者、この３者によって負担するということになっています。","voiceIndex":296,"id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"数年前でしょうか、保育料値上げになりました。そのときの理由としては、国の流れも含めると、受益者負担という形で、まあ、これは保育料だけではないとは思いますけれども、利益に対してそれだけの料金といいますか、それを払っていきましょうという形に大きく変わっていったと思います。それの考え方についてもお聞きします。","respondent":"立川保育課長","answer":"一部の高所得の方に対してだけ負担を強いるものではないかというご質問だと思うんですけれども、今回、全体で４％の改定をまず考えたところですけれども、今般の社会経済情勢にかんがみて、所得の低い方、中間層の方については今回は見送るということで、今回。","voiceIndex":298,"id":"exchange-125"},{"speaker":"西本委員","kind":"質問","question":"保育料の仕組み、全体の仕組みはやはり応能という形になっている、階層的になっているというのは、それは十分にわかっております。なので、先ほど見直しを図るというようなところもありますけれども、今の国の流れも含めて考えると、今後どういう形で、時期的なところも含めて、保育料の改定等々考えられているのか、お聞きします。","respondent":"立川保育課長","answer":"今回、全体で４％と考えましたけれども、今般の経済情勢ということで、低所得、中間所得の方については見送りましたけれども、今後の改定につきまして、やはり今回見送ったところの部分につきましても。","voiceIndex":300,"id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり平等性というところ、それから子育て支援と考えたときに、保育料の値上げというのはやはり全体、品川区でいろんな施策をやっている中で、それを含めた形で今後検討する、見直しを図るということをぜひしていただきたいと考えています。で、今回このお約束を破ってまで、光熱費がかかるからということで、見直しを図るというのはいかがなものかと思うんですが、その理由についてお聞きしたいと思います。","respondent":"和氣学務課長","answer":"確かにご不便はおかけいたしますが、本当に快適な、しかも地域開放を前提にして設計をしました豊葉の杜学園のプールをぜひお使いいただきたいと考えているところです。","voiceIndex":302,"id":"exchange-127"},{"speaker":"西本委員","kind":"質問","question":"使っている方々への意見交換であるとか、あとは、移行期間を設けるとか、来年の５月までという形になっていますけれども、その移行期間を少し長くするとか、いろいろと使用していただくための手立てをするとかという努力が必要だと思うんですが、今回出されてきたというのは、今までなかったことが急に委員会に出された、報告事項で出されたということについては、やはりこれは納得いかないし。","respondent":"和氣学務課長","answer":"移行期間ですが、そういうこともございまして、半年前という、団体利用の方についても十分計画を変更していただける半年前ということを考えさせていただいたということと、単に経費というよりは。","voiceIndex":304,"id":"exchange-128"},{"speaker":"西本委員","kind":"質問・要望","question":"節電はもちろんわかります。なので、そこはしっかりと説明をする必要があると思いますし、そもそもこの伊藤学園ができたときの経緯というものも、もう一度見直していただいて、多分そのときにかかわった理事者の方が少なくなっているかもしれませんけれども、やはりそういう歴然とした歴史がありますので、きっちりと区民の方に説明をしていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":306,"id":"exchange-129"},{"speaker":"山元委員","kind":"質問・要望","question":"私は、第１２款使用料及び手数料の中の８０ページの区民活動交流施設使用料についてお伺いしたいと思います。この誤差というか、計算違いというんでしょうか、これはどのようになってこうなったのか。それから、今、実際このこみゅにてぃぷらざに登録団体というんでしょうか、その登録団体は幾つなされているのか、また、どのような団体が登録されているのかも教えていただきたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"物理的な、位置的な問題だとか、それからまた、先ほどご質問がありました美術工芸室につきましても、陶芸の利用者等がいますものですから、かま等もつくってまいりました。しかし、実際にあけてみると、やはり南大井文化センターにも陶芸室のかまがあります。","voiceIndex":308,"id":"exchange-130"},{"speaker":"山元委員","kind":"意見","question":"すいません、最後にロッカーのことなんですけれども、予算書には使用料が載っていたんですが、この決算には載っていないのはどういうことなのかなということなんですけど。","respondent":"安藤文化スポーツ振興課長","answer":"予算には載って、決算には載っていないというお話ですけれども、決算の中の８１ページですが、ここの設備使用料です、ここの中に入ってあります。","voiceIndex":310,"id":"exchange-131"},{"speaker":"山元委員","kind":"質問・要望","question":"そういう意味で、お部屋の周りを見ると、棚があるんだけれども、その辺を使わせていただけないのかどうかということがありました。それに対してのちょっとご返事をいただきたいのと、それから、ロッカーの使い方なんですけれども、これは鍵がついているんでしょうか。それと同時に、１回１回使って、お金が戻ってくる、たしか無料ではなかったような、その辺もちょっと教えていただきたいんですけれども。","respondent":"安藤文化スポーツ振興課長","answer":"それからもう一つのロッカーの鍵ですが、これについては、リターンではございませんで、１００円で購入をしていただくです。","voiceIndex":312,"id":"exchange-132"},{"speaker":"山元委員","kind":"質問","question":"そうしますと、ごめんなさい、このロッカーは、ずっと使うことが可能なんでしょうか。それとも１回限りで返さなければいけないんですか。","respondent":"安藤文化スポーツ振興課長","answer":"今現在、こみゅにてぃぷらざ八潮につきましては、個人団体の方々に対して、特別に１団体１団体に貸し出すようなロッカーにしてはございません。利用者の皆さんが共同で使えるような１００円のロッカーにしています。","voiceIndex":314,"id":"exchange-133"},{"speaker":"山元委員","kind":"質問・要望","question":"いずれにしましても、やはり皆さんに使い勝手のいいこみゅにてぃぷらざにしていただきたいので、その辺もぜひご検討していただきたいと同時に、やはりこの事務事業評価の中に、継続ということもありますが、周知の方法について云々と書いてありますが、今度やはり広げるためには周知の方法が大事かなと思いますが、どのような方法で広げていきたいと思っていらっしゃいますか。","respondent":"安藤文化スポーツ振興課長","answer":"とにかくまだ１年と８カ月なものですから、これからどんどんどんどん利用者を増やしていきたいと思っています。","voiceIndex":316,"id":"exchange-134"},{"speaker":"松澤委員","kind":"質問・要望","question":"２点お伺いしたいと思います。１点目は、成果報告書の１００ページ、第１５款財産収入、財産売払収入、不動産売払収入７,４３８万７,６０１円、これの内訳をお願いしたいと思います。２点目は、８２ページの民生使用料、高齢者等住宅使用料と、８４ページの土木使用料、区民住宅使用料に関連してお伺いをしたいと思います。１点目、お答えいただきたいと思います。","respondent":"平澤経理課長","answer":"１点だけ、旧総合体育館の損失補償金というのがございまして、こちらにつきましては、総合体育館、再開発区域に含まれているというところでございまして、工作物、樹木等の売払というんですか、損失補償で収入があったです。","voiceIndex":319,"id":"exchange-135"},{"speaker":"松澤委員","kind":"質問","question":"まあ、この不動産売払収入、この中には公共溝渠というものがあると思うんですけれども、この水路ですね、大きな水路、立会道路があのようにふたかけになって、道路として使用されていますけれども、ある程度の広さのものは、歩いてふたかけがあるからわかるんですけれども、本当に細い水路、Ｕ字溝が草ぼうぼうになっていたり、そこが駐車場として使用されていたり、あるいは玄関になっていたり。","respondent":"小林土木管理課長","answer":"ただいまお話にありました公共溝渠、今改め法定外公共物に分類していますけれども、ご指摘のとおり、歴史的な経過から、中にはもう実質的に公有財産、道路、通路、あるいは水路敷等の用途を失っているものも含めて、この間、国から一括譲与ということで、平成１３年、平成１４年。","voiceIndex":321,"id":"exchange-136"},{"speaker":"松澤委員","kind":"質問","question":"この払い下げの考え方というのは、東京都から区に移管されましたから、払い下げると、区の収入になるんですけれども、基本的には今お話聞いたように、不法状態をなくすというのが主だと私は思うんですよ。大きな測量費になりますから。それが少なくとも半額ぐらいは助成する方向、そういうような形にしてもらえれば早く進むと思うんですが、その辺の考え方、いかがでしょうか。","respondent":"小林土木管理課長","answer":"具体的に測量費の負担については、今後の課題と考えております。","voiceIndex":323,"id":"exchange-137"},{"speaker":"松澤委員","kind":"質問・要望","question":"実は、今度１６３号線が開通しまして、すごく広くなって、皆さん喜んでいます。その前は通行止めという立て看板があったんですが、ガードレールでふさがれて、今どうなっているかというと、コインパーキングになっているんですね。あの区道が占有されてしまったのか、囲い込まれたのか、まあ、常識的に考えれば、払い下げたんだと思いますが、その辺の経緯をお教えいただきたいと思います。","respondent":"小林土木管理課長","answer":"ご指摘の箇所は、この区役所前、もう少し大井町のほうへ行きまして、１６３号線と立会道路との十字路の角です。これは１６３号線の拡幅が済んだ状況の中で、この十字路、区としては将来バス通り等の可能性もあり、また、道路が広がったので、隅切りが欲しかった。","voiceIndex":325,"id":"exchange-138"},{"speaker":"松澤委員","kind":"質問","question":"これは議会にも報告がないんですが、これは報告義務がないんでしょうか。その辺をもうちょっとお伺いしたいと思います。","respondent":"小林土木管理課長","answer":"基本的に、まず廃路敷を含めた区道については、認定ないしは廃止の場合は、議会の議決をちょうだいしています。今回、この計画道路の整備に伴うこの部分については、広く道路の区域変更ですので、これは議会への付議案件、報告案件になっておりません。","voiceIndex":327,"id":"exchange-139"},{"speaker":"松澤委員","kind":"質問","question":"時間がなくなって、２点目はほかのところでやりますけれども、もう１点、区道がやはり何かの都合で行きどまりになってしまって、不法に占有されている、占拠されている、車庫になっているという話、私のところに２件来たんですね。その辺の区道に対する、占有に対する調査とか、そういうものはしているんでしょうか。その辺をお聞きしたいと思います。","respondent":"小林土木管理課長","answer":"必要に応じて常時、地元の声などをもとにして対応をしています。","voiceIndex":329,"id":"exchange-140"},{"speaker":"南委員","kind":"質問・要望","question":"９９ページの教育費委託金、人権尊重教育推進費について伺いたいと思います。したがって、先だって発生してしまった中学１年生の男子生徒の、自宅でみずから命を絶つという、この悲しい事件の問題について調査委員会を立ち上げたというご報告が先般ありましたので、そのことに関して幾つか質問させていただきたいと思います。どんな内容なのか、具体的に教えていただきたいと思います。","respondent":"太田指導課長","answer":"いじめ等調査対策委員会のメンバーですが、委員長を教育長とし、委員が１０名、委員は教育次長、指導課長、統括指導主事、学校参与、それに学校の校長、副校長です。それから２点目、いじめと判断することがあったという、その内容ですが、からかい、それから暴力的な行為等です。","voiceIndex":332,"id":"exchange-141"},{"speaker":"南委員","kind":"質問・要望","question":"アンケート調査を９月２７日に行ったようですけれども、その内容はどのようなものなのか。そして、調査対策特別委員会は、このアンケートのほかにどのようなものをどういうふうに調査するのか、そのあたりについても伺いたいと思います。","respondent":"太田指導課長","answer":"調査はどういうふうなことで進んでいるのかですが、翌日学年全員にアンケートを実施し、それをもとに、管理職を含めた、これは教育委員会の指導主事も交え、そして担任、３名で、そういう体制を５組、組みまして、学年の生徒全員のまず聞き取りを行いました。","voiceIndex":334,"id":"exchange-142"},{"speaker":"南委員","kind":"質問・要望","question":"調査で明らかになったものについては、かなりの体制をとって調査しているということが今のご報告でわかったわけですけれども、その調査で明らかになったものについては、ご遺族はもちろんのこと、当該校の保護者をはじめ、区民に報告する必要があると思うんですけれども、報告というのはどういうふうに考えているのか、また、いつごろの時期に報告するというふうに考えておられるのか。","respondent":"太田指導課長","answer":"期間といたしましては、いつまでというようなことで、今調査中でございまして、いろいろ調査の段階で再度面談をやったりということがありますが、なるべく急いでやりまして、遅くとも今月中にはそういったことを取りまとめたいと考えております。","voiceIndex":336,"id":"exchange-143"},{"speaker":"南委員","kind":"質問・要望","question":"で、新聞報道なんですけれども、９月２９日付の朝日新聞では、校長先生が出席停止措置にも言及して、指導を強めていく姿勢を示したと、そういうふうに報道でなっているんですけれども、加害生徒への対応は、教育委員会としては同じように考えているのか、この点について伺います。","respondent":"太田指導課長、田村教育次長","answer":"いじめ防止に関する手引書等で出席停止についても触れたということを受けまして、区の方針といいますか、そういったことで、校長のほうはマスコミの取材に対しまして、それも視野に入れるという形でお話をしたところ。冒頭、教育長からお話ししたように、これから個別に調査結果がまとまりつつあるということなので、個別に直接私たち理事者のほうに、アンケートの用紙という形よりも、議長と個別に相談して、今後も出てくる話なので。","voiceIndex":338,"id":"exchange-144"},{"speaker":"南委員","kind":"質問・要望","question":"この委員会で質疑している中身でありますので、そこで議長が出てくるというのはちょっと違うのではないかと思うんですね。したがって、委員長、この委員会の正副なり理事会なりできちんと議論していただいて、ぜひ出していただけるように、議員みんながわかるように出していただきたいと思います。その点はよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":341,"id":"exchange-145"},{"speaker":"南委員","kind":"質問・要望","question":"よろしくお願いします。したがって、早急に加害生徒に対しても教育的に指導をする、このことが欠かせないと思うんですね。そういうことはどんなことがあっても防がなければいけないわけですから、やはり加害生徒に対してのきちんとした教育的な指導、そういうものをぜひ求めたいと思っているんですけれども、そのあたりについてはどういうふうに考えているかを伺います。","respondent":"太田指導課長","answer":"もちろん学校で加害生徒への教育的指導も、また保護者との対応もしてまいりたいと考えています。いじめにかかわった子どもへの指導ということですけれども、そのかかわり方が、今調査をしている中で、どういうようなかかわり方かというのが、いろいろな段階、その程度があります。","voiceIndex":343,"id":"exchange-146"},{"speaker":"南委員","kind":"質問・要望","question":"私はもう絶対に再び再発させない、このことを強く求めたいと思います。そして、学校の中にいじめを許さない雰囲気をやはりしっかりつくっていただく。同時に温かい人間関係を築くことを大事にして実践していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":345,"id":"exchange-147"},{"speaker":"石田（慎）委員","kind":"質問","question":"よろしくお願いします。私のほうからは、成果報告書７７ページ、民生費負担金の保育園保育料について、それと７７ページ、負担金について、それと８７ページ、９２ページ、生活保護費について、そして、補助金全体についてお伺いをします。初めに、保育料についてですが、今定例会にて保育料の改定の議案が提出をされております。","respondent":"立川保育課長","answer":"文教委員会のほうでご審議いただいたんですけれども、そこでの資料については、委員ご指摘のとおり、ちょっと不十分なものであったというふうに認識しております。","voiceIndex":347,"id":"exchange-148"},{"speaker":"石田（慎）委員","kind":"提案","question":"保育料の改定においては、さまざまな地区で、例えば世田谷区では今定例会で議会に提案をし、そして第４回定例会で議案を提出する予定であったり、中野区では審議会を立ち上げて検討する、また、三多摩地区でもさまざまな、国立市では財政改革審議会を設置、また西東京市では子ども福祉審議会、武蔵野市でも保育料審議会、そういった審議会の中でさまざまな議論をし、そして、さまざまな専門家。","respondent":"金子子ども未来事業部長","answer":"今、委員ご指摘のありました他区での状況、他自治体での状況、そういった審議会、あるいはパブリックコメントを求めるというような区もあるという状況は私どもも承知しております。今後の保育料改定に際しましては、何らかの検討組織を設置することも必要だと考えています。","voiceIndex":351,"id":"exchange-149"},{"speaker":"石田（慎）委員","kind":"意見","question":"保育所の運営経費というのは今後も増えていくのではないかと思われている中で、今回の保険料の改定は、現行の枠組みの中で行った改定であり、この改定においては、保育料全体、仕組みの全体の見直しが必要だと考えますが、その点について区のお考えをお聞かせください。","respondent":"金子子ども未来事業部長","answer":"私ども、先ほど課長が答弁申し上げましたとおり、日々、保育料を含め、さまざまな見直しをしておりますけれども、この平成２７年度というのが大きな節目であって、制度変更に合わせてさまざまな検討も必要かと考えているところです。","voiceIndex":353,"id":"exchange-150"},{"speaker":"石田（慎）委員","kind":"質問","question":"今回の保育料改定は、前回の改定と比べてもはるかに大きい上げ幅ではないかと思います。その対象の中では、年間１０万円を超えてしまうような負担増となる家庭もあります。そこで、保育料の激変緩和策、例えば国保のときも、値上げをするときにはそういった激変緩和策がありますが、この保育料に関しても適用するべきだと思いますが、いかがでしょうか。","respondent":"金子子ども未来事業部長","answer":"今回の保育料改定は、るるご説明申し上げているとおり、低所得の、比較的所得の低い方、それから中間所得層の方々は見送ったわけでありますけれども、そういう意味で、今回激変緩和策をとる考えはありませんが、今回新たに設置をしましたＤ２４階層、２５階層の方々については。","voiceIndex":355,"id":"exchange-151"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"負担金について、７７ページになります。区の施設を貸しているのがこの負担金で計上されていると思うんですが、この算定基準、面積とかがあると思うんですが、その算定基準がどのようになっているのかお知らせいただきたいのと、行政財産使用料、８３ページですかね、行政財産使用料とこの負担金の違いというのはどのようなものなのか、お知らせをください。","respondent":"平澤経理課長","answer":"これに使用面積の案分をいたしまして、で、条例上の１０００分の２.５、これが土地の分、１０００分の６、これが建物の分ということで、掛け算をしまして、また、その貸出相手ごとに一定の減免率がございまして、そういったところも勘案した上で算定しています。","voiceIndex":357,"id":"exchange-152"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"補助金について、今回、東京都からオリンピックの招致の部分で急遽補助金が創設されたと思うんですが、こういった急な補助金、東京都だったり国が示してきたときに、期間が非常に短いときがあると思うんですが、そのとき、どのような対象者に周知をされるのか、その周知方法を教えていただきたいのと、区でもそういった例えば補助金を年度の途中で急遽つけるとかという。","respondent":"安藤文化スポーツ振興課長、本城企画財政課長","answer":"それで５０万円の補助金が新たについたというものです。そのついた経過につきましては、東京オリンピックのほうも、急な措置でございまして、我々、２３区をはじめ、担当の部課を呼びまして、そこで説明会がありました。今のこととほかに、区として補助金を交付するときにはどのような形でということでご質問があったかと思いますが、それにつきましては、区といたしましては、補助金を交付するに当たっては、基本的に予算計上いたしまして。","voiceIndex":359,"id":"exchange-153"},{"speaker":"須貝委員","kind":"質問","question":"私は７２ページ、歳入について企画財政課にお聞きします。そして、あと基金についてもお聞きしたいと思います。まあ、見込み違いがかなり大きいのではないかと思うんですが、先ほどこういう理由でとありましたが、この大きさというのは、それはさまざまあると思うんですが、この大きさについてどのようにご見解を持っているのか、お聞かせください。","respondent":"本城企画財政課長","answer":"もう１点の基金のほうですが、こちらにつきましては、基金を幾ら取り崩すかということは、年度末の決算の状況を見まして、必要な範囲で取り崩すということの考え方ですので、年度末の状況で、区の財政全般の運営の中で取り崩さずに。","voiceIndex":365,"id":"exchange-154"},{"speaker":"須貝委員","kind":"質問","question":"事情は今お聞きしましたが、品川区の決算調製は、本当にこれからも、こういうことがこれだけの額のものがやはり常々起こってしまうのか、起こってもいいのかということをちょっともう１回お聞かせください。当たり前のことなら当たり前のことで。","respondent":"本城企画財政課長","answer":"今、品川区のという形でご説明させていただきましたが、これは特に品川区特有の問題ということではございませんで、基金については特にですが、それはあくまでもある意味では直近的なものですので、必要がなければ取り崩さずに済むということで、今回最終的な年度末を迎えまして。","voiceIndex":367,"id":"exchange-155"},{"speaker":"須貝委員","kind":"質問","question":"で、こういうわけで急にこうなった。まあ、それぞれ大きな理由もあると思います。そして、基金についてお聞きしたいんですが、地球環境基金、３０億円はいまだに使われずにおりますが、要は固定化しているわけですよね。これについて理由を教えてください。そして、今後使い道があるのか、ないのか、その辺についてちょっとお聞かせください。","respondent":"本城企画財政課長","answer":"今のご質問のあった基金につきましては、先ほど来ご説明させていただいたのは、基金の性格として取崩型という基金でございまして、これに対して今の地球環境基金の関係は、果実運用型ということで、利子ですね、そういうものを活用しながらやっていくので。","voiceIndex":369,"id":"exchange-156"},{"speaker":"須貝委員","kind":"質問","question":"３０億円というお金が固定化して、今、利息って知れていますよね。確かに果実を運用しているというのはわかるんですが、区民の皆さんから預かっている税金をやはり有効に使う。利息をつけるために基金というのは設けるものなんですか、根本的に。私は事業をやるというためにつくるのが基金ではないか、とっておくのが基金ではないと思うんですが、その辺についてご見解をお聞かせください。","respondent":"本城企画財政課長","answer":"基金の性格によって異なるですが、今の地球環境基金につきましても、利子を活用して、実際に１,８００万円ほどの益がありますので、それを効果的に活用して、リサイクル関係の事業に使っているということでご理解いただければと思います。","voiceIndex":371,"id":"exchange-157"},{"speaker":"須貝委員","kind":"質問","question":"本当にね、果実というのもわかります。次にお聞きしたいのは、平成２２年度末から平成２３年度末にかけて、基金の増減について教えてください。","respondent":"本城企画財政課長","answer":"は基金の増減ですが、取り崩したものにつきましては、取り崩した結果、増減といたしましては、平成２２年度末が６８８億円余に対して、平成２３年度末が６９６億円余ということで、前年度に比べて８億６,４００万円ほど増えている形になっております。","voiceIndex":373,"id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"２０２０年問題がありました。でも、これを維持するためには、やはり建替え、全部つくりかえるわけですから、そうすると、新聞等によりますと３０億円から４０億円もかかると。ですが、やはりこういうお金があるならば、区民生活、社会福祉に対しても、社会保障費に対しても、やはり私はそういうお金をつぎ込んでいく、そういう姿勢が大事だと思うんですが、その辺についてご見解をお聞かせください。","respondent":"本城企画財政課長","answer":"施設もいろいろある中で、これから改築需要を迎えることがありましたり、これから将来的に仮に経済状況が厳しくなったときにも、きちんと財政的に力を確保する、そういう長期的な見通しの中で基金を活用するという意味で、計画的に基金を積み立て。","voiceIndex":375,"id":"exchange-159"},{"speaker":"須貝委員","kind":"意見","question":"ですが、やはり考えていかなければいけないことは、他の自治体、東京２３区は比較的まだ税収、歳入が見込まれております。で、今は確かに基金がある。ですが、やはり国民、区民に直結しない事業というものは、やはり私は少しずつやめていくなり、新しい方法で品川区を財政的にも引っ張っていってほしいし、区民にとって安心な品川区であってほしいと思うんですが、最後に、もし一言あればお願いいたします。","respondent":"本城企画財政課長","answer":"繰り返しになってしまうかもしれませんが、そのような状況だからこそ、本当に真に必要なものを見きわめつつ、なかなか見通し切れない将来に対して健全な財政を維持するために計画的に基金もきちんと活用していかなければいけない、そのように考えているところです。","voiceIndex":377,"id":"exchange-160"},{"speaker":"若林委員","kind":"質問・要望","question":"私は２点、ページ数ありませんが、いわゆる不納欠損、収入未済額について１点、もう一つは、決算書の２３６ページになりますが、財産に関する調書から１点お伺いをしたいと思います。不納欠損と収入未済の件です。この今後の取り組み、そして、今後のこの収入未済とか不納欠損についての数字の動きをどういうふうにされていこうとしているのかというのをお聞きしたいと思います。","respondent":"福田会計管理者","answer":"３.８％を、来年は２％台に行くかどうかはわかりませんけれども、全庁を挙げてそういうふうな気持ちで取り組んでまいりたいと考えています。","voiceIndex":380,"id":"exchange-161"},{"speaker":"若林委員","kind":"質問・要望","question":"確認といいますか、今後のために、今取り上げました条例の中で、収入未済額、国と都の支出金は当然除きますけれども、この中でこの網のかかる部分というのはどれに当たるのか。","respondent":"福田会計管理者","answer":"一つは私債権。世間のどこにでもある債権です。もう一つは、自力執行力のない公債権。３番目が、例えば税金のように、自力執行力のある公債権です。私債権等の管理に関する条例の守備範囲ですが、これは私債権と、それから自力執行力のない公債権、これを守備範囲としております。","voiceIndex":382,"id":"exchange-162"},{"speaker":"若林委員","kind":"質問・要望","question":"ありがとうございました。大変なお仕事、しっかり頑張っていただきたいと考えています。それから、財産に関する調書のほうですが、事項別明細書の２３６ページ、行政財産には公共財産と公共用財産があります。普通財産のほうは増えている。それから普通財産は増えている。この公共財産調書から、区はどういうことを区民にわかってもらいたいのか、こういうことを一つお聞きしておきたいと思います。","respondent":"平澤経理課長","answer":"で、この財産につきましては、行政財産にしろ、普通財産にしろ、区の大きな規模の財産ですので、しっかりした管理をしていくということには変わりないということでございまして、区が区民の方にどういうところを酌み取ってほしいかですが、区として行政を進める上で。","voiceIndex":384,"id":"exchange-163"},{"speaker":"若林委員","kind":"質問・要望","question":"そのとおりだと思います。あえて政策的に、例えば品川区は区有施設中長期改修計画とか公共施設の活用プランというのを出しております。そういう中で、現状のこの財産に関する調書、公有財産をどういうふうに見ていくか、また今後勉強して質問させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":386,"id":"exchange-164"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうすると、例えば予算の立て方というのは、多分過去いろいろあった実績を取りまとめて予算立てをするとか、あとは、実務でこれぐらいかかるとか、いろいろそういうのを積み上げて、これぐらいかかるのではないかというふうにしてきていると思うんだけど、そこら辺の基本的な考え方、全体的に、細かく指定管理者がどうとか、委託がこうだとか、あまり聞かないので。","respondent":"本城企画財政課長","answer":"補正と流用の考え方ですが、当初予算を立てた後の事情の変更に対応するということで、基本的には補正予算で対応できるものについては対応するのが基本と考えているところですが、ただ、事業の執行を迅速にするという、その適時にするということもありますので、その考え方の中で。","voiceIndex":388,"id":"exchange-165"},{"speaker":"石田（秀）委員","kind":"提案","question":"そういうところをやるときに、どういう入札制度の仕方をしているのかというのを教えてほしい。それであるならば、普通に入札するならこの金額と言われれば、それで終わりではないですか。これがいいのかどうかわからないけど、駐車場契約するときに、最低価格を出すわけよ。そういう収入を上げるために、皆さんがどういう契約をする考え方を持っているのかなというのをぜひ教えていただきたい。","respondent":"多並公園課長、江部健康課長、日下部企画部長","answer":"公園の駐車場につきましては、都市公園法という法律の中で、設置・管理許可という形を使わせていただいております。事業者の努力によりまして、欠損が出た場合には事業者負担であるし、利益が出た場合には還元されるという方式でやっております。ただし、その当事者、事業者にとっても利益が上がる。こういうような方式をできるだけ幅広く活用するという方向で今進めているところです。","voiceIndex":390,"id":"exchange-166"},{"speaker":"石田（秀）委員","kind":"質問","question":"だけど、利用率を考えたらそうでもないなと言えば、リターンが来ることを考えるなら、そこが満タンになるような政策は何って、そこにもう１回突っ込む、契約の後にね。そういう選定を誰がして、そういうところでしっかりそういうことで後追いもしていくよというような体制が私はこの予算立てのときに必要な気がして、だから、こういう不用額も含めて、もう一段そこら辺の考え方を教えてもらえればと思います。","respondent":"日下部企画部長","answer":"不用額につきましては、実は執行実績、つまり契約落差もありますけれども、実際は執行実績がかなり大きく当初見込みよりも減っているという事例があります。これを例えば具体的に申し上げますと、生活保護、子ども手当、それから融資あっせん。","voiceIndex":394,"id":"exchange-167"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1356#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":119711,"voices":396}},{"id":"h24-20121003-4","meetingId":"h24-c-settlement","date":"2012年10月3日","dateIso":"2012-10-03","committee":"決算特別委員会","time":"午前１０時００分～午後５時１５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を172件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"ます前に、昨日、南委員より発言のありました資料要求の件につきまして、先ほど、理事会において検討いたしました結果","agenda":"ます前に、昨日、南委員より発言のありました資料要求の件につきまして、先ほど、理事会において検討いたしました結果","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"成果報告書１１０ページの庁舎等維持管理費、それから１１７ページの区民施設費と思っているんですけれども、そのあたりでお伺いさせていただきたいと思います。震災を受けてということもありますけれども、庁舎が安全だということを広くアピールしたほうがいいかと思うんですけれども、その辺のお考えがあれば、お聞かせください。","respondent":"平澤経理課長","answer":"庁舎の耐震化、平成２３年度で終了したところですが、そちらにつきましては、庁舎入口３階に、実際に免震ダンパー等をかなり長い期間、置かせていただきまして、広報等に努めた次第です。","voiceIndex":4,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"そういったアピールが大切だということはあると思うんですけれども、その一方で、災害時の庁舎のあり方ということで、庁舎は避難所ということではないと思うんですけれども、震災が起きたとき等、避難してこられる方が実際はいるかと思うんです。それから、今、ちょっと話が戻りますけれども、避難してきた方への対応は、どんな施策をとられているのでしょうか。","respondent":"平澤経理課長","answer":"ハードの部分について、ご説明させていただきたいと思います。現在、例えば停電になった場合に、第二庁舎につきましては、７２時間の非常用電源を確保しており、本庁舎につきましては、２５時間の非常用電源が確保されているところです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"沢田委員","kind":"意見","question":"そういった防災対策も、区民の方にもお願いしている部分もありますし、これだけ２,０００人以上の方が区役所でも働かれているということですので、そういった業務を続けていくこと、それからまた、避難されてこられる方がきっといると思いますので、そういった方への対応を進めていってもらいたいと思います。","respondent":"平澤経理課長、小林施設整備課長","answer":"はじめに、総合庁舎につきまして、ご説明させていただきたいと思います。太陽光パネルですが、第二庁舎に設置されておりまして、３kw程度ですが、発電能力があるです。区有施設を新築、改築する場合には、ＬＥＤの電球を優先的に使っております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういった制度があるということは、やっぱりそれは積極的に区としても進めていってほしい施策だと思います。そういった意味でも、今、いろいろ検証がされているというお話がありましたけれども、節電には大変効果があるということはわかっているので、区としても助成制度を設けているんだと思いますので、ぜひとも、進めていっていただきたいと思います。","respondent":"平澤経理課長、野呂瀬環境課長","answer":"ＬＥＤにつきましては、電球タイプのものは大分規格が統一されてきたというところではありますが、蛍光管タイプのものにつきましては、先般、新聞報道でもございましたとおり。庁舎の環境に関する部分ですけれども、地域推進計画というものを策定しておりまして、その中で、品川区役所は率先して設備を導入することになっておりますので、今後も、そのような形で進めてまいりたいと考えています。","voiceIndex":11,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"ぜひとも、そういった形で率先して、区が先頭に立ってやっていただきたいと思います。最後にちょっと時間が残ったので、防災協定のことでお伺いしたいんですけれども、先日、港区がＪＲとの防災協定ということを発表されていました。品川区も大井町駅、それから大崎駅、五反田駅、目黒駅というＪＲの駅がありますけれども、こちらのほうの防災協定というのは、どんな形で進んでいらっしゃるのでしょうか。","respondent":"鈴木防災課長","answer":"大井町駅等区内のＪＲにつきましても、それぞれの駅の実際の対応を見極めながら、区としても協力できるところがあれば協定等の方法で協力体制を築くとともに、現在ももう、通信機を配備したり、連携体制をとっておりますので、今後も積極的に協力をしていきたいと考えております。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鶴委員","kind":"質問・要望","question":"私のほうからは、１０９ページ、職員研修費、それから１２１ページの地域防災計画改訂検討委託、１２２ページ、備蓄物資購入、災害時要援護者支援経費は、関連して質問させていただきたいと思います。これは、執行率が７５.６％となっておりますけれども、事業として何か工夫をされて、この率までに圧縮できたということか、それともほかの要因があるのか、そのあたりをまず教えてください。","respondent":"堀越人事課長","answer":"研修についての執行率の関係ですが、最初、予算の段階で、受講人数等の見積り等々の違いもあります。それから、あわせて講師につきまして、内部講師を活用しまして、その分で効率的な執行に努めた結果である、そのように理解しています。","voiceIndex":17,"id":"exchange-006"},{"speaker":"鶴委員","kind":"質問・要望","question":"人数の見積りのところとか、あとは内部講師に変更してという工夫があったということで理解いたしました。そのうえで、内容のところに関連して、人権教育もこの職員研修の中で行っていると伺っておりますけれども、概要で結構ですので、どういうような内容なのか教えていただきたいと思います。","respondent":"中山人権啓発課長","answer":"人権については、昇任時、それから新人採用時、そういう各節目の研修のほかに、全体を通してやっているところなんですが、どうった研修かということになりますと、全般的な人権課題について、改めてお話しするとともに、そのときどきの節目に合わせて、例えば新人であれば。","voiceIndex":19,"id":"exchange-007"},{"speaker":"鶴委員","kind":"質問","question":"昇任時とか、新人研修、あとは全体の研修の中でそれぞれ行っているということで、その内容の部分なんですけれども、講師を呼ぶとか、見るものがあるとか、その辺をもうちょっと詳しく教えていただければと思います。","respondent":"中山人権啓発課長","answer":"直接講師をお願いするケースは、できるだけ当事者の方にご登壇いただいているんですが、ほかの人権研修は、私が講師をしていますので、できるだけ具体的にイメージが沸くように、例えば、こういった差別の実態がある。","voiceIndex":21,"id":"exchange-008"},{"speaker":"鶴委員","kind":"提案","question":"取り組みの中で、教材としてひとつ提案をしたいと思います。例えばインドの内容であれば、全国の公立学校で教員に研修を実施して、３０万人が受講されたということであります。そうした意味からも、職員の皆様一人ひとりが人権文化の担い手となっていただくということも含めて、この教材はネット上で見ることができますので、ぜひ有効に活用していただきたいと思いますけれども、いかがでしょうか。","respondent":"中山人権啓発課長","answer":"私も実はウェブサイトで見させていただきました。大変いい教材だと考えていますので、職員研修、あるいは、教職員研修でも人権研修をやっておりますので、そういった中での活用も考えてまいりたいと考えております。","voiceIndex":23,"id":"exchange-009"},{"speaker":"鶴委員","kind":"質問・要望","question":"それは、こうして学んだ方々が、区で言えば、職員の一人ひとりが区民の方と接する中で、所作とか、振る舞いを通じて区民の一人ひとりにも、まさに品川区でも宣言をしておりますけれども、人権について高い意識を持っていただく、これは非常に大事なこと思いますので、ぜひ進めていただきたいと思います。最初に、災害時要援護者の該当者を、品川区としてはどういうふうに認識しているのか、教えてください。","respondent":"鈴木防災課長","answer":"具体的には、一つ目の該当者は６５歳以上の高齢者の方。それから、二つ目が障害者手帳で第１級から第３級までの手帳をお持ちの方、それから、その他、特にご本人が希望される方が対象となっております。","voiceIndex":25,"id":"exchange-010"},{"speaker":"鶴委員","kind":"質問・要望","question":"６５歳以上、それから障害者手帳１級から３級をお持ちの方と、最後が本人の希望となっております。災害時要援護者がどういう方かという中に、例えば妊婦の方とか、難病に指定されている方、それから希少疾病等の方も、しっかり明文化させていくことが大事じゃないかなと思いますけれども、その辺の認識を教えていただきたいと思います。","respondent":"鈴木防災課長","answer":"新しい計画の中には、そのような対応についても盛り込める予定で、現在、考えているところです。","voiceIndex":27,"id":"exchange-011"},{"speaker":"鶴委員","kind":"質問・要望","question":"今のご説明で非常に安心をしました。そのうえで、今まさに順次やっていただいていると思うんですけれども、品川区としてよく言われるところの、今の要援護者への対応という部分で、だれがどこへ避難させるか具体的に定める個別計画があると思うんですが、これを品川区で、今策定しているかどうかも含めて、これからの取り組みも含めて、教えていただきたいと思います。","respondent":"鈴木防災課長","answer":"それ以外の専門的な対応が必要な方につきましても、先ほど申し上げましたように、現在、各所管課と調整をしておりますので、その中で具体的な対応を定めて、今後も一人ひとりの個別プラン作成をしていくということで考えております。","voiceIndex":29,"id":"exchange-012"},{"speaker":"鶴委員","kind":"質問・要望","question":"なおかつ、今、名簿の取り扱い、個人情報の観点とかがあります。中にすばらしい備蓄物資がそろっていても、それを入れている箱というんですか、それがぐしゃっとなってしまったら、搬出もできないし、使いものにならなくなってしまっては元も子もないので、そうした備蓄倉庫の耐震化、建て替えとかも含めて、この態勢も必要かと思うんですけれども、その辺のお考えがあれば教えていただきたいと思います。","respondent":"鈴木防災課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"１０９ページの人権と、男女共同参画についてと、１１１ページ、結婚サポートについて、お伺いします。結婚サポートは、この事業が始まってから、私はずっと質問をさせていただきました。そんな中で、今回出された事務事業評価の中でＣという形になっていますが、このことについて、まずお伺いします。","respondent":"久保田地域活動課長","answer":"そうした中で、また、平成２４年度の事務事業評価におきましても、実施している中で、いろいろ課題もあるというところもありますので、もう一度、この実施している内容を踏まえまして、見直しをかけていきたいということでＣ評価とさせていただいたです。","voiceIndex":34,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"最初、この事業が始まった趣旨と大分変わってきてしまって、見直すのかなという思いもあるんですけれども、私は、ずっとこれは言い続けてまいりました。個人的な考えですけれども、こういう結婚とかは民がやる仕事だと思っています。民ができることは民がするという思いで、こういう質問をさせていただいているんですけれども、その辺については、どうでしょうか。","respondent":"久保田地域活動課長","answer":"そうした中で、民間の役割というところはあろうかと思いますけれども、自治体がこういった事業に取り組んでいくという意義はあるものと考えています。","voiceIndex":36,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"わかりました。次に、ＤＶについてお伺いします。配偶者のＤＶと、デートＤＶと分けてお伺いしたいとお伺いしたいと思います。デートＤＶからお伺いしますけれども、平成２２年に調査をしたと思うんですけれども、デートＤＶの調査というのは、全国的にも珍しいと思っているんですけれども、大体の概要について、どのような調査項目と、なぜ調査を行ったのか、お伺いします。","respondent":"中山人権啓発課長","answer":"調査項目になりますが、基本属性、これは性別や年齢、学生かどうか、収入があるかないか、それから日ごろの考え方として、自己肯定感、要するに自分を好きかどうかということですが、それから暴力に対する考え方、交際経験の中でデートＤＶをされた経験、あるいは、した経験。","voiceIndex":38,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"ＤＶ相談がある中で、デートＤＶの相談はどのぐらいの割合を占めているかということと、それから、デートＤＶに関しては、法律の対象外だと思うんですけれども、区が対策を行う意義といいますか、その辺を教えてください。それから、調査結果から、今見えてくる課題はどういうことなのか。今後、区として、どういう対策をしていくのか、お伺いします。","respondent":"中山人権啓発課長","answer":"法の対象外であるデートＤＶを、区が実施する意義ということになりますが、先ほどの説明とちょっと重なりますけれども、ＤＶはある種、法ができております。その法に従って、相談者を支援するさまざまな手だてもできております。","voiceIndex":40,"id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"ＤＶの特徴として、その方がＤＶを受けていることを感じないということとか、ありますよね。だけれども、私は、これこそ公がやる仕事だと考えていますので、やっぱり行政が介入をどんどんして、邁進していっていただきたいと思います。そんな中で、平成２３年３月に、配偶者暴力対策基本計画というのを品川区はつくりましたが、これの特徴について、お伺いします。","respondent":"中山人権啓発課長","answer":"それにあわせて、実際に被害を受けられた方に対して、きちっとした相談と、その後の支援体制の整備、それから、私ども、相談に乗る人材の育成、それから、やはり全体で暴力を許さないという態勢が必要だと考えていますので、区の中の体制整備、それから。","voiceIndex":42,"id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"ＤＶ法の第２条で、二つ、これは行政の責務だという形でうたっているんですけれども、一つはまず、被害者の保護ですよね。もう一つは、被害者の自立支援。この二つがＤＶ法に出てくるんですけれども、まず保護についてですけれども、やはり逃げてくるわけですよね。その辺に関して、どういう形で、区として被害者を守っていくのか、教えてください。","respondent":"中山人権啓発課長","answer":"ただ、これはもちろん、言ってしまっては何もならないことなので一切お答えできないということで、うちの相談部門もやっておりますし、あるいは、関係する機関というところでは、戸籍住民課であれば、住民票や戸籍の附票といったものを出さないようなガードということも。","voiceIndex":44,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"戸籍、住民票というのは、まさに行政しかできないことですから、絶対に流れないように、法律上ブロックしていると思うんですけれども、これはもう守ってください、よろしくお願いします。それから、自立支援のところですけれども、やはり経済的なことをちゃんとしていないと、ここはほんとうに悲惨な結果になってしまうと思うんですけれども、自立支援については、いかがでしょうか。","respondent":"中山人権啓発課長","answer":"ですから、そういった状況を、相談の中でしっかりと受けとめながら、その方が次のステップに向けて一番いいあり方を支援員が一緒になって考えていくということになろうかと思います。","voiceIndex":46,"id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"こうやってＤＶの質問をさせていただきましたが、私は思うんですよ、根本的に違っていると。根本というのは何か。加害者は普通に生活をしている、おかしいですよね。被害者が隠れなくちゃならない、これはどう考えてもおかしいと思う、理不尽だと思うんです。一自治体では変えられないかもしれないですけれども、そういうことを踏まえて、今後のＤＶ施策について、どう考えているか、最後に教えてください。","respondent":"中山人権啓発課長","answer":"確かにおっしゃるとおりかと思います。ただ、法律ができて、今ここまでやっときたというところですので、今後の課題ということで考えてさせていただきたいと思います。","voiceIndex":48,"id":"exchange-021"},{"speaker":"向委員","kind":"質問","question":"１０９ページの職員研修費に当たるんでしょうか、区職員に対するコンプライアンス研修ですとか、懲戒処分云々に関することをお尋ねしたいと思います。私はちょうど１年前の決算特別委員会で、看板がないのでよくわかりませんとお尋ねした記憶がありますけれども、その後、どうなったのか。看板ができたという話をちらっと伺っているんですけれども、そのあたりをお話しいただけたらと思います。","respondent":"久保田地域活動課長","answer":"マウントしながわの看板ですけれども、里山再生に従事されている方々のお力によりまして、頂上よりちょっと下のあたりなんですけれども、看板をつけさせていただいて、川を挟んだ反対側の道路から、ここはマウントしながわだとわかるようになってあります。","voiceIndex":51,"id":"exchange-022"},{"speaker":"向委員","kind":"質問","question":"川のほうから見て、見上げるともうわかりやすく、車とかで行ってもすぐにたどり着けるような看板が立っているということで、よろしいでしょうか。決算の費用としても、４７３万円ということで数字が出ていましたけれども、今後の展望については、区として、どのようにお考えなのでしょうか。","respondent":"久保田地域活動課長","answer":"事業のほうも、平成１９年度から始めてありますけれども、５年以上経過した中で、今後どういった方向で考えていくのかということ、またどこまでいくと整備が終わるのかというか、到達点というか、目標といったところも。","voiceIndex":53,"id":"exchange-023"},{"speaker":"向委員","kind":"質問","question":"よくわかりました。ほかにもお伺いしたいことがあるので、また、別の機会にお尋ねしたいと思います。１０９ページ、職員研修費の中に入っていると考えていいんでしょうか、区職員のコンプライアンス研修、懲戒処分等に関することをお尋ねします。日ごろから、区民サービスの質の担保ですとか、向上については、品川区として、たくさんのご努力をしてくださっていることを、心から感謝しています。","respondent":"堀越人事課長","answer":"内容につきましては、公務員の特性、公平性ですとか、中立性といったことから始まりまして、もちろん全体の奉仕者であること、それから、地方公務員法上の法令遵守が求められるといった、こういった内容について研修を行っているものです。","voiceIndex":55,"id":"exchange-024"},{"speaker":"向委員","kind":"質問","question":"基本的に随時ということで、例えば、年に１回必ず職員が受けなければいけない研修、同じことの繰り返しかもしれないですけれども、毎年１回は理念だったり、道徳的なこと、コンプライアンスとかをおさらいするような研修というのは、特に今のところはないということでよろしいでしょうか。飲酒運転とか、痴漢とか、盗撮とか、放火、セクハラいろいろあると思います。","respondent":"堀越人事課長","answer":"そういった中身の中で、公務員倫理というコンプライアンスの要素も入れながら進めておりますので、そういった中で適切に対応していると思ってあります。","voiceIndex":57,"id":"exchange-025"},{"speaker":"向委員","kind":"質問","question":"わかりました。品川区としても、職員の分限懲戒審査委員会規程というものがあると思います。平成５年にできて、一番最新で平成１９年に改正されたと伺っています。こういった審査委員会というのは、どういう経緯でできたのか、それが、処分を下さなければいけないようなときに、きちんと機能しているのかどうか、そのあたりをご説明ください。","respondent":"堀越人事課長","answer":"審査委員会についてですが、平成１９年ということで、今、ご紹介をいただいたところです。職員に対する処分について、その適正をしっかりと期していく、そういうことを目的としてつくったものです。","voiceIndex":59,"id":"exchange-026"},{"speaker":"向委員","kind":"質問・要望","question":"わかりました。最後にちょっと、この不祥事、コンプライアンスの件なんですが、区の職員の皆さんで、フェイスブックとか、ツイッターとか、ミクシーとか、それはもうプライベートの部分で、あまり関与されてないかもしれないのですが、このあたりに対する制限というか、規定のようなものは内部的に設けられているのでしょうか。","respondent":"堀越人事課長","answer":"その規定についてですけれども、品川区職員のソーシャルメディアの利用に関するガイドラインを設けまして、これも全職員に周知をして、こういう規定の中で行っているものです。","voiceIndex":61,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、１１２ページの情報公開経費に係わって、品川区の情報公開に対する基本的な姿勢と、各種審議会、また、区の委員会の公開状況を中心に伺いたいと思います。その改正の趣旨を伺いたいと思います。そこで、各種審議会の公開状況を伺いたいと思います。傍聴者に資料を配っている審議会は何か、配っていない審議会は何か、それぞれ主なもので構いませんので、現状をご説明いただきたいと思います。","respondent":"荒井広報広聴課長","answer":"情報公開についてのお尋ねです。２００４年に条例を改正した主な趣旨というお尋ねですが、情報公開につきましては、原則公開という立場は変わっておりません。２００４年に改正した主な趣旨といたしましては、非公開情報をやや広げたというところが主な趣旨です。","voiceIndex":66,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"原則公開というのは変わっていないと。審議会では、現在、１０審議会が公開されているということです。一方で、都市計画審議会では、当日、傍聴者への資料配布が行われるようになりました。条例で定める、原則公開を貫くのであれば、まずは公開している会議については、傍聴者に会議資料を配布すべきだと思いますが、いかがでしょうか。情報公開条例の理念に照らして、どうお考えなのか伺いたいと思います。","respondent":"荒井広報広聴課長","answer":"それぞれの委員会の審議の過程で、傍聴者に資料を配ってより委員会の様子を理解していただくほうがいいという考えに立って、資料配布するところもありますし、また途中経過について、あやふやな情報、審議過程の情報については。","voiceIndex":68,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"審議会も含めて、それぞれの会議に品川区は事務局として参加しています。その情報公開条例の原則公開の趣旨を説明し、それに沿った運営を求めていくということも必要な対応ではないでしょうか。改めて、まずは公開されている会議について、傍聴者への資料配布を求めてますが、ご説明いただきたいと思います。原則公開と照らして、回収はやめるべきだと思いますけれども、いかがお考えでしょうか。","respondent":"荒井広報広聴課長、山崎マスタープラン担当課長","answer":"委員会を公開するか、あるいは非公開で行うか、また、その委員会をどういう形で運営していくか、これは資料配布も含めた考え方ですが、それにつきましては、それぞれの審議会、委員会に任されていることであると考えているところです。先週、２８日金曜日に、マスタープラン策定委員会で、傍聴人の方の資料につきましては、会の冒頭に、会議に資する資料という前提で傍聴者に対してご配布をします、ただし、終了後には回収をしますということで。","voiceIndex":70,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"資料配布も含めて、それぞれの運営は任されていると言いますが、区は、その運営でよいのかと、その姿勢を伺いたいと思います。マスタープラン策定委員会の資料回収について、委員会の冒頭で、確かに諮られましたが、なぜ冒頭で委員会終了後の回収を求めなければならないのか。こうしたところは、原則公開の趣旨に沿ってしっかり運営を改善していくべきだと思いますが、いかがでしょうか。","respondent":"荒井広報広聴課長、山崎マスタープラン担当課長","answer":"区といたしましては、審議会およびそれぞれの委員会に運営につきましては、それぞれの委員会の特性がありますので、そちらのほうに、引き続き任せていきたいと考えているところです。まちづくりマスタープラン策定委員会につきましては、傍聴の取り扱い要領を定めておりまして、その要領に基づいて適正な運営を行ったです。","voiceIndex":73,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば、冒頭に配った資料について、中身に変更があることは、質疑を通じて十分にあり得ます。どうしてもそこを理由にするのであれば、校正中にて取り扱い注意という判こを押して傍聴者に配れば何ら問題はないはずです。こうした姿勢はしっかりと改めていただきたいと思いますし、みずから定めた条例の趣旨に沿って運営を、重ねてお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-032"},{"speaker":"渡辺委員","kind":"質問","question":"私は、成果報告書１１６ページ、１１７ページにまたがります学校開放運営費、また公園運動施設費のところで、使用時の音響というか、声援も含めて、そこのところで伺っていきたいと思います。はじめに言うと、これはすごくまたがるので、施設という点で絞って伺えればと思います。あるいは、件数は、大まかな数が構いませんが、どう把握されているのか、まず伺いたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"ただいま、スポーツ・文化を通じて騒音と申しましょうか、かけ声と申しましょうか、それに対して、近隣の皆様に影響を及ぼすです。スポーツを進めていくうえで、私ども、進めているのが学校体育館並びに学校の施設全てです。","voiceIndex":78,"id":"exchange-033"},{"speaker":"渡辺委員","kind":"質問","question":"かなりしっかり把握はされていると思います。そういう意味で、何か基準といいますか、今、対応のところで、学校施設がまずあります。それから、公園などにしても、統一した見解だとか、基準はあるべきものなのか。行政といっても所管もそれぞれありますが、現状で、学校施設、あるいは公園施設の点で、どのような対応をされているのか、教えてください。","respondent":"安藤文化スポーツ振興課長","answer":"行政の対応につきまして、まず大きく二つ挙げします。一つは、学校の施設。これはすべての学校を、学校教育に支障のない範囲で開放しています。","voiceIndex":80,"id":"exchange-034"},{"speaker":"渡辺委員","kind":"質問・要望","question":"多少施設によっては性格が異なりますが、２点、僕が申し上げたいのは、利用者も知らない中で、うっかりのミス的なものでのマナーとかはあるかと思います。ただ、今、注意啓発は、所管をはじめすごくやっているから、大概の方は守っているかと思います。その点も一つ。その辺の区分けをしっかりとしたうえで、毅然とした基準なり、対応をしていただきたいと思うんですが、その辺はいかがでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"私ども、スポーツをする側と近隣の方々が共生できるような、スポーツを通してまちづくりをしていこうということを我々第一に考えています。そんな中で、話し合いによって、お互いに守るべきものは守って協力していければ最高だと考えています。","voiceIndex":82,"id":"exchange-035"},{"speaker":"阿久津委員","kind":"質問・要望","question":"私からは、１１４ページ、地域振興費の中から、町会ホームページ制作支援等、１１５ページ、地域振興費、近隣セキュリティシステム運営経費、できれば、１２２ページ、防災対策費の中から災害時応急物資確保費、学校避難所管理費、防災関係組織経費に関して、お伺いします。最初に町会ホームページ制作支援等について、お伺いいたします。サーバーなどを利用した場合、これは有料なのか、どうか。","respondent":"久保田地域活動課長","answer":"講師は、明治大学地域コミュニティシステム研究所の研究推進員にご説明をしていただいております。","voiceIndex":85,"id":"exchange-036"},{"speaker":"阿久津委員","kind":"質問","question":"第二義的には、やっぱり特に東品川の地域なんていうのは、海沿いに高層マンションがたくさんできまして、新しい住民の方、若い世代の方が引っ越して来られていますので、そういう方が町会活動とかに興味を持ったときの入り口といいますか、直接、町会の方とお話をすると、今後、近所同士ですから、活動を始めないときまりが悪かったりして、なかなかそういうのを踏み出せない方にとっての。","respondent":"久保田地域活動課長","answer":"新しく引っ越してこられた方、また引っ越しを考えておられる方につきましては、ネットで気軽に自分の引っ越し先の地域がどうなっているか、町会がどうなっているかを見ることができるという意味では、非常に効力があるということです。","voiceIndex":87,"id":"exchange-037"},{"speaker":"阿久津委員","kind":"質問","question":"３２町会でホームページが立ち上がっているということなんですが、いろいろ工夫をされている町会もあると聞いているんですけれども、そこら辺、何かホームページならではの情報発信や活用している町会を、もし区で把握しているのであれば、ちょっと１例ぐらい、教えていただければと思います。","respondent":"久保田地域活動課長","answer":"先ほども言いましたけれども、こういった行事があるので参加してくださいということで、広く呼びかけて、それを見て参加をしてくれる方もいらっしゃると聞いてあります。","voiceIndex":89,"id":"exchange-038"},{"speaker":"阿久津委員","kind":"質問・要望","question":"これは要望です。経済産業省なんかも勧めているんですけれども、地域住民が主体となって、地域が抱える課題をビジネスの手法によって解決し、また、コミュニティの再生を通じて、その活動の利益を地域に還元すると、ちょっとややこしい事業の解説なんですけれども、こういった手法が活用できないのか、その点について、区の見解をお聞きしたいと思います。","respondent":"久保田地域活動課長","answer":"明治大学の研究所の方も、そういった認識を持っていらっしゃいますので、こういう方のご意見、専門家のご意見も聞きながら、更新についても、何か支援ができないかということは研究してまいりたいと考えています。","voiceIndex":91,"id":"exchange-039"},{"speaker":"阿久津委員","kind":"確認","question":"続きまして、１１５ページの地域振興費、近隣セキュリティシステム運営経費のことで、１１ページに事業内容が書いてあるんですけれども、通報件数８,６４０件のうち、ほぼ誤報だと思うんですが、緊急発報が１６件ということで、児童の安全を確認とありますので、何事もなく、ほんとうによかったと思いますし、まもるっちのシステムというのは、品川区としてほんとうに誇るべきものだと考えております。","respondent":"中川原地域振興事業部長","answer":"緊急発報についての内容と、それへの対応のお尋ねです。緊急発報１６件につきましては、凶悪犯対応というよりは、子どもが不安に思って、怖いおじさんがいるので、殴られそうなので発報したとか、その程度のものがほとんどです。","voiceIndex":93,"id":"exchange-040"},{"speaker":"阿久津委員","kind":"質問","question":"私も管内の警察署に登録しているんですが、結構頻繁に不信者情報、子どもに対する暴行とか、公然わいせつ、声かけ等の注意メールが届くんです。このセキュリティシステムとは全く別の、もちろん警視庁が出しているメールなんですけれども、学校関係者なんていうのは、このメールを把握しているんでしょうか。生活安全担当課長のほうにきているのかどうか、そこら辺の体制について、教えてください。","respondent":"中川原地域振興事業部長","answer":"メール警視庁につきましては、もちろん生活安全担当課長のほうにも届いておりまして、事案によりまして、こちらから詳しく問い合わせて、それについて必要な危機管理室とか、学校と連携を取りまして対応をする、そういう形になっております。","voiceIndex":95,"id":"exchange-041"},{"speaker":"阿久津委員","kind":"質問・要望","question":"最後に１点だけ、１２２ページ、防災対策費のところで、この前、津波ワークショップで、東品川のある小学校で、海抜が低いんですけれども、想定外のことが起きた場合、浸水をした場合を考えて、備蓄物資を高いところに置いたらどうだという発言が、そのときにありました。これは、私も発言をしているんですが、この点について、最後に確認をさせていただいて終わりたいと思います。","respondent":"鈴木防災課長","answer":"お尋ねいただきました学校避難所の備蓄物資の保管場所ですが、学校区民防災組織、防災課で、連絡会を通して検討している仕組みがありますので、その中でお話を伺いまして、対応したいと考えております。","voiceIndex":97,"id":"exchange-042"},{"speaker":"原委員","kind":"質問","question":"すみません、一応、全部先にお話をしてしまいます。それから、歩行喫煙につきましては、実際の問題として、５カ所、美化推進区域というのがあると思うんですけれども、過料というんですか、一般に言われる罰金みたいなもの、その辺のところはどうなっているのかということ。集中豪雨対策、１５３万４,８３７円に関しては、どんなものであったかということを、お聞かせいただければと思います。","respondent":"武内総務課長、柏原行財政改革担当課長、中川原地域振興事業部長、鈴木防災課長","answer":"成人式ですけれども、ここ３年間の出席状況をお話しますと、該当者が２,５００人ぐらいですと、約半数ぐらいの方の出席があります。来年度に向けまして、既存建物解体に向けた形で動いていくことになりまして、平成２７年度開設という目標で、今、動いているところです。美化の活動につきましては、シルバー人材センターを中心としたところにお願いをしまして、仕事としてお願いしています。","voiceIndex":100,"id":"exchange-043"},{"speaker":"原委員","kind":"質問・要望","question":"平塚橋会館につきましては、了解いたしました。というのは、案内が来る来ない、これがまた新年のスタートですし、そこから品川区に対する区民の見方が大きく変わってくるというか、各町会長、各団体だけではなくて、そのすそ野を広げていただきたいという思いがあるものですから、その辺のご答弁をいただければと思います。よろしくお願いします。","respondent":"武内総務課長、中川原地域振興事業部長","answer":"その対応ができるように部屋を分散する、あるいは、時間帯を変えて２回開催するだとか、そんなようなことも、今後検討して、言われるとおり、効率的な新年名刺交換会の開催をしていきたいと考えております。ポイ捨てのマナーアップについての啓発の周知方法ですが、横断幕と、路上にシールを貼っておりまして、それぞれ約５００枚ほどです。ただ、横断幕につきましては、裏表で、歩道からも車道からも見えるような形でセットしているものです。","voiceIndex":107,"id":"exchange-044"},{"speaker":"原委員","kind":"質問・要望","question":"やはりガードレールに設置されていると、これは品川区の問題と、実際には国道沿いですから、東京都の関係だというような問題ですとか、具体的なところを申し上げてしまいますと、私が喫煙するせいかもしれないんですけれども、大崎広小路から私の事務所まで１０ｍ間隔で床に貼ってあるんですね。その辺のところも、もう少し思いを語っていただければと思うので、よろしくお願いいたします。","respondent":"中川原地域振興事業部長、福島ものづくり・経営支援課長","answer":"各５００カ所については、増やすというよりは、やはり美観も大事ですので、耐久度に合わせまして、１年から３年ごとに貼り替えたり、つけ替えたりしておりますが、区民の方からも汚いというようなお声をいただきますと。こうした集積を生かしまして、ものづくりだけに特化するのではなく、業態や業種を超えた新しい先端ビジネス、そういったものの中心となるような拠点にしていくように、今後検討していきたいと思ってあります。","voiceIndex":110,"id":"exchange-045"},{"speaker":"原委員","kind":"意見","question":"大崎のほうなんですけれども、これはまだ産業経済費のところもありますので、導入、スタートの段階かなと思いますので、特に品川区、まだ大まかで結構なんで、すみませんけれども、もう一言、ご意見をいただければと思います。","respondent":"福島ものづくり・経営支援課長","answer":"そういう新しい産業がかなり集積していますので、そういったところと連携を取りながら、大崎を日本を代表するビジネス拠点としてつくり上げていきたいと考えている次第です。","voiceIndex":113,"id":"exchange-046"},{"speaker":"山内委員","kind":"質問","question":"１１０ページの庁舎維持管理に関することを、ちょっと伺いたいんですが、この庁舎なんですけれども、免震構造が終了いたしました。そうなりますと、あちらにも、今入っているのはヤマダ電機、それから、西友、さらにはいわゆるレストラン等が入っておりますが、この資産価値と同様に、ここも家賃を上げていることを、役所として考えていくのか、そのあたりのところをお伺いしたいと思います。","respondent":"平澤経理課長、安藤文化スポーツ振興課長","answer":"その財産台帳につきましては、３年に１回見直しをしているところでございまして、こういった修繕的なものについては、その価値の増ということは、今のところ、考えていないところです。きゅりあんにつきましては、１号棟、２号棟あります。そこにつきましては、大井町再開発ビル管理組合という組合があります。そんな中でも考えて、今後の検討課題にしていくだろうと考えています。","voiceIndex":116,"id":"exchange-047"},{"speaker":"山内委員","kind":"質問","question":"それはわかるんですよ、ですから今後の展望。改修をした後には、そういった家賃のアップというものが考えられるのかどうかということを、私は今聞いているんです。","respondent":"安藤文化スポーツ振興課長","answer":"１号棟につきましては区分所有で、区の持ち物、それから地権者の方々、いろいろ持ち物があります。そんな中での管理組合をつくってのものですので、今後検討します。","voiceIndex":119,"id":"exchange-048"},{"speaker":"山内委員","kind":"質問・要望","question":"わかりました。次にいきます。１１４ページの地域活動費の中で、町会に関することを伺います。そういう中で、建築確認とは別に、例えば、マンションデベロッパーは、品川区にいろいろと相談にくると思うんですよね。町会費を管理費に組み込んで徴収できないものかとか、そういったアイデアを要請できるのかなと思うんですけれども、今後の町会費に関することについて、ちょっと意見をいただきたいんです。","respondent":"久保田地域活動課長","answer":"私ども以外にも、例えば町会の会長とか、役員の方は、自分の町内にマンション等ができるということがあれば、積極的に建設会社、または管理組合に働きかけて、できた暁には、町会に加入をしてくれということでお願いをしています。","voiceIndex":121,"id":"exchange-049"},{"speaker":"山内委員","kind":"提案","question":"それはわかるんですけれども、管理費の中に組み込んだ、そういった具体的なところも提案をしていただければ、例えばそういった知識がないとは言わないけれども、マンションデベロッパーも、じゃあ考えようかなというようなことにもなっていくのかと思うので、これは要望として、最後に言っておきます。これは、ケーブルテレビの社長に伺いました。何でうちは見れないのかと。","respondent":"柏原行財政改革担当課長","answer":"ただ、品川区のケーブルテレビの考え方等もありますので、どういった形ができるかも含めて、ちょっと検討課題とさせていただければと思います。","voiceIndex":123,"id":"exchange-050"},{"speaker":"山内委員","kind":"質問","question":"ケーブルテレビ、今、自分が見れない状況でいると、これまで見れたんですけれども、やっぱり区の情報をつかみにくい。そうすると、なかなか品川区政に協力しましょうというような意気が高まらない。ですから、その辺を、先ほど、課長がおっしゃったように、強制はできないけれども、要請をして協力をいただくと、これが区政にまさに協力することではないかと思うんです。改めて、その辺をもう一度伺います。","respondent":"柏原行財政改革担当課長","answer":"ケーブルテレビ、区としても大切なメディアということで考えてありますので、その辺、できる限り前向きな形で検討していきたいと考えています。","voiceIndex":125,"id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"きゅりあんに続いて、荏原平塚総合区民会館が、共産党は直営でやってほしいと求めていますけれども、指定管理者制度になりました。こういった声が幾つも届いています。もう１点は、利用料金が高いうえに、一般区民のサークルなどの活動への支援というか、減免制度が全くないということで、なぜ減免制度がないのか、ぜひ、つくってほしいという立場でお伺いします。","respondent":"安藤文化スポーツ振興課長","answer":"今回できたものは、武蔵小山駅から歩いて１０分程度という距離的な部分を考えまして、いろいろな角度から考えて、きゅりあんの今現在の平米平均単価が１３.３７円で、それを２３区と比較しましても決して高くありません。これを採用させていただいたところです。","voiceIndex":129,"id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこをもう１回、伺いたい。きゅりあんの大ホール、１,０００名規模なんですが、平日の夜間に使うと２４万２,１００円。それから、きゅりあんと荏原平塚総合区民会館なんですが、区民と区民以外の二つの仕切りがあるんですが、ここの違いを教えてほしいんですが、区民とは、どういう人なのか。一般の区民と企業と同じ扱いになっているのか、どうか、そこをお伺いしたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"そんなところで、私どもも、区内の文化センター、または中小企業センター等の平米単価も調べ、またなおかつ、駅から徒歩１０分以上ある施設についても、１０施設の平米単価を調べてまいりました。","voiceIndex":131,"id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"集まる場所が欲しいということにおいて、会議室を比較すると、２倍から３倍も会場費にかかってしまうということにおいては、サークルの存続にかかってくるんですよ。ぜひここに差をつけていただきたい。一般区民の方がもっと気軽にできるように。企業の方に対してはもうちょっと付加をして、企業のために貢献をする施設ではなく、区民のための施設にしていただきたいのですが、いかがでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"減免制度につきましては、全然考えておりません。それからもう一つ、区民の概念ですけれども、事業所が区内にあって、そこに勤める方は非常に多うあります。そんな中で、事業者の方も、当然区民として位置づけさせていただいているところです。","voiceIndex":133,"id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"文化スポーツが、だれもが享受できるように、お金のない人もちゃんと活用できるように、減免とか、安い料金、ぜひぜひ実施をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-055"},{"speaker":"塚本委員","kind":"確認","question":"ふれあい掲示板は、よくお伺いする話として、この前の台風とかがありますと、剥がれて飛んでいってしまったりとかいうことで、貼ったり、剥がしたりにつけ加えて、ああいう悪天候とかがありますと、非常に見た目にもよろしくないですし、またそれを直しにいくのにも手間がかかるというようなお話をよく聞くんですが、その辺につきまして、区として、どういうふうなお考えなり。","respondent":"久保田地域活動課長","answer":"中には、例えば引き戸のついたようなものを設置できないのかといったような声もいただいているところです。","voiceIndex":137,"id":"exchange-056"},{"speaker":"塚本委員","kind":"質問・要望","question":"今、建て替え等の費用も、きちんと予算の半分ぐらいで計上されているということで、一定のサイクルというか、決まった時期等がくれば建て替えというような、ひどい状況であれば、それも新規に建て替えていくというようなことかと思うんですけれども、その際に、今言ったような地域のご要望、引き戸みたいなものがあったほうがいいのではないかとか、あるいは。","respondent":"久保田地域活動課長","answer":"そうしたものにつきましては、ガラス戸、またはアクリルの引き戸がついている掲示板を設置しているところでございまして、平成２３年度のふれあい掲示板で新しく建てたものすべてには、引き戸のついたものを設置しているところでございまして、今後も、地元の要望を聞きながら。","voiceIndex":139,"id":"exchange-057"},{"speaker":"塚本委員","kind":"質問・要望","question":"ふれあい掲示板だけではなくて、ちょっと話を広げて、地域センターの掲示板とか、屋内の掲示板、役所が管理している掲示板も含めてのお話を、ちょっとお伺いしたいんです。そういったところで、また防災の部分でも、いろいろな利用価値が出てくるかと思いますが、そういう電子掲示板というものに対して、将来、区としてどのように捉え、評価をされているか、お話を聞かせていただきたいと思います。","respondent":"荒井広報広聴課長","answer":"デジタルサイネージ、電子掲示板についてのお尋ねです。デジタルサイネージにつきましては、その有効性については、この間、防災、災害時の対応などでいろいろ見聞きしています。今後、どうしていくかにつきましては、さらに検討を進めていきたいと考えているところです。","voiceIndex":141,"id":"exchange-058"},{"speaker":"塚本委員","kind":"質問","question":"その一方で、品川区で言えば、大井、荏原、品川の三つの消防署ごとに、消防ボランティアという民間組織みたいなものがあって、それはいろいろ消防署ごとに登録をしているというような状況のようです。区といたしまして、消防ボランティアで、例えば、登録されている人数がどれぐらいいるかとか、日ごろどんな活動をしているのかとか、そういったことを、どの程度掌握されているのかお聞きしたいと思います。","respondent":"山口防災安全担当課長","answer":"実際の災害のときは、やっぱり消防庁は消防庁で震災対応をする、その中で厳格な指示、命令に従ってやらなければいけないものですから、災害時に、区がお願いするということはなかなか難しいと思います。","voiceIndex":143,"id":"exchange-059"},{"speaker":"塚本委員","kind":"質問・要望","question":"では残りの時間で、ちょっと要望みたいなことになりますけれども、他の地方自治体と違って、特別区においては、消防署というものが自分の管轄ではなくて、東京都というところでありまして、実際にはいろいろなところで消防庁との連携はなされているかとは思うんですけれども、やはり特別区としても大事なところだと思いますので、消防署との連携をしっかりお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-060"},{"speaker":"大倉委員","kind":"質問・要望","question":"私は、１２１ページ、防災対策費についてお伺いします。関連で、防災訓練、また災害時要援護者避難誘導ワークショップや、災害時要援護者名簿の取り扱いについて、お伺いできればと考えています。そこで、区として、どういうふうに関係があるのか、何か連携している部分があるのか、それを教えていただきたい。そうした訓練を、区としてはどのように捉えているのか、教えていただきたいと思います。","respondent":"鈴木防災課長","answer":"ほかにも港区や大田区、隣接区がありますが、各区とも災害時には連携をとって対応することが重要となりますので、日ごろから、特別区の防災担当課長会であるとか、城南地区での連絡会のようなもので連携体制をとっておりますので、今後も、その連携を強めながら。","voiceIndex":147,"id":"exchange-061"},{"speaker":"大倉委員","kind":"質問","question":"連携をとって構築しているところだというお話ですが、先ほど、最初に述べましたが、消防訓練、防災訓練をすることで、改めて何が必要か、課題とかがもちろん見つかることもありますけれども、実施をするということが、境目の人たちにとっても、例えば上大崎であったら、港区に逃げたほうが、状況としてはいいのではないかとか、そういった部分も踏まえて、区単体だとかなり限界がある。","respondent":"鈴木防災課長","answer":"地区ごとの連携というような仕組み、もしくはそのための訓練というメニューを考えておりますので、それを参考にして、今度は拡大をして、隣接区との連携、もくしは訓練のあり方もどのようにしたらよいかというようなところについては、研究、検討をしていきたいと考えております。","voiceIndex":149,"id":"exchange-062"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひ、そうした検討、研究をしていただいて、できれば実現させていただきたいと思います。次に、災害時要援護者避難誘導ワークショップについてお伺いしますが、この現状を教えていただきたい。要綱によると、多分明記がない、例えば防災区民組織、警察、消防への提供はしていると思うんですが、そういったところはどうなっているのか、教えていただきたいと思います。","respondent":"鈴木防災課長","answer":"要援護者ワークショップについてのお尋ねですが、まず現状といたしましては、各地区の防災区民組織の方々にお願いをいたしまして、ワークショップを実施していただいております。","voiceIndex":151,"id":"exchange-063"},{"speaker":"大倉委員","kind":"質問・要望","question":"民生委員は、持っていないということですね。区としては、全町会を網羅するのに、どういう働きかけをされているのか。そして、今、現状が、１０から２０町会ぐらいの数なんですが、それがどの程度で、いつまでに全町会１回は必ずやっていただくという目標があれば、教えていただきたいと思います。","respondent":"鈴木防災課長","answer":"要援護者支援のワークショップを、各町会で実施していただくということについての取り組みですが、まず、要援護者支援の仕組みにつきましては、災害時ふれあいシステムということで、今、お話にありました名簿の作成にとどまらず、実際の避難誘導のワークショップ。","voiceIndex":153,"id":"exchange-064"},{"speaker":"大倉委員","kind":"意見","question":"そうした部分で言うと、例えば、災害時要援護者の避難支援ガイドラインの中で、関係機関共有方式というのがあって、それを取り入れた渋谷区なんかは、区長の権限で、要援護者名簿を関係機関が使えるようになるというようなことも聞いておりますが、震災対策総合条例、渋谷区ではそういう条例がございまして、そういった区長のトップダウンというか、区長の権限である程度名簿を使えるような。","respondent":"鈴木防災課長","answer":"ですから、今後も、その辺につきましては、災害時のためで、訓練等であれば、個人情報の保護の観点を踏まえたうえで、さらに活用いただけるようにというお話をさせていただきたいと考えています。","voiceIndex":155,"id":"exchange-065"},{"speaker":"大倉委員","kind":"質問・要望","question":"最後に、防災ハンドブックを、今、全戸配布しておられると思うんですが、その中で、例えば要援護者とか、コミュニケーションが必要な方、例えば知的障害者や外国人にやったコミュニケーション支援ボードとかを取り入れる考えがあるのか、どうか、最後にお聞かせください。","respondent":"鈴木防災課長","answer":"今、ご質問がありました、支援に関する内容も含めまして、現在、改訂中のハンドブックの中に反映をさせていただいて、区民の皆さんに周知したいと考えております。","voiceIndex":157,"id":"exchange-066"},{"speaker":"本多委員","kind":"質問","question":"１０９ページの品川区史編さん経費を最初に聞きまして、その後、地域振興費についてお聞きしたいと思います。平成２３年度の内容、進みぐあい、それから現在の平成２４年度の進みぐあいについて教えてください。","respondent":"武内総務課長","answer":"平成２４年度に入りまして、その委員会の話、また内部の検討委員会を通じまして、大枠の項目等の内容が、大体でき上がってきているところですので、１１月に、学識経験者を踏まえた委員会を設置しまして進めていく予定になっております。","voiceIndex":160,"id":"exchange-067"},{"speaker":"本多委員","kind":"質問・要望","question":"これは要望も含めてなんですけれども、平成２６年度に完成するということなんですけれども、その前に中間報告というか、できれば議会に報告いただけないかと思うんですけれども、その点。それから、区史編さんの平成２６年度の完成に向けて、区内にあります大森貝塚の名称を、品川貝塚ですとか、大井貝塚ですとかに変えていただきたいと思うんですが、その辺について、お聞かせください。","respondent":"武内総務課長","answer":"大森貝塚という名称については、日本全国一般的に使われているものを、この審議会の会議の中で、品川貝塚だとかという名称が妥当なのかどうかという部分につきましても、学識経験委員のほうに、そういう声があったということを伝えて、検討していきたいと考えております。","voiceIndex":162,"id":"exchange-068"},{"speaker":"本多委員","kind":"質問","question":"前向きに、よろしくお願いいたします。次の１１４ページの地域振興費に移ります。町会・自治会館耐震診断実績が１件ということで、昭和５６年以前の新耐震の前のものが対象ということですけれども、この実績１件というのは、もう少し数が伸びるのかなという思いがあったんですが、その辺についてお伺いします。","respondent":"久保田地域活動課長","answer":"私どものほうにも、まだ件数としてはあらわれてはいませんけれども、実際にこういうのをやりたいといった声も幾つか挙がってきてありますので、そういった相談を今度は実際に耐震化、または改修のほうにつなげていけるように、町会の方々と話し合いをして。","voiceIndex":164,"id":"exchange-069"},{"speaker":"本多委員","kind":"質問","question":"ちょっと次の質問にいきます。そういうことなんですが、法人化の推進をしていくということなんですが、その辺の現況について、どういう感じでしょうか。","respondent":"久保田地域活動課長","answer":"法人になるということでも、町会の総会とか、意思決定等も必要ですので、そうした意味で、町会を法人化したいんだという話になりましても、それがすぐに法人化にいくかというと、それなりの手続を踏まなければならないので、多少時間が要りますし。","voiceIndex":166,"id":"exchange-070"},{"speaker":"本多委員","kind":"質問・要望","question":"ぜひ、推進を続けていただければと思います。同じく１１４ページの区政協力委員会経費について、お聞きします。これはたとえの話なんですけれども、区政協力委員は、地域からの意見や要望を区政運営に、ということでやられているんですけれども、監査委員は専門的にやっているから、ここに出ないということで、この決算特別委員会も、区政協力について専門的にやっているわけです。これは私だけでしょうか。","respondent":"久保田地域活動課長","answer":"区政協力委員は、町会長になっていただいておりますので、町会長の選任につきましては、任意団体の町会の中で決めていただいているです。","voiceIndex":168,"id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"希望者に対して支援をしていくわけですけれども、民生委員の方たちというのは、非常にその地域の実情を知っている、お一人で住まわれているとか、状況がよくわかっているということを考えると、逆に、民生委員の方々から情報を受け取って、こういう支援があるんですよという形でご紹介するという形で、コラボレートができるのではないかと思うんですが、その件についてのお考えをお聞きしたいと思います。","respondent":"原高齢者福祉課長","answer":"そういう意味では、現場を把握している民生委員が、どういった方が要援護者名簿に載っているかというところを把握できることによって、地域に根ざした防災活動ができると理解をしています。","voiceIndex":171,"id":"exchange-072"},{"speaker":"西本委員","kind":"質問","question":"そういうことではなくて、この支援の方法は、希望者がいて、希望者によってリスト化されるわけですよね。なので、逆にそちらから、こういう方たちもいますよと、これも個人情報になると思うので難しいところはありますけれども、そこの情報をお互いに共有化して、支援の申込みをされていない方を促進していくというか、進めていくという形はどうかと言っているんですが、いかがでしょうか。","respondent":"原高齢者福祉課長","answer":"そういう意味では、名簿にどういった方が載っているか、民生委員が把握することによって、民生委員が把握しているのに載っていないといったところが、当然わかるわけですから、そういった中で連携が図られれば、委員ご指摘の形に近づくと認識しています。","voiceIndex":173,"id":"exchange-073"},{"speaker":"西本委員","kind":"質問・要望","question":"そうではくなくて、必要な方はいらっしゃるわけですから、そこにアクセス方法がいくらでもありますので、そこは協働しながら、ぜひとも進めていっていただきたいと思います。その中では、やはり青少年健全育成というのは、各中学校に設置されていると思うんですが、それについて、どういう運営になっているのか、改善はされていくのか、これから拡充していくのかということについてのお考えをお聞きします。","respondent":"梶青少年育成課長","answer":"内容につきましては、品川区のほうでは、青少年問題協議会がありますので、そちらでの方針、青少年健全育成基本方針に基づいてやっているところですが、学校との連携に関しましては、例えば、夏になれば安全対策のチラシを配って、各小中学校の父兄の方々にお配りするとか。","voiceIndex":175,"id":"exchange-074"},{"speaker":"西本委員","kind":"質問","question":"青少年問題協議会というのはわかっておりますけれども、あれも、もっと突っ込んだ話ができればいいかなと思うんです。それについては、今は学校が中心的にやっているんですけれども、そうではなく、地域の方たちも含めて、実行委員体制などをとって、地域で青少年に対する育成を考えていこうという形に変えられるのではないかと、強化することができるのではないか思いますが、お考えはいかがでしょうか。","respondent":"梶青少年育成課長","answer":"連携のところでは、協議会はありますけれども、そこでの会議だけではなくて、その後もさまざまなところで情報交換をしていますので、その中で一体的にやっているところです。","voiceIndex":177,"id":"exchange-075"},{"speaker":"西本委員","kind":"質問・要望","question":"足りないと思います。今の現状では、感想として、認識不足だと思っていますし、地域の方たちはいろいろな方がかかわっているんですよ。地区委員にしても、青少年の地区委員もいらっしゃいますし、それぞれのところで活躍されている人、ＰＴＡの方たちもいます。じゃあ、それを取りまとめていくのはどこなんですか、ということなんです。","respondent":"梶青少年育成課長","answer":"個々について、また必要な部分については、それぞれ連携して話し合い等々情報交換をやっていくという形でつくり上げていきたいと考えているところです。","voiceIndex":179,"id":"exchange-076"},{"speaker":"西本委員","kind":"質問・要望","question":"この問題は学校だけの問題ではないです。やはり地域ぐるみでやっていかないと解決できない問題だと思いますので、ぜひ今後、推進していっていただきたいと思います。次に、品川区民芸術祭。今年のオープニングセレモニー、非常によかったと思います、感動しました。それから、今後、どういう形でこの芸術祭をやっていこうとしているのかを聞きたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"来年４回目を始めますけれども、新たな展開に向かって、今、実行委員会と皆さんとで協議をしています。","voiceIndex":181,"id":"exchange-077"},{"speaker":"西本委員","kind":"質問・要望","question":"五反田文化センターができて、非常にすばらしい施設なんですよね。あの施設をたくさん使っていただきたいという思いがあります。これからやはり、子どもたちがすばらしい演奏を聞くことによって、実際、自分たちも交わってみて、さらに目指していけるような会にしていただきたい、芸術祭にしていただきたいと要望したいと思います。","respondent":"久保田地域活動課長","answer":"ですから、町会によっては、自分たちが使いたいときに使えるような形でもいいといった声もありますので、例えば、今ご提案のあったようなほっとサロンの管理を任せてということも考えられるところはあるかとは思いますけれども、それが町会のニーズとマッチするかどうかは。","voiceIndex":183,"id":"exchange-078"},{"speaker":"西本委員","kind":"提案","question":"今、協働ということを出しておりますし、ウェルカムセンター原なんかも地域の方たちが運営するという形をとっているわけですから、それの応用みたいな形で、町会ができるかもしれないといった場合には、そういう方法も、手だても考えていただくことを、ぜひお願いしたいと思いますが、いかがでしょうか。","respondent":"久保田地域活動課長","answer":"そういうご提案ではありますけれども、それがほんとうにイコール町会のニーズと合うかどうかというのは、私どももいろいろ意見を聞いていかなければならないとは考えてありますけれども、今後の町会会館の所有に関してのメニューの一つではあるかなとは考えております。","voiceIndex":185,"id":"exchange-079"},{"speaker":"金野委員","kind":"質問","question":"私のほうからは、１１５ページの地域ふれあいサポート活動経費、二つ目には、１２２ページの消火器維持管理費、この二つをお伺いいたします。あるいは、消防署が設置をした消火器の設置場所は、区として把握されていらっしゃいますでしょうか。されていましたら、どのような方法でされているのか、その点を、まずお伺いしたいと思います。","respondent":"鈴木防災課長","answer":"街頭消火器のお尋ねです。大きく分けまして、委員からご指摘いただいた区が設置するもの、それからもう一つは、民間のほうで設置するものと、この２種類があります。","voiceIndex":188,"id":"exchange-080"},{"speaker":"金野委員","kind":"質問","question":"ある町会で防災訓練をされたときに、地域の方と、消火器が設置されている地図を頼りに、どこに設置してあるかという把握をしたときに、区が設置をしている地図と、それからもう一つ、そのときは消防署とお聞きしたので、私は消防署と言ったのですが、そこが設置をされている地図と２枚あるんですよと。この２枚を両方見ないと把握できないので、これは１枚にならないものですかねというご意見があったんです。","respondent":"鈴木防災課長","answer":"これにつきましては、町会の方がご覧になった地図が、ちょっとどこが出したものかわからないんですが、区のほうに問い合わせをいただければ、地区ごとに、どの位置に消火器が設置してあるかという情報は、お答えできるようにしております。","voiceIndex":190,"id":"exchange-081"},{"speaker":"金野委員","kind":"質問","question":"この点は以上です。そういう認識から、まず決算書の数字からお聞きしたいんですけれども、当初予算では、９０７万６,０００円という予算に対して、決算額は８０１万７,８４３円となっておりました。１００万円強減になっておりますけれども、どのような事業が行われ、この中には数々の事業がありますので、簡単で結構です、減の理由のほうを主にお聞きしたいと思いますけれども、よろしくお願いします。","respondent":"今井協働・国際担当課長","answer":"減の主な理由につきましては、昨年度実施いたしました、地域貢献団体感謝状の贈呈式の中で、表彰予定の数が下回りまして、感謝状、そしてそれに伴ってお渡しする経費の部分が削減されたということになっております。","voiceIndex":192,"id":"exchange-082"},{"speaker":"金野委員","kind":"質問・要望","question":"そうすると、その事業の中で、去年スタートしたのでしょうか、品川第二、荏原第二地域センターでモデル事業としてされております支え愛・ほっとステーション事業の状況を、教えていただきたい。利用者とか、また相談内容とか、事例とか、簡単で結構です。","respondent":"原高齢者福祉課長、今井協働・国際担当課長","answer":"中身ですけれども、ひとり暮らしの方々のちょっとした困り事に対応するということで、この事業を進めてあります。ただいま説明申し上げました荏原第二および品川第二地区の支え愛・ほっとステーション事業のほかに、全地域で訪問ボランティア事業という形で、地域センターが事務局となり、高齢者宅等を、地域のボランティアが定期的に訪問する。","voiceIndex":194,"id":"exchange-083"},{"speaker":"金野委員","kind":"質問・要望","question":"評価ではＢというふうに、継続となっておりましたけれども、これはまだまだ力を入れていただきたい事業ですので、その点を言いたかったんです、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-084"},{"speaker":"松澤委員","kind":"質問","question":"お願いのほうですけれども、１２２ページ、小・中学校消火ポンプ配備。この訓練なんですけれども、消防団が行っているんですけれども、訓練時間が４時ごろからということで、消防団も働いているものですから、その訓練をする方は大変限られて負担が大きいんです。これができると、団友会の方たちが使えて、相当助かると思うんですが、その辺について、お伺いしたいと思います。","respondent":"山口防災安全担当課長","answer":"ただし、どういう指導ができるか、どういう指導までできるかというのは、またいろいろ消防署、消防団の方に聞きつつ、なるべく指導できるような形で検討を進めたいと考えています。","voiceIndex":199,"id":"exchange-085"},{"speaker":"松澤委員","kind":"質問","question":"これは訓練限定ということで、この場なら、この保険が適用されるということで結構なんです。ふだんの消火活動に参加するということではありませんので、ひとつよろしくお願いします。それからもう一つは、このほど補正予算でスタンドパイプの配備が決まりましたけれども、まだ配備されてないんですよ。いつごろ配備されるのか、この点についてお聞きしたいと思います。","respondent":"鈴木防災課長","answer":"ですが、ご存じのように、今、スタンドパイプは大変に注目をされて、各方面から注文が殺到しておりまして、納期が４カ月ほどかかってしまうということを、メーカーから聞いておりますので、現在、手配はしておりますが、年末から年明けにかけて、全町会に配備できる予定で、今。","voiceIndex":201,"id":"exchange-086"},{"speaker":"松澤委員","kind":"質問","question":"いつこれは来るんですかと、それぐらい人気があるんです。それだけ地域の防災強化として役に立つと思うんです。そうすると、地域の方たち、１０人ぐらいずつまとまって、その現場で実際に水を出すところを訓練して、それから放水に向かうということで、大変に危険なんです、大勢な人数ですから、やはり人の邪魔になったり、車の通行で危険性が増すということで。あれは、訓練用消火栓というのがあるんです。","respondent":"鈴木防災課長","answer":"区としても、もし独自で購入できるものであれば、購入をいたしまして、区民の方に、スタンドパイプの操作方法について習熟していただくための講習会、訓練等も積極的に実施していきたいと考えているところです。","voiceIndex":203,"id":"exchange-087"},{"speaker":"松澤委員","kind":"質問","question":"区民のためになるということですので、できるだけ早くお願いをしたいと思います。２点目に入ります。１１４ページ、町会・自治会について。町会・自治会に参加している町会長は、区政協力委員会名簿に載って、区政協力員、それぞれ手当ても出るし、やめたときに表彰されるとか規定があるんですけれども、町会・自治会というものをつくるときに、町会・自治会は何ぞやという規定はどこにあるのでしょうか。","respondent":"久保田地域活動課長","answer":"例えば、ある方が、私はこの地域で町会をつくりたいということを言いましても、それは既存の町会等もありますので、勝手につくることはできないと、一般的に言われているところです。","voiceIndex":205,"id":"exchange-088"},{"speaker":"松澤委員","kind":"質問","question":"自治会を調べてみますと、一番小さい自治会は、何と２０世帯。あれも自治会なんですね。でもやはり、大きなマンションなら、こういうふうな形のときには、自治会をつくるということが可能ではないかと思うし、また実際にあるわけですから、可能だと思うんです。この点について、町会・自治会というものについて、マンションを自治会にすることについて、区の見解を、ちょっとお伺いしたいと思います。","respondent":"久保田地域活動課長","answer":"委員お尋ねの自治会というのは、集合住宅の自治会のことだと思いますが、集合住宅の自治会は、管理組合と違って、住んでいる方が自分たちの住んでいる地域のために活動するというものでございまして、そうした自治会を立てるということについても。","voiceIndex":207,"id":"exchange-089"},{"speaker":"松澤委員","kind":"質問・要望","question":"時間がないんですけれども、実は、ある町会で、このマンションが町会に入りたい、いやいやうちの町会の人数よりも多い人が来たら、町会を乗っ取られちゃうから嫌です、自治会をつくってくださいと言って、自治会をつくったところもあると聞いています。やはり自治会をつくると、区政に対する、我々区民なんだという意識が多いと思いますので、こういうことから考えても、少し考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":209,"id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１２１ページの防災対策について、お聞きします。地域防災計画なんですけれども、東京都の素案が発表されて、今度、品川区の計画の素案が出されてくるわけですけれども、ぜひ、この防災計画は実効性あるものにしていただいて、区民の命と財産を守れる防災対策を求めたいと思うんです。そういう立場で進めるということで、予防対策を徹底して行っていただきたいと思うんですけれども、いかがでしょうか。","respondent":"高山防災計画担当課長","answer":"災害において、予防等対策の重要性については、委員ご指摘のとおりですので、そういった部分の拡充については、十分図ってまいたいと考えております。","voiceIndex":211,"id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、自助、共助ばかりを強調するのではなくて、やっぱり予防対策というところで、公助をしっかりと、自治体の役割をしっかりと果たしていただきたいということを、まずはじめに求めたいと思います。それから、次に初期消火態勢の強化について、お伺いしたいと思います。こういうところに対して、区がどう働きかけ、充実をさせていくと考えているのか、お聞かせください。","respondent":"鈴木防災課長","answer":"それに基づいて、一般的には１００ｍ、特に対応が必要な木造密集地域であるとか、特殊な地域においては８０ｍという基準を設けて、既にその基準に適合するように設置を終えているところです。","voiceIndex":213,"id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民消火隊については、そういうことで、ぜひ区のほうからも強力に働きかけをしていただきたいと思います。何とか初期消火で市街地大火になるのを食いとめていく対策のためにも、まとめて消火器を置いて初期消火をしていく対策がすごく必要だと思うんですけれども、そこら辺の対策も、ぜひ求めたいのですが、いかがでしょうか。","respondent":"鈴木防災課長","answer":"それからまた、区の施設も、もうほとんどつけてしまったので、今後増える予定はないんですが、区の施設についても、できるだけ設置をするという方向で進めておりますので、その辺につきましては、今後も、町会の状況にあまり左右されずに。","voiceIndex":215,"id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ進めていただきたいと思います。それもあわせて、東京都のほうに求めていただきたいと思うんですけれども、いかがでしょうか。そのこととあわせて、お伺いします。１００％耐震化されている区も、ほかに５区ぐらいありまして、そういう点では、おくれているところも強力に進めていただきたいということで、あわせて求めていただきたいと思っているんですが、その理由もあわせてお聞かせください。","respondent":"鈴木防災課長、武藤河川下水道課長、高山防災計画担当課長","answer":"水道管に関しましては、地下に埋設している関係で、地盤と一緒に震動するということで。その結果、目標とする平成２７年度を２年前倒しして、来年度中には、避難所等全カ所耐震化する見込みです。トイレの耐震化に加えまして、いわゆる既設のトイレにつけるような化学薬剤を用いたトイレなども組み合わせまして、災害時のトイレの対応につきましては。","voiceIndex":217,"id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、木造密集の火災危険度の高い地域で、スタンドパイプが使えるような耐震化を求めていただきたいというのが一つです。それからもう一つは、避難所で、学校のトイレ、１階の１カ所だけではなくて、全部の水洗トイレが使える方向で、ぜひとも耐震化を進めていただきたいということで、もう時間が終わりなので、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":221,"id":"exchange-095"},{"speaker":"浅野委員","kind":"確認","question":"１１２ページのＷＥＢ映像館、１２２ページの防災行政無線管理費について、質問します。最初に、防災行政無線管理費ですけれども、それに関連しまして、携帯電話の緊急速報メールですけれども、３社ともそろって、もうできるようになっていると伺っておりますが、これは、３事業者同時に情報を流せるようになっているのかということを、一つ、お伺いしたい。","respondent":"荒井広報広聴課長、山口防災安全担当課長","answer":"私からは、携帯電話における緊急速報メールについて、お答えいたします。３社とも出揃いまして、ただし、私どもが同時に発信するような、瞬時に同じ秒数でというところまでは、まだいっていないです。私から、９月１２日のＪ－アラートの訓練結果について、補足で説明します。","voiceIndex":223,"id":"exchange-096"},{"speaker":"浅野委員","kind":"質問・要望","question":"国民保護計画によりますＪ－アラートを使っての自動放送というのは、自動的に操作盤の電源を入れたりして、すべて人手を介さずにできると伺っております。先ほど、緊急速報メールの件を伺いました。ここら辺、そういう意味では、防災行政無線を補完する重要な情報提供の手段と思いますが、なっていなければ、今後、どのようにされていくのか、方針について、お伺いしたいと思います。","respondent":"荒井広報広聴課長","answer":"メールマガジン、ツイッターにつきましても、現在のところ、Ｊ－アラートとは連動しておりません。今後、同時配信も含めて、連動が可能になるような方策の検討を進めているところです。","voiceIndex":226,"id":"exchange-097"},{"speaker":"浅野委員","kind":"質問","question":"緊急速報メールもそうですけれども、品川区のメールマガジンのほうも、多分、受け取れる方もおられると思います。次に防災テルてる、防災伝言板ですけれども、これはＣ評価で、見直しを図ると出ています。どのような見直しが図れるのかと、頭の中で考えますと、あとはもうＰＨＳしかないのかと、ふと思ったわけです。もし、今、お考えがあるのであれば、教えてください。","respondent":"鈴木防災課長","answer":"防災伝言板に関しましては、文字情報で一方通行であるというような制約があるというところで、現在、最新のいろいろな防災伝言板にかわるタブレットのような、機能を幾つか持った機種が出始めておりますので、今後、より確実にいろいろな情報のやりとりができる機器を選定して。","voiceIndex":228,"id":"exchange-098"},{"speaker":"浅野委員","kind":"質問","question":"ＷＥＢ映像館ですけれども、平成２２年度のアクセス件数については７万６,６５３件と伺っております。平成２３年度の実績について、お伺いします。いつでもは、パソコンで見れますから理解できるんですけれども、どこでもというのは、何を想定されているのか、この点についてお伺いします。","respondent":"荒井広報広聴課長","answer":"ＷＥＢ映像館についてのお尋ねです。平成２３年度のアクセス数につきましては、９万４,９８３件、月平均にしますと、７,９００件余になってあります。","voiceIndex":230,"id":"exchange-099"},{"speaker":"浅野委員","kind":"質問・要望","question":"これはぜひとも、ホームページのほうで対応していただけないかなと思います。このような方は随分増えておりますので、これはぜひとも検討していただきたいと思います。ともかく、これからは、こういうタブレット端末も含めまして、さまざまな機器が出そろってくるので、広く、どこでも、だれでも見ることができるような、それをさらに目指していっていただきたいと思いますが、ご答弁をお願いします。","respondent":"荒井広報広聴課長","answer":"ＷＥＢ映像館について、さまざまなご指摘をいただいたところです。それぞれについて、前向きな形で検討をさらに進めていきたいと考えています。","voiceIndex":232,"id":"exchange-100"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、１１０ページ、大きな意味での庁舎整備費と、１２２ページの災害時要援護者支援経費、それから、１０９ページの職員研修、政策課題研修について伺いたいと思います。ＪＲ東日本の社宅が平成２６年３月をもって廃止されると、地域の方から伺いました。この情報について、改めて伺いたいのと、区の対応はどうしているのかということも伺いたいと思います。その中で、民間からのアイデアを募集したと。","respondent":"鈴木防災課長、溝口都市開発課長、藤田都市計画課長、堀越人事課長","answer":"それからもう一つは、個人の資産に関することなので、その情報で価値が下がってしまうような影響が出るといけないということもありますので、現在。ＪＲの社宅を含めた今後の跡地利用ですが、今後につきましては、品川区とＪＲとで、月１回程度。品川駅周辺についてですけれども、品川駅周辺基盤整備まちづくり検討会、あるいは、検討委員会、あるいは、ワーキンググループというようなことで。この研修の過程の中で、さまざまな意見交換ですとか、議論ですとか、そういったやりとりを通じて。","voiceIndex":235,"id":"exchange-101"},{"speaker":"石田（秀）委員","kind":"提案","question":"何となく、私はわかるような気がする。それから、政策の部分は、私はぜひ実行していただきたいので、一つでもいいです、二つでもいいです、モデル事業でもいいです、始めることが、必ず若い方のやる気にもなるし、これは区長に頼むのかどうかわかりませんが、必ず一つでも、二つでも、モデル化でも結構ですので、予算を実現してほしいと思いますので、これに対する答弁をお願いします。","respondent":"溝口都市開発課長、堀越人事課長、鈴木防災課長","answer":"私どもは、ＪＲの言いなりになることなく、品川区の中心地でもある大井町の持続的な発展に向けたまちづくりができるように、庁内強力な連携体制を築いて。今、委員からご指摘いただきました、政策課題研修につきましては、能力向上ということ。避難ルートの際に必要な情報としての耐震の進捗状況、もしくは建物の状況の情報提供ですが、先ほど申し上げましたように、民間の部分に関しては、今。","voiceIndex":240,"id":"exchange-102"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"最初の部分のＪＲの部分は、ちょっと寂しい答えだなと考えています。それから、避けるルートって、私はこれだけはぜひ思ってほしい。今、この議論をするときに、命を守ることが大切なのか、民間の個人情報を守るのが大切なのか。それだったら、しっかり書き込むぐらいの気持ちがあったほうがいいと思うので、ぜひもう一度、そこは教えていただきたいと思います。","respondent":"片田都市環境事業部長","answer":"それ以外も建物もありますので、プライバシーのことも含めながら、ただ、安全を重視した中で、区としても必要な対応を考えていきたいと考えております。","voiceIndex":244,"id":"exchange-103"},{"speaker":"稲川委員","kind":"質問","question":"私からは、１１４ページ、地域振興費の中から地域活動費全般と、１２２ページの防災対策費の中から、区民消火隊の装備品整備等について、時間があれば戻りまして、１１０ページの庁舎等維持管理費に関連して、お伺いいたします。地域環境整備等助成金についてでありますが、環境整備費として２０４町会に助成金を交付していると思います。その算出方法についてお知らせください。","respondent":"久保田地域活動課長","answer":"町会に対する助成金ですけれども、私ども地域活動課のほうで出していますのは、１１４ページにあります地域美化推進補助とか、ふれあい掲示板、また、町会会館助成といったものがあります。","voiceIndex":247,"id":"exchange-104"},{"speaker":"稲川委員","kind":"質問","question":"その落差というのでしょうか、整備助成金についてで構いませんので、その落差がどれぐらいで、金額が離れているのかということを、お知らせください。さまざまなところから助成金が出るという話ですが、今、地域活動課長が全部お答えになったんですが、これは地域活動課のみなのか、防災課から出ているとか、そういうことがあるのかどうなのか、教えてください。","respondent":"久保田地域活動課長、鈴木防災課長","answer":"先ほど、私がご説明させていただきました助成金ですけれども、防災のほうにつきましては、所管課は防災課ですけれども、支給については、地域センターを通じて町会のほうに書類の手続等。概略で言いますと、その町会に関しては、町会の人口と、前年度の総合防災訓練への参加人数の実績、これを算定根拠にしまして、毎年度、補助金を出させていただいているという状況です。","voiceIndex":249,"id":"exchange-105"},{"speaker":"稲川委員","kind":"確認","question":"何カ所から、どういった補助金が出ているかということをお伺いしたのは、多分、一括して出るケースもあると思いまして、その内容を町会にはご説明いただいているとは思うんですが、実際に私も聞く話で、例えば「防災関係の備品を購入したいんだけれども、こういった補助金は区から出るのかな」と、「確認するけれども、実を言うと違う形で出ているんですよ」ということで。","respondent":"久保田地域活動課長","answer":"町会ハンドブックというものもつくりまして、お配りをして、ご理解をいただいているところですけれども、やはり、私ども足を運んで、きちんと説明をしなければならないと思っているところもありますので、来年度以降、そういった事業を。","voiceIndex":252,"id":"exchange-106"},{"speaker":"稲川委員","kind":"質問・要望","question":"ぜひ、その辺はしっかりと説明をしていただければと思います。言うまでもなく、活動が増えれば支出も増える。要は町会の負担が増えるです。ほんとうにいい意味で頑張っている町会には、それなりの助成金の交付ができる仕組みをしっかりと考えていただきたいのですが、改めて、ご答弁願いたいと思います。","respondent":"久保田地域活動課長","answer":"私どもも、町会の助成金につきましては、いろいろな算出で支給しているところですけれども、やはり、先ほど言ったように、説明が必要だというところと、もとになっている世帯の数とかも、ちょっと古い国勢調査の数とかを使っているところもありますので。","voiceIndex":254,"id":"exchange-107"},{"speaker":"稲川委員","kind":"提案","question":"ふれあい掲示板の管理費について、ちょっとお伺いしたいんですが、先ほど、塚本委員のほうからありましたので、要望にとどめておきますが、４００カ所以上あるということで、場所によっては、ほんとうに風が吹き抜けるような場所もあります。これは要望です。次に、区民消火隊の装備品等に関連して、お伺いをいたします。そして、紺色の活動服は、ある意味目立たず、作業服に見えてしまう。","respondent":"鈴木防災課長","answer":"こちらのほうの在庫は、今、３０人から４０人分ほど防災課のほうにあるというのが現状です。","voiceIndex":256,"id":"exchange-108"},{"speaker":"高橋委員","kind":"質問","question":"成果報告書１１２ページの広聴経費の区政モニター、ケーブルテレビ事業、それから、１１４ページの企画調整費、区有施設跡地活用等検討経費、それから、１２４ページ、行政サービスコーナー経費。ちょっと順番は後からになるんですが、１２４ページの行政サービスコーナー経費から質問します。利用者数の推移、そして、区として、このサービスコーナーをどう評価しているのかということをお尋ねいたします。","respondent":"井浦戸籍住民課長","answer":"地域センター全体で４０％という中で、その残りをすべてサービスコーナーということで実績が出てまいりますので、二つの小さな場所という点を考えますと、駅に近いということで、区民サービスということで有効なサービスを実施していると自負しています。","voiceIndex":261,"id":"exchange-109"},{"speaker":"高橋委員","kind":"質問・要望","question":"今、お話があったように、２カ所で１５％ということで、駅に近く、非常に利便性が高いということ、それから開いている時間も、利用者に非常に利便性が高いということで、区民の方々の評価も非常に高いとお聞きしています。窓口業務の対応でしょうか、それがちょっと、行った方にとって非常に迷惑があると。そして、区としては、その責任者にどのような責任というか、仕事を求めているのか。","respondent":"井浦戸籍住民課長","answer":"責任体制と、指揮系統についてのお尋ねです。職員構成としましては、総勢で２１名、現在あります。大井町が１２名、武蔵小山が９名。","voiceIndex":263,"id":"exchange-110"},{"speaker":"高橋委員","kind":"質問","question":"そこで、今、お話があったんですが、２１名で、大井町に１２名いらっしゃるということなんですが、常に１２人にいらっしゃるのではないと思います。大井町のほうに、同じ立場の方の中でチーフとかを決めてやられているのか、そういう認識でよろしいでしょうか。","respondent":"井浦戸籍住民課長","answer":"お尋ねの１点目ですが、常時３人から４人ずつ配置しております。そして、午前８時から午後７時までやっておりますので、シフト制をしいてあります。係長は本庁に在席しています。","voiceIndex":265,"id":"exchange-111"},{"speaker":"高橋委員","kind":"質問","question":"本庁の住民票係長が、いわゆる指揮をしているということですので、係長はほかの係もやられている方なのでしょうか、そうすると、守備範囲がすごく広くて、本庁からではなかなか目が届かないのではないかと思います。ですから、チーフやサブの方がいらっしゃるだけではなくて、監督の方がお一人でもいらっしゃったほうがよろしいのではないかと思うんですが、いかがでしょうか。","respondent":"井浦戸籍住民課長","answer":"あるいは、接遇の研修の強化というようなことも視野に入れながら、接遇についてのご指摘を頂戴しないように、区の窓口にふさわしい形での執行体制ということで、所管課長としてやっていきたいと考えています。","voiceIndex":267,"id":"exchange-112"},{"speaker":"高橋委員","kind":"質問","question":"いわばサービス業務ですから、そういった研修等も含めてお願いしたいんですが、平成２４年度の事務事業評価の結果のところに、区民ニーズに的確に対応し、より一層のサービス向上を図るため、効率的、効果的な運営に努めるというふうな結果が出ています。このサービスコーナーを民間事業者に委託するということは、法律上の問題があるのでしょうか。","respondent":"井浦戸籍住民課長","answer":"民間活力の導入という部分につきましては、他区の実施状況という部分も研究いたしまして、検討課題としていきたいと考えております。","voiceIndex":269,"id":"exchange-113"},{"speaker":"高橋委員","kind":"質問・要望","question":"ですから、評判がよければ区長の評判も、暇そうにしていると、区長も暇なのかと、サービスが悪ければ、区長もと、そんなことはないわけですよ。ですから、その顔を表現する場所でありますので、ぜひとも、先ほどの民間業者への委託、または研修をきちっとやっといただきたいと思います。この三つの点を踏まえて、今後、どのようにして施設の老朽化に対応していこうという計画があるのでしょうか。","respondent":"柏原行財政改革担当課長","answer":"ソフトの面につきましては、有効活用プランでも言っているんですけれども、なるべく新規で建てるものについての抑制であるとか、それから、既存建物の複合化であるとか、多様化とか、多目的化であるとか、そういったところで、有効的な活用を図れるように、ソフト面。","voiceIndex":271,"id":"exchange-114"},{"speaker":"高橋委員","kind":"質問","question":"今、抑制というお話もあったんですが、もう一つお尋ねしたいのは、ほかの自治体と共同で何かを使ったりすると、いろいろなハードルがあると思うんですけれども、そういった意味の広域化という視点、それからもう一つは、今、ソフトという言葉もあったんですが、民間施設を活用して、そこに補助金等を必要に応じて投入することによって抑制をしていく、そういった広域化。","respondent":"柏原行財政改革担当課長","answer":"委員ご指摘のあったとおりでございまして、例えば広域化等々についても、区の施設の有効活用、目的とか、お客様の層であるとか、そういったところを総合的に勘案して、もし可能な事案が出てくれば、検討する価値はあるんだろうと思ってあります。","voiceIndex":273,"id":"exchange-115"},{"speaker":"高橋委員","kind":"質問","question":"企画の方々はいろいろなお仕事があって、もちろんいろいろな活用プランなどをつくられていますから、かなりの発言をして中心になっていくと思うんですが、そういった既存の組織ではない形で、この施設について何か中心になっていくものを、これは行財政改革担当課長にお尋ねすることではないのかもしれませんが、その辺のお考えはいかがでしょうか。","respondent":"柏原行財政改革担当課長","answer":"実は、有効活用プランを立ち上げる際にも、庁内の中で検討組織といいますか、連携をとりながらつくってきたところです。そういったところを踏まえまして、今後もいろいろな施設の更新とかが出てきた場合には、庁内の連携を深めながら進めていくことになろうかと思います。","voiceIndex":275,"id":"exchange-116"},{"speaker":"高橋委員","kind":"質問","question":"それを、今度は区民の方々に、区の施設はこうなっている、こういう状態なんだと、今、老朽化の建物がこれだけあるというお話をされましたけれども、そういった形で施設白書とかいろいろな形で、別の形で整理してわかりやすく区民の方々に示していって、ご意見をいただく、あるいはこれから区がこういうことをやっていくということを説明していくというお考えはいかがでしょうか。","respondent":"柏原行財政改革担当課長","answer":"今、お話がありました、施設白書的なものというのはちょっとわかりませんけれども、このたび公共施設の有効活用プランというのを策定させていただきましたので、これをどういった形で公表できるかというのは、今、検討していますけれども、そういったところをベースにしまして。","voiceIndex":277,"id":"exchange-117"},{"speaker":"山元委員","kind":"質問・要望","question":"私からは、１２２ページの防災対策費の中の防災センター運営費、時間があれば、１１４ページの地域コミュニティ活性化助成金について、お伺いしたいと思います。最初に、防災センター運営費についてなんですけれども、昨年３月１１日の大きな東日本大震災からもう１年半がたちましたけれども、その当初から比べて、防災センターですけれども、来館者数を教えていただきたいと思います。そちらの内訳。","respondent":"鈴木防災課長","answer":"その内訳につきましては、区内の幼稚園、小学校、中学校、高校生、いわゆる児童・生徒、学生についてのご利用が約２，７００名程度、これは区内です。それから、区外につきましては３００名程度というご利用で、これが団体の主な利用の内訳になっております。","voiceIndex":280,"id":"exchange-118"},{"speaker":"山元委員","kind":"質問・要望","question":"特にシアターですけれども、平成６年にスタートしたと伺っております。この見直しということは、これからなので、具体的にどういうことかというのは、なかなか難しいかと思いますけれども、実際、どんなような予定というか、その範囲で結構です、わかれば教えていただきたい。","respondent":"鈴木防災課長","answer":"北区でも同様の防災センターを持っているんですが、北区は、実は一度リニューアルをしたという実例がありますので、そういうほかの自治体で参考になる施設の視察や情報収集も含めまして、現在の状況、それから今後のニーズを確認したうえで、来年度。","voiceIndex":282,"id":"exchange-119"},{"speaker":"山元委員","kind":"質問・要望","question":"２５万人がいらっしゃった、３人に２人というお話もありましたけれども、やはりお母様方とか、学校関係の方は平日オーケーだと思いますけれども、お仕事をなさっている男性、女性もそうですけれども、今、土日がお休みですので、土曜日か日曜日、いずれか開館をしていただければ、もっと意識が高まるのではないかと思いますのが、その辺もお考えいただきたいと思うんですが、いかがでしょうか。","respondent":"鈴木防災課長","answer":"１点目の見直しの検討会のメンバーについてです。こちらにつきましては、ご存じのように、防災シアターは、３Ｄの映像で壁が崩れたり、配管が落ちてきたりとか、特殊な構造になっておりますので、基本的には、検討については、専門家のコンサルへの相談が必要だと考えております。","voiceIndex":284,"id":"exchange-120"},{"speaker":"山元委員","kind":"質問","question":"一つ、言い忘れたんですが、３Ｄの映像を２本見させていただいて、感動して胸がいっぱいになったんですが、もし追加ができるのであれば、ぜひ津波関係の映像を流していただければと考えていますけれども、それは、今はご返事は無理ですかね、どうでしょうか。","respondent":"鈴木防災課長","answer":"３Ｄ映像の中で、津波の映像というご意見ですが、実は、３Ｄの映像をつくるのに１億円程度かかるですので、現時点では、ちょっと前向きに検討ということは難しいのですが、これも検討の中でちょっと考えさせていただきたいと考えております。","voiceIndex":286,"id":"exchange-121"},{"speaker":"須藤委員","kind":"質問・要望","question":"１１３ページの財産管理費、１２４ページの外国人登録費、１２５ページの区議会議員選挙費について、お尋ねいたします。区長は、そういう方向性を見せていただいたんですけれども、その後の進捗状況はどうなのかお聞かせいただきたいと思います。それから、この火災保険料というのは、地震の際の火災にも適用できるのかどうか。そのことを、まず教えてください。","respondent":"藤田都市計画課長、平澤経理課長","answer":"先般、あそこの土地は、区にとって、やはり防災上非常に有効な土地であるというような判断もありまして、区長名でＪＴのほうに、もし土地の売却を検討する場合については、ぜひ区に売ってほしいと、その中で、区として。きゅりあんにつきましては、区分所有ということになっていまして、ちょっと別の考え方で対応していますが、火災保険には加入しております。地震保険に入っているかどうかというお尋ねですが、地震については対象ではないです。","voiceIndex":289,"id":"exchange-122"},{"speaker":"須藤委員","kind":"意見","question":"先ほど来、防災に関していろいろなお話があったときに、やはり区のところが防火設備があれば、ある程度延焼は食いとめられるという仕組みになってこようかと思うので、耐震については、今までずっとやってきていただいたんですけれども、防火については、どういうふうに考えていらっしゃるのか。","respondent":"小林施設整備課長","answer":"それが防火には一番適していると思います。それから、あとは準耐火とかいろいろ方法はあるんですが、委員ご質問の防火に関しては、一応考慮しているということになっております。","voiceIndex":294,"id":"exchange-123"},{"speaker":"須藤委員","kind":"質問","question":"それから次に、外国人登録費では、住民基本台帳に移行がされてきているんですけれども、そのあたりで何か変わったことがあるのかどうか。それから同時に、そのことによって、品川区としては、外国人が土地を買ったりすることが、はっきりつかめるのかどうか、そのあたりを教えてください。つかめた場合、それをどうだということは、外へ個人情報で出せないという話になるのか、そのあたりも教えてください。","respondent":"井浦戸籍住民課長","answer":"住民票に対応するものが、法改正前は、外国人登録証明ということで、年間８,５００通ほどございまして、本庁では、月間８００通ほど発行しておりましたが、住民票になりましてから、お客さんが増えまして、増減率としては１８９％の増ということで、法改正前に比べまして。","voiceIndex":296,"id":"exchange-124"},{"speaker":"須藤委員","kind":"確認","question":"品川区での事前審査というのは、どういうふうになっているのか。そのあたりが、生活をした根拠が、３カ月以上あるないということを、どういうふうに判断をしているのか。単に申請書が来たら受理して、そのままなのか、その確認の仕方というのは、品川区ではどうしているのか。","respondent":"諸岡選挙管理委員会事務局長","answer":"ただいまのお尋ねですが、選挙管理委員会といたしましては、事前の審査につきましては、申請いただきました書類の基本的な文書についての管理、チェックということで、これまでどおりの対応です。","voiceIndex":298,"id":"exchange-125"},{"speaker":"須藤委員","kind":"意見","question":"今、各地で、事前に証明がない、電気の使用がどうだとか、水道の使用があったとかないというのは、ほかの市民とか、区民が訴える、そういう仕組みになってくるんですけれども、選挙管理委員会としては、そういうことがなければ、その辺の調査はしませんというのか、できませんというのか、そういう対応なのか。","respondent":"諸岡選挙管理委員会事務局長","answer":"現況におきましては、申し出をいただいた後に、選挙管理委員会としては調査を行うという体制です。","voiceIndex":300,"id":"exchange-126"},{"speaker":"南委員","kind":"質問","question":"１０９ページの人権啓発費に関して、お尋ねしたいと思います。そこで、質問したいんですけれども、教育委員会が、９月２６日に区立中学校の１年生の男子の生徒がいじめがもとになって自殺したということがあったと判断したのは、いつなのか。このいじめによって自殺者を出してしまったことについて、教育委員会としてどう考えているのか。その３点を、伺いたいと思います。","respondent":"太田指導課長","answer":"記事になったということも考えますと、私どもは、ご遺族の方のお気持ちを最優先に考えて対応してまいりたいと考えています。そういった意味においては、ご質問にもお答えするところなんですけれども、そこの点もご承知いただきたいと考えています。","voiceIndex":303,"id":"exchange-127"},{"speaker":"南委員","kind":"質問","question":"この委員会で質問はできるということになっているはずです。いかがでしょうか、委員長、そこのことを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":305,"id":"exchange-128"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、私は冒頭、教育委員会が作成したいじめの手引書には人権侵害について、こういうふうに書いてあるということを、まず紹介して、入っているんです。したがって、しっかり答弁してください。大事なことは議会の中で、この問題についてきちんと調査をしていくということ、そのことが大事で、調査の過程を明らかにしていただきたいことが、何が悪いんですか。ぜひ答弁していただきたいと思います。","respondent":"齋藤庶務課長","answer":"事案の中身につきましては、議長にご相談申し上げながら幹事長会などで、しかるべくご報告するというふうにお話をさせていただいたところですので、今日のところは、細かいことについては答弁は控えします。","voiceIndex":307,"id":"exchange-129"},{"speaker":"南委員","kind":"質問・要望","question":"答弁控えるというのは、実におかしいです。そういう判断は、教育的な立場からもおかしいし、区民の皆さんが求めている、そこからも反することであるということを指摘しておきたいと思います。それで、もう一度伺いますけれども、教育委員会が東京都の教育委員会へ、この問題についての報告はいつしたのか。教育委員会がいじめがあったと判断したのはいつなのか、その点について、しっかり答弁してください。","respondent":"齋藤庶務課長","answer":"繰り返しになりますが、現在、教育長が陣頭指揮に立ちまして、事案の解明に向けて、ただいま、努力していますので、いましばらく、答弁については控えします。","voiceIndex":309,"id":"exchange-130"},{"speaker":"南委員","kind":"質問","question":"実に、時間のむだで、私としては、すごく憤慨です。今までやってきたことについて聞いていることを、なぜ答えられないのか。なぜ答えられないんですか、答弁してください。","respondent":"齋藤庶務課長","answer":"繰り返しになります。昨日、教育長から、決算特別委員会の冒頭、貴重なお時間をいただきましてご説明したとおり、事案の中身、軽重から考えて、軽々にご答弁申し上げることは適切ではないと考えております。しかるべき時期に議長に相談させていただいて、議会にも情報提供します。","voiceIndex":311,"id":"exchange-131"},{"speaker":"南委員","kind":"質問","question":"人権の問題に関して、人権啓発費のところで聞かないで、どこで聞くんですか、委員長。この質問はしてはいけないこと、委員長は人権の問題について、人権侵害があったと規定しているんですよ。その問題について、人権啓発費のところで聞いて何が悪いんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":313,"id":"exchange-132"},{"speaker":"南委員","kind":"質問・要望","question":"いいですか、答弁をしていただけるように、委員長からも働きかけをしていただきたいと思います。そのことを申し上げて、質問したいと思います。東京都への報告については、していないんですか。","respondent":"齋藤庶務課長","answer":"ご質問の件につきましても、しかるべき時期に、しかるべくお答え申し上げます。","voiceIndex":315,"id":"exchange-133"},{"speaker":"南委員","kind":"質問","question":"非常に不誠実過ぎますね。一人の子どもが、東京新聞によると、自分の夢があったと、小学校のときの卒業文集に書いたその中身を紹介しています。その中身を見ると、ほんとうに胸が潰れる思いで、私は読みました。あのいじめた、自殺をした……そんなことを言うのであれば、後で質問してください。黙って聞きなさい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":319,"id":"exchange-134"},{"speaker":"南委員","kind":"質問","question":"記者会見を、私は開くべきだと思っています。しかも、今まで調査した中身でわかった事実をしっかり示して、こういうふうな事実がわかりましたと、これについて、こういう対応をしてきましたけれども、こういうことですということをきちんとわかるように、一刻も早く、そこはするべきだと思います。それについては、いかがですか。","respondent":"齋藤庶務課長","answer":"遺族の方も含めて、誠実に対応したいと考えていることは、私どもの本意です。記者会見につきましては、考えておりません。","voiceIndex":323,"id":"exchange-135"},{"speaker":"南委員","kind":"質問","question":"この問題でも、非常に区民の皆さんが関心を持ち、そして、当該の父母、生徒は、とりわけ非常に不安を感じておられると思います。そういう状況のときに、何も答えを出してあげない、そういうことでいいのでしょうか。なぜやらないのですか。考えていないという理由は何でしょうか、もう一度、尋ねたいと思います。","respondent":"齋藤庶務課長","answer":"繰り返しになりますが、昨日、教育長からご説明したとおり、今、事案の解明と再発防止に向けて全力を挙げております。したがいまして、得られた情報につきましても、しかるべき時期に議長にご相談申し上げて、議会にもお伝えいたします。これの繰り返しになりますが、以上です。","voiceIndex":325,"id":"exchange-136"},{"speaker":"南委員","kind":"質問・要望","question":"この決算特別委員会の場面で、議長を通じてやるなどという、そういうことを理事者側が言っていいのでしょうか。したがって、この件については、委員長の見解も伺わせていただければ伺いたいと思っています。区長と、教育長、どちらでもいいんですけれども、会見をやる予定はないのか、もう１回、このことについて伺います。","respondent":"齋藤庶務課長","answer":"会見を行う予定はございません。","voiceIndex":327,"id":"exchange-137"},{"speaker":"南委員","kind":"意見","question":"重ねて同じことを聞いているわけですけれども、いつも一つの答えしか返ってこない。この間の８月２０日の文教委員会で、数にはあらわれている、区が掌握しているこの数字、ここのバックには、もっともっとたくさんの数字があると思うんですけれども、こういう方々、今実際にいじめを受けて苦しんでいる子どもたちにも、希望を見失わせる言動だと思うんです。そういう認識はありますか。","respondent":"太田指導課長","answer":"それ以上のことやその他のことについては、調査結果がまとまった段階できちっとしかるべく、ご遺族の方にもきちっとご説明をし、そういった手順を踏みながら対応していくことが大切なことだと考えておりますし、そういったことで。","voiceIndex":329,"id":"exchange-138"},{"speaker":"南委員","kind":"質問","question":"どんな言葉を重ねて誠実だとおっしゃっても、こういう態度をとり続ける限りは誠実なんて、だれが思うんですか、だれも思わないですよ。品川区と品川区の教育委員会は、子どもを守ってくれるんだと、そういうふうに思えないと思います。子どもを守る姿勢があるんですか、もう１回、問いたいと思います。","respondent":"太田指導課長","answer":"あります。","voiceIndex":331,"id":"exchange-139"},{"speaker":"南委員","kind":"質問","question":"あるというのであれば、胸を開いて、わかった具体的な事実をきちんと議会の中に報告する、そのことが子どもを守るということにつながるのではないですか。それから、いじめ等調査特別委員会に第三者が一人も入っていません。これは入れるべきだと思いますが、その点について、いかがでしょうか。","respondent":"太田指導課長","answer":"ご意見として伺っておきます。","voiceIndex":333,"id":"exchange-140"},{"speaker":"南委員","kind":"意見","question":"甚だ不満足です。そして、私はちょっと、もう信頼を失いかけています。大津市の対応が問題になってきておりますけれども、その繰り返しになってしまうのではないかということを非常に危惧します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":335,"id":"exchange-141"},{"speaker":"井上委員","kind":"質問","question":"私は、成果報告書の１１１ページの市町村との交流事業と、１０９ページの人権啓発、事項別明細書９４ページの選挙管理委員会費について、お伺いいたします。品川区が人権尊重都市宣言をしてから、来年には２０周年を向かえます。全庁的な人権尊重意識の啓発について、区ではどのように対応されているのか、伺います。","respondent":"中山人権啓発課長","answer":"人権啓発というのは、私ども人権啓発課だけでできるものではございませんので、人権に関係するような各課の委員に一堂に集まっていただきながら、全庁的に啓発を進めているです。","voiceIndex":337,"id":"exchange-142"},{"speaker":"井上委員","kind":"質問","question":"障害者基本法が改正、公布されて、この中で差別の禁止、第４条の２で、「社会的障壁の除去はそれを必要としている障害者が現に存し、かつ、その実施に伴う負担が過重でないときは、この実施について必要かつ合理的な配慮がされなければならない」と示されています。例えば、区の封筒に決められたところに穴をあけるとか、全庁的な対応が工夫できないかと考えますけれども、これについて、いかがでしょうか。","respondent":"永尾障害者福祉課長","answer":"ただ、区の出す封筒についてすべてわかるようにするというのは、経費の面でも非常に厳しいものがありますし、すぐにやるということは難しいところですけれども、現在、障害者福祉課のほうで、視覚障害者の方に出すものについて、すべて手で印しをつけて出しているところです。","voiceIndex":339,"id":"exchange-143"},{"speaker":"井上委員","kind":"質問・要望","question":"私は、障害者福祉課に求めているのではなくて、全庁的に人権の意識ということで、その社会的障壁を除くということを、姿勢として示してほしいということです。社会的障壁を除くということ、それを求める方たちがいて、封筒に穴をあけて納入してもらうということが、区として負担が過重な範囲なのかということを、改めてお伺いしたいと思います。","respondent":"中山人権啓発課長","answer":"全庁的に、というお話です。例えばホームページにつきましても、今少しずつ音声対応が始まっておりますし、いろいろなパンフレットにつきましても、例えば介護保険のパンフレットですとか、視覚障害の方にも関係の深いものについては、対応が始まっているところです。","voiceIndex":341,"id":"exchange-144"},{"speaker":"井上委員","kind":"提案","question":"それをぜひ、品川モデルとして全国にも普及していただくということもできるのではないかと思います。これは一つの提案ですので、もっとよい方法があるとすれば検討していただき、人権尊重都市宣言２０周年を迎える来年に、ぜひそういった形で、区としても積極的に取り組んでいただきたいということで、ここは要望にしておきますので、何らかの検討を、ぜひお願いしたいと思います。","respondent":"諸岡選挙管理委員会事務局長","answer":"平成２３年度の選挙管理委員会の開催等に関してです。平成２３年度につきましては、定例会が２３回、臨時会が５回、その他の関係機関との会議が３９回ございまして、ご出席いただいております。","voiceIndex":343,"id":"exchange-145"},{"speaker":"井上委員","kind":"質問・要望","question":"今、答弁をいただきました回数、品川区の委員報酬が、４人で１,２１４万４,０００円ですから、単純に委員会開催２８回で報酬を割り返すと、相当乱暴な計算ではありますけれども、１回１０万８,４３０円ということになります。新宿区は、月額報酬を日額報酬にして、１回３万５,０００円ということだったと思います。","respondent":"諸岡選挙管理委員会事務局長","answer":"行政委員の報酬等につきましては、私どもでつかんでいる状況としましては、日額制への変更をしているところは２区程度と考えています。１区につきましては、日額と、それから月額の併用ということで聞いております。","voiceIndex":345,"id":"exchange-146"},{"speaker":"井上委員","kind":"質問","question":"昨年の決算特別委員会で、こういった問題について、私も指摘をしていますけれども、これは条例に沿ってということなので、条例改正も必要な案件ではありますけれども、こういった行政改革の一環として、日額報酬に向けて検討をする、そういう時期もあるのではないかと思いますが、今後、品川区として何かお考えがあれば、教えてください。","respondent":"諸岡選挙管理委員会事務局長","answer":"したがいまして、現状において変更する必要性は感じてございません。","voiceIndex":347,"id":"exchange-147"},{"speaker":"井上委員","kind":"質問","question":"次は、１１１ページの市町村交流事業ですけれども、広報「しながわ」で定期的に交流事業のお知らせが結構載っていると思います。特に早川町で言えば、イベントだけではなくて、サポーターの呼びかけなども行われおり、民間での交流も進められていると思っています。事業評価ではＣ判定ですが、今後、どのような見直しを考えていらっしゃるのか伺います。","respondent":"久保田地域活動課長","answer":"私どもも、今は直営という形でやってありますけれども、さまざま民間の活力とかを活用している時代ですので、こうした中でも、区民とか、また民間企業とかと連携した事業展開ができるかどうかということを考えていきたいという意味で、Ｃ評価をつけたものです。","voiceIndex":349,"id":"exchange-148"},{"speaker":"井上委員","kind":"質問・要望","question":"わかりました。それから、延べ人数ではなく、実人数を教えていただきたいと思います。それから、こういった補助金をつけて、品川区民が早川町に宿泊することは、何か政策的なメリットがあって行われているものなのか、そこもあわせて教えてください。","respondent":"久保田地域活動課長","answer":"実人数ですけれども、Ａさんが年間何泊泊まったかということですけれども、ちょっとそういった集計はしてございませんので、ここでお答えすることはできませんが、私ども担当者も含めて感覚的なお話でいきますと、３泊が限度ですから。","voiceIndex":351,"id":"exchange-149"},{"speaker":"井上委員","kind":"意見","question":"ただ、潤沢にお金がある時代ではなくなってきた昨今ですので、こういった補助金の使い方は見直しをしていくべき問題でもあるだろうと、全庁的なことも言えますが、そういったところを進めていかなければいけない今の時代であるということを、意見として述べて終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":353,"id":"exchange-150"},{"speaker":"須貝委員","kind":"質問","question":"私は、１２１ページ、防災対策全般についてお聞きしたいと思います。先ほどからもお話がありましたが、区の防災、減災への取り組みについて、さまざま、先ほどお聞きいたしました。そこでお聞きしますが、区では、放射能汚染に対する防災、減災対策は始めているのでしょうか、お聞きします。そして、これに対する危険度をどの程度考えているのか、認識しているのかお聞かせください。","respondent":"野呂瀬環境課長","answer":"放射線につきましては、今現在は、そんなに心配ない、今後どうするのかにつきましては、今、環境計画を策定しておりまして、その中に、どういう形であるかは別ですけれども、放射能という項目も取り入れながら、その中で検討してまいりたいと、このように考えております。","voiceIndex":355,"id":"exchange-151"},{"speaker":"須貝委員","kind":"質問","question":"前回、一般質問で申し上げましたが、実際、チェルノブイリ原発事故でも、爆発により放出されたヨウ素１３１を子どもが被爆して、子どもたちの甲状腺に取り込まれ、４年後には、子どもたちの間で甲状腺がんが急増した。その周りも、一部退去させられました。離れているといって、周りがほとんど汚染されて、放射能が飛散された場合、そうしたらどうするんですか。そうしたら、今、何が一番怖いんですか。","respondent":"工藤生活衛生課長","answer":"そういった中で、また、新たな知見といった部分が示されましたら、区としても対応ということになりますけれども、今のところ、国のほうからそういった知見、指示等はございません。これが、現状です。","voiceIndex":357,"id":"exchange-152"},{"speaker":"須貝委員","kind":"質問","question":"これは国の問題ですから、品川区がとやかく、ああせいこうせいと言うわけにはいかない。手の届かないところにあります。ですが、実際に、これから原発がまた稼動しつつある、また、１基つくり始めるという状況で、区民の生命財産を守るというのは、これは区の仕事ですよね。そっちはそっちでやっている、やっていることはしようがないとしても、我々でどうしろっていったって、法律もつくれません。","respondent":"野呂瀬環境課長","answer":"こういうことを、これからも引き続きとっていくことが、一番区民に身近な自治体の役割だと、私は考えております。","voiceIndex":359,"id":"exchange-153"},{"speaker":"須貝委員","kind":"意見","question":"今、そのように環境課長はおっしゃいましたが、品川区が自分の家族で、区長がお父さんで一家を支えているということならば、どうしよう。これは、国の政策だからとめようがない。そういうときに、いや区としてはこういう対応策、こういう施策を考えていますと、やっぱりそういうふうにやっていただけると、私は区民もほんとうに安心すると思うんですが、その辺、もう１回、お聞かせください。","respondent":"野呂瀬環境課長","answer":"国は国でやりますけれども、区は区でしっかりと共助に向かって、委員の皆さんの力を借りながら、また我々職員も区民の皆さんと一緒になって取り組んでいきたいと考えております。","voiceIndex":361,"id":"exchange-154"},{"speaker":"須貝委員","kind":"意見","question":"今、共助ということで、自助ということもありますけれども、それは、皆さんそれぞれやられると思うんですよ。建物に対しても、何に対しても、それは今でも多くの方がやられていると思います。言ってもあれかな、何かもう一つありましたら。","respondent":"野呂瀬環境課長","answer":"ですからやはり、生活する中ではリスクがある、それはあるんですけれども、その中でどう折り合いをつけていくか、そこのところを、今後も考えていくことが重要かと考えています。","voiceIndex":363,"id":"exchange-155"},{"speaker":"若林委員","kind":"質問・要望","question":"四つ挙げてしまいましたので、一つ一つ、お一人ずついくと時間がかかりますので、できればまとめて、こういう課題があって、平成２５年度に向けてはこういうふうにやっていきますというお話を、ひとつお聞かせいただきたいと思います。ここら辺の分析を、もう１点、お聞きしたいと思います。最後には、１２１ページの防災対策費は、後のほうで聞きたいと思います。","respondent":"本城企画財政課長、荒井広報広聴課長","answer":"そういう意味で、不用額が発生したそれぞれの原因を、これから精査しまして、平成２５年度の予算編成の中で、きちんと精査したうえで、来年度に向けて対処していきたいと、全般的には考えているところです。そういったことが原因かということで考えているところです。","voiceIndex":366,"id":"exchange-156"},{"speaker":"若林委員","kind":"質問・要望","question":"毎月１日発行の広報「しながわ」に、この区民相談のご案内が載っております。それからもう一つ、先日、１０月１日に品川区功労者表彰に出させていただきまして、大変にすがすがしい式典でございました。条例上、施行上、そういうふうになってくるのかどうかというのを、一つお聞きしておきたい。","respondent":"荒井広報広聴課長、武内総務課長","answer":"広報紙につきましては、紙面が限られていて、毎回、そういった丁寧なご案内をするのはなかなか難しいかとは思いますが、できる範囲で、相談の内容、こんなことがという例文を挙げるような形を考えて、工夫をしていきたいと考えています。表彰の関係ですけれども、法律相談員を１０年やっていただくと、普通表彰ということで、そのほかの相談員ですと、区民相談員、外国人生活相談員等、要綱で決めております。","voiceIndex":369,"id":"exchange-157"},{"speaker":"若林委員","kind":"質問・要望","question":"ではまた、今後、その年数と対象になった場合には、しっかりと表彰できるかもしれないと、受けとめておきます。それから、あと２分で、防災対策費。その中で、建設防災協議会という団体があります。もう一つの質問で終わっちゃいますけれども、これはどういう団体なのかということをお聞きしておきたいと思います。区とか区民にとってどういう存在なのか、そのところについてお答えいただきたいと思います。","respondent":"鈴木防災課長","answer":"具体的には、この間の台風のときもそうだったんですが、災害時の応急本部を設置したときの見回り、もしくは倒木や道路の欠損等の対応というようなところを実際にお願いする部隊ということで、日ごろから災害に協力をいただいている団体です。","voiceIndex":372,"id":"exchange-158"},{"speaker":"大沢委員","kind":"質問・要望","question":"１１５ページ、品川区民芸術祭経費、それから上の歩行喫煙防止推進経費、それから、ページが移りまして、１２１ページの防災対策費ということでお伺いしたいと思います。最初に区民芸術祭を質問します。一昨年から区民芸術祭が始まったということで、過去２回開催をされた。","respondent":"安藤文化スポーツ振興課長","answer":"１回目につきましては、暗中模索をしながらやってまいりました。そんな中で、一つは区民の参加イベントとして、区民の方々が企画をして、そこで発表をする、もう一つは、質の高いものを区民に提供していくと、この二つの面をやってまいりました。","voiceIndex":375,"id":"exchange-159"},{"speaker":"大沢委員","kind":"質問","question":"今、区民参加ということ、非常に盛り上がりがあるというご答弁をいただいたんですけれども、盛り上がりがあるのであれば、見直しをする必要はない、継続すべき事項で、この評価は変わってくると思うんですけれども、そこのところをどういうふうに捉えて、この評価を下したのでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"この見直しについてですが、従来、区民参加型イベントは、かつての文化フェスティバルというところからずっと引っ張ってまいりました。","voiceIndex":377,"id":"exchange-160"},{"speaker":"大沢委員","kind":"質問","question":"この期間について伺いますけれども、今年度においても、９、１０、１１月、３カ月ということで、それでいいのですね。","respondent":"安藤文化スポーツ振興課長","answer":"区民参加型イベントの期間のことですね。来年度以降、どのような形で区民参加型イベントを盛り上げていって、期間をどのような形にしていくかということも、今後、皆さんと協議をしていこうと考えています。","voiceIndex":379,"id":"exchange-161"},{"speaker":"大沢委員","kind":"質問","question":"期間のことなんですけれども、やはり祭ということで、私が考えるに、長いのではないかと。３カ月ではあまりにも長い、お祭りというからには、やはり今日あって、明日、花のように消えていくお祭りが一番いいと思うんですけれども、この期間について検討されるようなご予定はありますでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"ただいまご指摘いただきました期間については、実行委員会のほうでも、それを取り上げまして、集中的に論議をしています。ですから、来年以降につきましては、期間の集中化も含めて、今、鋭意検討しています。","voiceIndex":381,"id":"exchange-162"},{"speaker":"大沢委員","kind":"質問・要望","question":"次に防災対策に移ります。今、５日まで、東京都でパブリックコメントを行って、１１月以降にその計画が出てくるということで認識をしております。１００％なのか、それとも品川区という立地特性を考えながら、いろいろなものを取捨選択し、品川区独自の防災計画を立てていかれるのか、そこら辺の方針を教えていただきたいと思います。","respondent":"高山防災計画担当課長","answer":"災害対策上の計画の中では、大きく防災基本計画という国の最上位の計画を筆頭に、東京都の地域防災計画、そして、品川区の地域防災計画といった形の三層構造となっておりまして、品川区の地域防災計画を改訂するにあたっては。","voiceIndex":383,"id":"exchange-163"},{"speaker":"大沢委員","kind":"質問・要望","question":"これは、９月でしょうか、練馬区の駐屯地のほうから、歩行でこちらのほうまで来たと。過日の東日本大震災をはじめとして、いろいろな部分で、世界で自衛隊は災害復興で活躍しているんですけれども、これは自衛隊ですから、確かに国なんですが、区の場合、どれだけの範囲で自衛隊と連携をとれるのか。はとっていくのか、教えていただきたいと思います。","respondent":"高山防災計画担当課長","answer":"自衛隊との関係性ですが、品川区の防災会議のメンバーです。したがいまして、発災時につきましては、東京都への要請のもと、自衛隊の協力態勢ということに関しましては、十分な連携がとられていると考えております。","voiceIndex":385,"id":"exchange-164"},{"speaker":"大沢委員","kind":"意見","question":"品川区では既に、警察、消防では、課長をお招きをして連携を密にとってやっております。自衛隊については、ここの部分、どのように考えられるのか。区の一つのこまとして、自衛隊の方、プロフェッショナルとしての知見などをうかがうべく、そのようなポストといいますか、組み入れるような考えはどうなのか、そこのところの考えを聞かせてください。","respondent":"堀越人事課長","answer":"警察、それから消防、自衛隊と、さまざまな機関と連携を強め、区民の安全・安心を守っていくのは非常に大切なことです。自衛隊との、そういう人事の面での交流についても、さまざまな方向性、可能性を検討していきたいと考えております。","voiceIndex":387,"id":"exchange-165"},{"speaker":"大沢委員","kind":"質問・要望","question":"次、歩行喫煙に移ります。品川区内、５カ所ということで、過料および制限が設けられている駅、大井町駅、青物横丁駅、五反田駅、大崎駅、武蔵小山駅ということになっていますが、ここで設けている制限とは、どのような制限なのか。知っていますけれども、改めてお答えいただきたい。","respondent":"中川原地域振興事業部長","answer":"今、５駅を重点地区と定めまして、そこでは、歩行喫煙禁止ということでお願いしているものです。","voiceIndex":389,"id":"exchange-166"},{"speaker":"大沢委員","kind":"質問","question":"歩行喫煙並びに、下に貼ってある路上喫煙はどうなんでしょうか。","respondent":"中川原地域振興事業部長","answer":"路上喫煙も禁止ということで、お願いしております。","voiceIndex":391,"id":"exchange-167"},{"speaker":"大沢委員","kind":"質問・要望","question":"私は矛盾を感じるのです。路上喫煙が禁止である、しかしながら、駅周辺にはたばこを吸う場所がある。これは、路上で禁止なのに、なぜそこの１点の吸う場所があるのか。ここのところの矛盾は、どういうふうにお考えになったのか。決してたばこを吸う方に対して、否定をしているわけではありませんが、そこのところを、路上喫煙が禁止なのにもかかわらず、なぜそこでたばこが吸えるのか、教えていただきたい。","respondent":"中川原地域振興事業部長","answer":"そういうところなんですけれども、喫煙する方のご希望もあり、歩きながら吸うと、子どもとかに対して危険だということもありまして、歩きながらはやめてください、そして、この重点地区ではたくさんの方が通りますので、ここに限って。","voiceIndex":393,"id":"exchange-168"},{"speaker":"大沢委員","kind":"質問","question":"この置く場所は任意だと思うんですけれども、路上喫煙が禁止なのに、何でそこでたばこを吸えるんですかというお話です。そこのところを、決まりをもうちょっと整理をしておかないと、私みたいにまた言うやからも出てくると思うんですけれども、どうでしょうか。","respondent":"中川原地域振興事業部長","answer":"原則は禁止ですが、禁止の解除という形で、そこだけ解除をさせていただいています。","voiceIndex":395,"id":"exchange-169"},{"speaker":"大沢委員","kind":"質問","question":"禁止の解除というのは、解除指定はされているのでしょうか、教えてください。","respondent":"中川原地域振興事業部長","answer":"一応、道路許可とかを取りまして、そこだけは、ということで区が指定をしています。","voiceIndex":397,"id":"exchange-170"},{"speaker":"大沢委員","kind":"質問・要望","question":"確かに駅前は人通りが多いし、往来も多いです。駅からおりてきて、ちょっと一服って、品川区からまた次へ行くというところがありますけれども、歩行者は、逆にそこの部分が、いっときに場所を集約しているのであれば、かなりのにおいとか煙とかもあるわけでして、そこら辺のところもちょっと考慮しながら、喫煙場所の指定なり、立地条件を考えていただきたいと思うんですけれども、いかがですか。","respondent":"中川原地域振興事業部長","answer":"どういう形でマナーアップしていただこうかという作戦を練り直さないと難しいというところで、考えているところです。","voiceIndex":399,"id":"exchange-171"},{"speaker":"大沢委員","kind":"質問・要望","question":"この問題、マナーアップですから、やはり１足す１が２になる問題ではありませんので、そこら辺のところを十分にお考えのうえ、マナーアップ運動を続けていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":401,"id":"exchange-172"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1358#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":114720,"voices":402}}]);
